export function SetupAssistant({ streams, onAlertsSaved, onOpenServiceOperation }: { streams: StreamListItem[]; onAlertsSaved: (document: AlertsDocument) => void; onOpenServiceOperation: () => void }) {
  const { runtime, replaceRuntime, restartPending } = useRuntimeStatus();
