  const [selected, setSelected] = useState<string[]>([]);
  const [decodeAsProtocols, setDecodeAsProtocols] = useState<Record<string, DecodeAsProtocol>>({});
  const [selectorEndpoints, setSelectorEndpoints] = useState<Record<string, string>>({});
  const [showConfiguredCandidates, setShowConfiguredCandidates] = useState(false);
  const [candidateQuery, setCandidateQuery] = useState("");
  const [captureQuery, setCaptureQuery] = useState("");
  const [interfaces, setInterfaces] = useState<InterfaceListItem[]>([]);
  const [preview, setPreview] = useState<SetupPreview | null>(null);
  const [profiles, setProfiles] = useState<SetupProfile[]>([]);
  const [profileName, setProfileName] = useState("");
  const [message, setMessage] = useState("Loading setup state…");
  const [busy, setBusy] = useState(false);
  const load = () => { setBusy(true); void Promise.all([getSetupState(), getSetupProfiles(), getInterfaces().catch(() => [])]).then(([next, nextProfiles, nextInterfaces]) => { setState(next); setProfiles(nextProfiles); setInterfaces(nextInterfaces); replaceRuntime(next.runtime); setDraft({ revision: next.revision, capture: next.capture.document, protocolMap: { path: next.protocolMap.path, document: next.protocolMap.document }, alerts: next.alerts.document }); setPreview(null); setMessage(""); }).catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to load setup state")).finally(() => setBusy(false)); };
  useEffect(load, []);
  const allCandidates = useMemo(() => buildCandidateBundles(streams, decodeAsProtocols), [streams, decodeAsProtocols]);
  const suppressedCandidateKeys = useMemo(() => new Set(allCandidates.filter((candidate) => isConfiguredBundle(candidate, draft?.protocolMap.document.protocols ?? []) || isShadowedGenericBundle(candidate, allCandidates)).map((candidate) => candidate.key)), [allCandidates, draft?.protocolMap.document.protocols]);
  const candidates = useMemo(() => showConfiguredCandidates ? allCandidates : allCandidates.filter((candidate) => !suppressedCandidateKeys.has(candidate.key)), [allCandidates, showConfiguredCandidates, suppressedCandidateKeys]);
  const selectedCandidates = useMemo(() => allCandidates.filter((candidate) => selected.includes(candidate.key) && candidate.protocol && selectorEndpointFor(candidate, selectorEndpoints[candidate.key])), [allCandidates, selected, selectorEndpoints]);
  const srtEndpointMigrations = useMemo(() => findSrtEndpointMigrations(draft?.protocolMap.document.protocols ?? [], allCandidates), [allCandidates, draft?.protocolMap.document.protocols]);
  const visibleCandidates = useMemo(() => candidates.filter((candidate) => candidateMatches(candidate, candidateQuery)), [candidates, candidateQuery]);
