  if (!state || !draft) return <PaneFrame className="maintenance-frame" header={<PaneHeader title="Setup Assistant" icon="maintenance" meta="Initial configuration and safe reconfiguration" />}><div className="maintenance-intro">{message}</div></PaneFrame>;
