  const targetIds = new Set(targets.map((target) => target.id));
  const orphanedBindings = draft.alerts.bindings.filter((binding) => binding.scope.kind === "managed_target" && !targetIds.has(binding.scope.target_id));
  const updateDraft = (patch: Partial<SetupDraft>) => { setDraft((current) => current ? { ...current, ...patch } : current); setPreview(null); };
  const updateCaptureInterface = (name: string) => updateDraft({ capture: { ...draft.capture, interfaces: toggle(draft.capture.interfaces ?? [], name), auto_interfaces: false } });
  const updateCaptureBpf = (value: string) => {
    const bpfFilter = value.trim();
    if (bpfFilter) {
      updateDraft({ capture: { ...draft.capture, bpf_filter: bpfFilter } });
      return;
    }
    const { bpf_filter: _bpfFilter, ...captureWithoutBpf } = draft.capture;
    updateDraft({ capture: captureWithoutBpf });
  };
  const rulesFor = (candidates: CandidateBundle[]) => candidates.flatMap((candidate) => makeRules(candidate, selectorEndpoints[candidate.key]));
  const addTargets = () => { updateDraft({ protocolMap: { ...draft.protocolMap, document: { ...draft.protocolMap.document, protocols: [...draft.protocolMap.document.protocols, ...rulesFor(selectedCandidates)] } } }); setSelected([]); };
  const addTargetsAsRelationship = (kind: MonitoringTargetGroup["kind"]) => {
    if (selectedCandidates.length < 2 || (kind === "bidirectional_pair" && selectedCandidates.length !== 2) || (kind === "redundancy_set" && selectedCandidates.some((candidate) => candidate.protocol !== "RTP" && candidate.protocol !== "RTP-FEC"))) return;
