  const removeTarget = (id: string) => { const target_groups = (draft.protocolMap.document.target_groups ?? []).map((group) => ({ ...group, members: group.members.filter((member) => member !== id), ...(group.paths ? { paths: Object.fromEntries(Object.entries(group.paths).filter(([member]) => member !== id)) } : {}) })).filter((group) => group.members.length >= 2 && (group.kind !== "bidirectional_pair" || group.members.length === 2)); updateDraft({ protocolMap: { ...draft.protocolMap, document: { ...draft.protocolMap.document, protocols: draft.protocolMap.document.protocols.filter((rule) => rule.id !== id), ...(target_groups.length ? { target_groups } : {}) } }, alerts: { ...draft.alerts, bindings: draft.alerts.bindings.filter((binding) => binding.scope.kind !== "managed_target" || binding.scope.target_id !== id) } }); };
  const makePreview = () => { setBusy(true); void previewSetup(draft).then((next) => { setPreview(next); setMessage(""); setStep("review"); }).catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to preview changes")).finally(() => setBusy(false)); };
  const apply = (restart = false) => { setBusy(true); void (async () => {
    const result = await applySetup(draft);
    const next = result.state;
    setState(next); replaceRuntime(result.runtime); setDraft({ revision: next.revision, capture: next.capture.document, protocolMap: { path: next.protocolMap.path, document: next.protocolMap.document }, alerts: next.alerts.document }); onAlertsSaved(next.alerts.document); setPreview(null);
    if (!restart) { setMessage(runtimeAttention(result.runtime) !== "current" ? "Saved. Active services still use an earlier configuration; restart pending services to apply it." : result.applied.length ? "Saved." : "No configuration changes."); return; }
    await restartPendingServices();
  })().catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to apply setup")).finally(() => setBusy(false)); };
  const restartPendingServices = async () => {
    const started = await restartPending();
    if (!started) { setMessage("All services already use the saved configuration."); return; }
    setMessage("Restarting " + started.targets.join(", ") + "…");
    setMessage("Restart started. Service operation tracks progress and any failure.");
  };
  const saveProfile = () => { if (!profileName.trim()) { setMessage("Enter a profile name."); return; } setBusy(true); void saveSetupProfile(profileName, draft).then((profile) => { setProfiles((current) => [...current.filter((item) => item.id !== profile.id), profile].sort((a, b) => a.name.localeCompare(b.name))); setProfileName(""); setMessage("Configuration profile saved."); }).catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to save configuration profile")).finally(() => setBusy(false)); };
  const loadProfile = (profile: SetupProfile) => { setDraft({ revision: state.revision, ...profile.draft }); setPreview(null); setMessage("Loaded profile " + profile.name + ". Review changes before applying."); };
  const removeProfile = (profile: SetupProfile) => { setBusy(true); void deleteSetupProfile(profile.id).then(() => setProfiles((current) => current.filter((item) => item.id !== profile.id))).catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to delete configuration profile")).finally(() => setBusy(false)); };
  const removeOrphanedBindings = () => { if (!orphanedBindings.length || !window.confirm(`Remove ${orphanedBindings.length} Alert binding(s) for Monitoring targets that no longer exist?`)) return; updateDraft({ alerts: { ...draft.alerts, bindings: draft.alerts.bindings.filter((binding) => binding.scope.kind !== "managed_target" || targetIds.has(binding.scope.target_id)) } }); setMessage(`Removed ${orphanedBindings.length} orphaned Alert binding(s).`); };
