  const migrateSrtEndpoint = (migration: SrtEndpointMigration) => updateDraft({ protocolMap: { ...draft.protocolMap, document: { ...draft.protocolMap.document, protocols: draft.protocolMap.document.protocols.map((rule) => rule.id !== migration.ruleId ? rule : { ...rule, endpoints: [...new Set(stringListValue(rule.endpoints).map((endpoint) => endpoint === migration.callerEndpoint ? migration.listenerEndpoint : endpoint))] }) } } });
  return <PaneFrame className={`maintenance-frame setup-assistant-frame${busy ? " is-maintenance-busy" : ""}`} header={<PaneHeader title="Setup Assistant" icon="maintenance" meta="Initial configuration and safe reconfiguration" actions={<button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={load}><Icon name="reload" size={16} />Reload</button>} />}>
    <div className="maintenance-form"><div className="maintenance-intro">Draft changes do not affect monitoring until you review and apply them. Save only keeps the current services running with their previous configuration; apply and restart updates the required services.</div><div className="maintenance-tabs" role="tablist" aria-label="Setup Assistant section">{steps.map((item) => <button type="button" key={item.id} role="tab" aria-selected={step === item.id} className={"maintenance-tab" + (step === item.id ? " is-active" : "")} onClick={() => setStep(item.id)}>{item.label}</button>)}</div>
    {step === "policy" && <section className="maintenance-section"><div className="maintenance-section-copy"><h2>System Capture Policy</h2><p>Guardrails are managed outside Setup Assistant and cannot be changed here.</p></div><div className="maintenance-table-wrap"><table className="maintenance-table setup-policy-table"><tbody><tr><th scope="row"><span>Policy file</span><small>External configuration and revision</small></th><td>{state.policy.configured ? <><code>{state.policy.path}</code><small>{state.policy.revision}</small></> : "No external System policy is configured."}</td></tr><tr><th scope="row"><span>Forbidden NICs</span><small>Capture is blocked by System policy</small></th><td><PolicyValueList values={state.policy.guardrails.forbiddenInterfaces} empty="None" /></td></tr><tr><th scope="row"><span>Required BPF exclusions</span><small>Always added to the Capture filter</small></th><td><PolicyValueList values={state.policy.guardrails.requiredBpfExclusions} empty="None" code /></td></tr></tbody></table></div></section>}
