    {step === "targets" && <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Monitoring targets</h2><p>Each candidate is a monitoring unit: an RTP-FEC session includes media and FEC flows, while an SRT session includes its bidirectional control and data flows. Unclassified UDP flows require an explicit UDP (monitor as-is), RTP, RTP-FEC, or SRT choice. TCP candidates can be monitored as TCP. TCP/UDP monitoring does not change decoding. UDT flows can be explicitly configured as SRT. RTP uses its session destination; SRT uses a confirmed listener endpoint. For an unclassified flow, choose the stable endpoint to save.</p></div>{srtEndpointMigrations.length > 0 && <div className="setup-alert-orphans"><p>{srtEndpointMigrations.length} SRT Monitoring target(s) use a transient caller endpoint. Replace each with the listener endpoint so caller reconnection remains decoded as SRT.</p><ul>{srtEndpointMigrations.map((migration) => <li key={migration.ruleId}><code>{migration.callerEndpoint}</code> → <code>{migration.listenerEndpoint}</code> <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => migrateSrtEndpoint(migration)}>Use listener endpoint</button></li>)}</ul></div>}<CandidateList candidates={visibleCandidates} total={allCandidates.length} suppressedKeys={suppressedCandidateKeys} showConfigured={showConfiguredCandidates} query={candidateQuery} selected={selected} selectedCount={selectedCandidates.length} hiddenSelectedCount={hiddenSelectedCount} decodeAsProtocols={decodeAsProtocols} selectorEndpoints={selectorEndpoints} busy={busy} onQuery={setCandidateQuery} onShowConfigured={setShowConfiguredCandidates} onToggle={(key) => setSelected((current) => toggle(current, key))} onProtocol={(streamKey, protocol) => { setDecodeAsProtocols((current) => ({ ...current, [streamKey]: protocol })); if (!protocol) setSelected((current) => current.filter((key) => key !== streamKey)); }} onSelectorEndpoint={(key, endpoint) => setSelectorEndpoints((current) => ({ ...current, [key]: endpoint }))} /><div className="setup-candidate-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={!selectedCandidates.length || busy} onClick={addTargets}><Icon name="add" size={16} />Add selected targets{selectedCandidates.length ? ` (${selectedCandidates.length})` : ""}</button><button type="button" className="maintenance-secondary-button" disabled={busy || selectedCandidates.length !== 2} onClick={() => addTargetsAsRelationship("bidirectional_pair")}>Add as bidirectional pair</button><button type="button" className="maintenance-secondary-button" disabled={busy || selectedCandidates.length < 2 || selectedCandidates.some((candidate) => candidate.protocol !== "RTP" && candidate.protocol !== "RTP-FEC")} onClick={() => addTargetsAsRelationship("redundancy_set")}>Add as redundancy set</button></div><div className="maintenance-table-wrap"><table className="maintenance-table"><thead><tr><th>Target</th><th>Protocol</th><th>NIC</th><th>Endpoint / host</th><th>Relationships</th><th /></tr></thead><tbody>{targets.map((target) => <tr key={target.id}><td>{target.title ?? target.id}</td><td>{target.proto}{target.flowRoles ? " + FEC" : ""}</td><td>{stringList(draft.protocolMap.document.protocols.find((rule) => rule.id === target.id)?.interfaces)}</td><td>{stringList(draft.protocolMap.document.protocols.find((rule) => rule.id === target.id)?.endpoints ?? draft.protocolMap.document.protocols.find((rule) => rule.id === target.id)?.hosts)}</td><td><RelationshipLabels groups={draft.protocolMap.document.target_groups ?? []} targetId={target.id} targets={targets} /></td><td><button type="button" className="maintenance-secondary-button" onClick={() => removeTarget(target.id)}>Remove</button></td></tr>)}</tbody></table></div><TargetGroupEditor groups={draft.protocolMap.document.target_groups ?? []} targets={targets} busy={busy} onChange={(target_groups) => updateDraft({ protocolMap: { ...draft.protocolMap, document: { ...draft.protocolMap.document, ...(target_groups.length ? { target_groups } : {}) } } })} /></section>}
