else { setBusy(true); void restartPendingServices().catch((error: unknown) => setMessage(error instanceof Error ? error.message : "Failed to restart pending services")).finally(() => setBusy(false)); } }}><Icon name="reload" size={16} />{preview ? "Apply and restart required services" : "Restart pending services"}</button></div></section>}
