function TargetGroupEditor({ groups, targets, busy, onChange }: { groups: MonitoringTargetGroup[]; targets: MonitoringTargetDefinition[]; busy: boolean; onChange: (groups: MonitoringTargetGroup[]) => void }) {
  const updateName = (id: string, value: string) => onChange(groups.map((group) => group.id !== id ? group : value.trim() ? { ...group, name: value.trim() } : omitGroupName(group)));
  return <section className="maintenance-section"><div className="maintenance-section-copy"><h3>Target relationships</h3><p>Create relationships while selecting candidate bundles above. Names are generated from their members unless you set a custom name here.</p></div><div className="maintenance-table-wrap"><table className="maintenance-table"><thead><tr><th>Name</th><th>Kind</th><th>Members</th><th /></tr></thead><tbody>{groups.map((group) => <tr key={group.id}><td><label><span className="visually-hidden">Relationship name</span><input value={group.name ?? ""} placeholder={automaticRelationshipName(group, targets)} disabled={busy} onChange={(event) => updateName(group.id, event.target.value)} /><small>{group.name ? "Custom name" : "Automatic name"}</small></label></td><td>{group.kind}</td><td>{group.members.map((id) => targets.find((target) => target.id === id)?.title ?? id).join(", ")}</td><td><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => onChange(groups.filter((item) => item.id !== group.id))}>Remove</button></td></tr>)}{groups.length === 0 && <tr><td colSpan={4}>No target relationships.</td></tr>}</tbody></table></div></section>;
}

function RelationshipLabels({ groups, targetId, targets }: { groups: MonitoringTargetGroup[]; targetId: string; targets: MonitoringTargetDefinition[] }) {
  const related = groups.filter((group) => group.members.includes(targetId));
  if (!related.length) return <>—</>;
  return <>{related.map((group) => <span key={group.id}>{automaticRelationshipName(group, targets)}</span>)}</>;
}

function automaticRelationshipName(group: MonitoringTargetGroup, targets: MonitoringTargetDefinition[]) {
  if (group.name) return group.name;
  const labels = group.members.map((id) => targets.find((target) => target.id === id)?.title ?? id);
  if (group.kind === "bidirectional_pair") return `Bidirectional: ${labels[0] ?? group.id} ↔ ${labels[1] ?? ""}`;
  return `Redundancy: ${labels.slice(0, 2).join(" / ")}${labels.length > 2 ? ` (+${labels.length - 2})` : ""}`;
}

function omitGroupName(group: MonitoringTargetGroup): MonitoringTargetGroup {
  const { name: _name, ...automatic } = group;
  return automatic;
}

