candidate.protocol === "SRT" ? "Listener confirmed" : "Session destination"}: {automaticEndpoint}</small> : requiresEndpoint && <label><small>{endpointLabel}</small><select aria-label={`${endpointLabel} for ${subject}`} value={selectorEndpoint ?? ""} disabled={configured || busy} onChange={(event) => onSelectorEndpoint(candidate.key, event.target.value)}><option value="">Choose stable endpoint</option>{selectorEndpointOptions(candidate.stream).map((endpointOption) => <option key={endpointOption} value={endpointOption}>{endpointOption}</option>)}</select></label>)}</div></div>;
