function captureCandidateMatches(candidate: CaptureCandidate, telemetry: InterfaceListItem | undefined, query: string) { const needle = query.trim().toLocaleLowerCase(); if (!needle) return true; return [candidate.name, candidate.selectable ? "selectable" : "disabled", candidate.reason, telemetry?.link?.speedMbps ? `${telemetry.link.speedMbps} Mbps` : undefined, telemetry?.link?.duplex, telemetry?.link?.operstate, telemetry?.link?.mtu ? `MTU ${telemetry.link.mtu}` : undefined, telemetry?.link?.mac].filter((value): value is string => Boolean(value)).join(" ").toLocaleLowerCase().includes(needle); }
function captureLinkLabel(telemetry: InterfaceListItem | undefined) { if (!telemetry?.link) return "—"; const speed = telemetry.link.speedMbps ? formatLinkSpeed(telemetry.link.speedMbps) : "speed unknown"; return [speed, telemetry.link.duplex, telemetry.link.operstate].filter(Boolean).join(" · "); }
function captureLinkDetail(telemetry: InterfaceListItem | undefined) { if (!telemetry?.link) return "No link telemetry yet"; return [telemetry.link.mtu ? `MTU ${telemetry.link.mtu}` : undefined, telemetry.link.mac].filter(Boolean).join(" · ") || "Link details unavailable"; }
function formatLinkSpeed(speedMbps: number) { if (speedMbps < 1000) return `${speedMbps} Mb/s`; const gbps = speedMbps / 1000; return `${Number.isInteger(gbps) ? gbps.toFixed(0) : gbps.toFixed(1)} Gb/s`; }
function targetDefinitions(rules: ProtocolRule[]): MonitoringTargetDefinition[] { return rules.flatMap((rule) => rule.id ? [{ id: rule.id, proto: rule.proto, target_type: rule.target_type ?? "single", ...(rule.stream_name ? { title: rule.stream_name } : {}), ...(rule.proto === "RTP" && rule.fec === true ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }] : []); }
function toggle(values: string[], value: string) { return values.includes(value) ? values.filter((item) => item !== value) : [...values, value]; }
function stringList(value: string | string[] | undefined) { return Array.isArray(value) ? value.join(", ") : value ?? "Any"; }
function stringListValue(value: string | string[] | undefined) { return Array.isArray(value) ? value : value ? [value] : []; }

type SrtEndpointMigration = { ruleId: string; callerEndpoint: string; listenerEndpoint: string };

function findSrtEndpointMigrations(rules: ProtocolRule[], candidates: CandidateBundle[]): SrtEndpointMigration[] {
  const migrations: SrtEndpointMigration[] = [];
  for (const rule of rules) {
    if (!rule.id || rule.proto.toUpperCase() !== "SRT") continue;
    const endpoints = stringListValue(rule.endpoints);
    for (const candidate of candidates) {
      if (candidate.source !== "detected" || candidate.protocol !== "SRT") continue;
      if (rule.interfaces && candidate.stream.interfaceName && !stringListValue(rule.interfaces).includes(candidate.stream.interfaceName)) continue;
      const listenerEndpoint = candidate.stream.listenerEndpoint;
      if (!listenerEndpoint || endpoints.includes(listenerEndpoint)) continue;
      const callerEndpoint = endpoints.find((endpoint) => selectorEndpointOptions(candidate.stream).includes(endpoint));
      if (callerEndpoint) {
        migrations.push({ ruleId: rule.id, callerEndpoint, listenerEndpoint });
        break;
      }
    }
  }
  return migrations;
}
## 2026-10-01: Setup Assistantの統合適用API

### Context

Capture、protocol map、Alert policyは別ファイルであり、個別設定APIだけではアシスタントの下書きを一貫して確認・適用できない。設定変更中も通常監視は継続し、再起動は自動実行しない方針である。

### Decision

Frontend serverに`/api/setup/state`、`/api/setup/preview`、`/api/setup/apply`を追加する。stateはSystem policy、Capture、protocol map、alertsと統合revisionを返す。previewは全下書きとrevisionを確認し、変更領域と必要なCapture/STM再起動を返す。applyはprotocol map、alerts、Captureの順に個別の原子的書込みを行い、途中失敗時には反映済み領域を返す。再起動は実行せず案内だけを返す。

### Reason

下書き中に設定ファイルを変更せず、保存前に競合・孤立したAlert bindingを検出できる。設定ファイルが別である制約は隠さず、部分適用の状態を明示して安全に復旧できる。

### Consequences

Setup APIを利用するclientは適用直前に最新stateを再読込する必要がある。Capture変更はCapture再起動、protocol mapまたはalerts変更はSTM再起動が必要である。プロセス管理権限を持つ再起動APIは含めない。
## 2026-10-01: 名前付きConfiguration Profile

### Context

同一のSTMで初期設定後に複数のCapture/Monitoring Target/Alert構成を再利用・比較したい。一方、System Capture Policyはデプロイ管理者の強制設定であり、運用プロフィールによって持ち運んだり上書きしたりしてはならない。

### Decision

Configuration Profileはサーバー側の独立JSONへ、Capture設定、protocol map、alertsの下書きを名前付きで保存する。System policyとSetup revisionは保存しない。プロフィールを適用する際は、その時点のSetup revisionで既存`setup/apply`を実行し、通常の競合確認、Target参照検証、再起動案内を通す。

### Reason

プロフィールを実行中設定のコピーとして直接書き込むと、古いrevisionやSystem policyとの不整合を見逃す。既存の統合適用経路を再利用すれば、通常のウィザード操作と同じ安全性を保てる。

### Consequences

稼働中に有効な設定は常に一組だけであり、プロフィール適用後も自動再起動しない。プロフィールはSystem policyを緩和できず、適用結果は現在設定との差分として確認できる。
## 2026-10-01: 汎用UDP／UDTからの明示プロトコル設定

### Context

RTPやSRTは、tsharkがポート番号だけからプロトコルを自動判別できない場合がある。そのような通信は`UDP`または`UDT`として検出されるが、導入時に実際のflowを選び、適切なプロトコルとして`decode-as`を生成する導線が必要である。特にSRTはtsharkによりUDTと分類される場合がある。

### Decision

Setup Assistantはtsharkにより`UDP`または`UDT`と分類され、endpointを持つstreamを候補として表示する。UDP候補では利用者がRTP、RTP-FEC、またはSRTを、UDT候補ではSRTを明示選択してからMonitoring Targetを追加する。RTP-FECは`proto: RTP`と`fec: true`のruleとして保存する。追加したruleは選択元endpoint、NIC、VLANを保持し、既存のprotocol map自動`decode-as`生成を利用する。

### Reason

画面表示用の`protocolDetails`文字列を判定に再利用すると、翻訳や表示変更で設定動作が壊れる。投影済み状態に保存されるtsharkの`UDP`／`UDT`分類を使えば、未解釈の候補だけを安全に候補化できる。UDTはSRTとして解釈される場合を対象にし、RTP選択を出さない。RTP/SRT ruleとして保存すれば、既存の識別、Target ID、Alert policyの経路を変更せずに再起動後の再分類へつなげられる。

### Consequences

UDP／UDT候補は単独では保存・登録できず、プロトコル選択が必須となる。UDT候補はSRT選択だけを許可する。RTP-FEC ruleはbase、base+2、base+4をTargetへ紐付け、RTP streamの`media`、`fec_row`、`fec_col` roleとして扱う。Target固有Alert policyを新規作成する際はこの3 roleを初期値にする。誤った選択は誤ったtshark dissector適用につながるため、Assistantは検出結果ではなく利用者の明示指定として表示する。設定反映には従来どおりSTMの再起動が必要である。

## 2026-10-01: Setup Assistantの候補リストとステップナビゲーション

### Context

Setup Assistantのステップ操作とMonitoring target候補は、設定作業の導線であるにもかかわらず、他の設定画面やStreamsの一覧と異なる見た目だった。候補数が多い場合に必要な対象を探しにくく、検索中に既存の選択を失うおそれもあった。

### Decision

Alert policiesとSetup Assistantのタブは共通の`maintenance-tabs`／`maintenance-tab`スタイルとARIA tab patternを使用する。Monitoring target候補は既存の「stream単位でTarget ruleを生成する」意味を保ったまま、NIC、scope、検出プロトコル、endpointを示すフラットな行リストで表示する。検索は候補表示だけを絞り込み、選択状態は維持する。選択済み候補が検索結果外にある場合は件数を表示する。

### Reason

StreamsのRanked flowsと同じ情報の優先順位を使えば、運用者が検出済みflowの文脈を保ったまま設定できる。一方、候補をflow単位のTarget生成へ変更すると重複判定と設定の意味が変わるため、表示改善と設定モデル変更を分離する。検索で選択を消さないことで、検索語の変更による意図しない設定漏れを防ぐ。

### Consequences

候補検索の対象はstream名、endpoint、NIC、VLAN/VXLAN scope、検出プロトコルである。追加ボタンは検索結果外の選択を含む全選択候補に作用し、件数でそのことを明示する。API、保存形式、decode-as生成、Alert policy設定の互換性は変わらない。

## 2026-10-01: Setup AssistantにおけるAlert評価の一括無効化

### Context

Setup Assistantは現在のMonitoring targetだけをAlert policy編集対象として表示する。一方、alerts設定には削除済みTarget IDを参照する`managed_target` bindingが残り得る。disabled modeもbindingとして保存されるため、現在のTargetをすべて無効化しても、古いbindingがReviewの整合性検証を失敗させる。

### Decision

Alert policiesステップに「全TargetのAlert evaluationを無効化」操作を置く。この操作は確認後、現在の各Monitoring targetへ`mode: disabled`のbindingを作成し、すべてのTarget固有bindingを置換する。Common policiesとProtocol default bindingは保持する。孤立したTarget固有bindingはAlert policiesとReviewの両方で件数を表示し、個別に削除できる。TargetのAlert policy見出しは`stream_name`由来のTarget名を優先し、target_idは補助情報として表示する。

### Reason

disabled bindingを現在のTargetへ明示的に置けば、Protocol defaultが存在してもAlert評価を確実に停止できる。孤立bindingを自動削除すると既存設定を意図せず失うため、削除は利用者の明示操作とする。一方で全無効化は「Alert policiesを設定しない」という明確な意思表示なので、Target固有設定の置換を確認付きで許容する。

### Consequences

Review／applyのTarget整合性検証は従来どおり厳密なままであり、孤立bindingを残した設定は保存できない。利用者は孤立bindingだけを削除して既存の有効なTarget設定を保つか、全TargetのAlert評価を無効化してTarget固有設定を作り直すかを選べる。

