import { createHash } from "node:crypto";
import type { AlertsDocument, AlertsResponse, AlertsSettings } from "./alertsSettings";
import type { CaptureDocument, CaptureSettings, CaptureSettingsResponse } from "./captureSettings";
import type { SystemCapturePolicy, CapturePolicySettings } from "./capturePolicySettings";
import type { ProtocolMapDocument, ProtocolMapResponse, ProtocolMapSettings } from "./protocolMapSettings";

export type SetupState = { revision: string; policy: SystemCapturePolicy; capture: CaptureSettingsResponse; protocolMap: ProtocolMapResponse; alerts: AlertsResponse };
export type SetupDraft = { revision: string; capture: CaptureDocument; protocolMap: { path: string; document: ProtocolMapDocument }; alerts: AlertsDocument };
export type SetupPreview = { revision: string; changes: Array<{ area: "capture" | "protocol_map" | "alerts"; action: "unchanged" | "update"; restart: "capture" | "stm" | null }>; warnings: string[] };
export class SetupConflictError extends Error {}
export class SetupValidationError extends Error {}
export class SetupApplyError extends Error { constructor(message: string, readonly applied: string[]) { super(message); } }

export class SetupSettings {
  constructor(
    private readonly policySettings: CapturePolicySettings,
    private readonly captureSettings: CaptureSettings,
    private readonly protocolMapSettings: ProtocolMapSettings,
    private readonly alertsSettings: AlertsSettings
  ) {}

  async get(): Promise<SetupState> {
    const [policy, capture, protocolMap, alerts] = await Promise.all([this.policySettings.get(), this.captureSettings.get(), this.protocolMapSettings.get(), this.alertsSettings.get()]);
    return { revision: revisionOf(policy.revision ?? "", capture.revision, protocolMap.revision, alerts.revision), policy, capture, protocolMap, alerts };
  }

  async preview(draft: unknown): Promise<SetupPreview> {
    const state = await this.get();
    const next = validateDraft(draft, state);
    if (next.revision !== state.revision) throw new SetupConflictError("setup state changed on the server; reload before applying");
    const warnings = danglingBindings(next.alerts, next.protocolMap.document);
    if (warnings.length) throw new SetupValidationError(warnings.join("; "));
    return {
      revision: state.revision,
      changes: [
        { area: "capture", action: same(next.capture, state.capture.document) ? "unchanged" : "update", restart: same(next.capture, state.capture.document) ? null : "capture" },
        { area: "protocol_map", action: same(next.protocolMap, { path: state.protocolMap.path, document: state.protocolMap.document }) ? "unchanged" : "update", restart: same(next.protocolMap, { path: state.protocolMap.path, document: state.protocolMap.document }) ? null : "stm" },
        { area: "alerts", action: same(next.alerts, state.alerts.document) ? "unchanged" : "update", restart: same(next.alerts, state.alerts.document) ? null : "stm" }
      ],
      warnings: []
    };
  }

  async apply(draft: unknown): Promise<{ state: SetupState; applied: string[] }> {
    const preview = await this.preview(draft);
    const state = await this.get();
    if (preview.revision !== state.revision) throw new SetupConflictError("setup state changed on the server; reload before applying");
    const next = validateDraft(draft, state);
    const applied: string[] = [];
    try {
      if (!same(next.protocolMap, { path: state.protocolMap.path, document: state.protocolMap.document })) {
        await this.protocolMapSettings.update({ revision: state.protocolMap.revision, ...next.protocolMap });
        applied.push("protocol_map");
      }
      const alerts = await this.alertsSettings.get();
      if (!same(next.alerts, alerts.document)) {
        await this.alertsSettings.update({ revision: alerts.revision, document: next.alerts });
        applied.push("alerts");
      }
      const capture = await this.captureSettings.get();
      if (!same(next.capture, capture.document)) {
        await this.captureSettings.update({ revision: capture.revision, document: next.capture });
        applied.push("capture");
      }
    } catch (error) {
      throw new SetupApplyError(error instanceof Error ? error.message : "failed to apply setup", applied);
    }
    return { state: await this.get(), applied };
  }
}

function validateDraft(value: unknown, state: SetupState): SetupDraft {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new SetupValidationError("setup draft must be an object");
  const draft = value as Record<string, unknown>;
  if (typeof draft.revision !== "string") throw new SetupValidationError("setup draft revision is required");
  if (!draft.protocolMap || typeof draft.protocolMap !== "object" || Array.isArray(draft.protocolMap)) throw new SetupValidationError("protocol map draft is required");
  const protocolMap = draft.protocolMap as Record<string, unknown>;
  if (typeof protocolMap.path !== "string" || !protocolMap.path.trim() || !protocolMap.document || typeof protocolMap.document !== "object" || Array.isArray(protocolMap.document)) throw new SetupValidationError("protocol map path and document are required");
  if (!draft.capture || typeof draft.capture !== "object" || Array.isArray(draft.capture)) throw new SetupValidationError("capture draft is required");
  if (!draft.alerts || typeof draft.alerts !== "object" || Array.isArray(draft.alerts)) throw new SetupValidationError("alerts draft is required");
  return { revision: draft.revision, capture: draft.capture as CaptureDocument, protocolMap: { path: protocolMap.path, document: protocolMap.document as ProtocolMapDocument }, alerts: draft.alerts as AlertsDocument };
}

function danglingBindings(alerts: AlertsDocument, protocolMap: ProtocolMapDocument) {
  const targets = new Set(protocolMap.protocols.flatMap((rule) => typeof rule.id === "string" ? [rule.id] : []));
  return alerts.bindings.flatMap((binding) => binding.scope.kind === "managed_target" && !targets.has(binding.scope.target_id) ? ["Alert binding refers to missing Monitoring target: " + binding.scope.target_id] : []);
}
function same(left: unknown, right: unknown) { return JSON.stringify(left) === JSON.stringify(right); }
function revisionOf(...parts: string[]) { return createHash("sha256").update(parts.join("\u0000")).digest("hex"); }
