function validateDraft(value: unknown, state: SetupState): SetupDraft {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new SetupValidationError("setup draft must be an object");
  const draft = value as Record<string, unknown>;
  if (typeof draft.revision !== "string") throw new SetupValidationError("setup draft revision is required");
