  if (!draft.alerts || typeof draft.alerts !== "object" || Array.isArray(draft.alerts)) throw new SetupValidationError("alerts draft is required");
  return { revision: draft.revision, capture: draft.capture as CaptureDocument, protocolMap: { path: protocolMap.path, document: protocolMap.document as ProtocolMapDocument }, alerts: draft.alerts as AlertsDocument };
