import type { ProtocolRule, StreamListItem } from "../types/api";

export type TargetProtocol = ProtocolRule["proto"];
export type TargetProtocolChoice = TargetProtocol | "RTP-FEC";
export type DecodeAsProtocol = "" | "RTP" | "RTP-FEC" | "SRT" | "UDP" | "TCP";
export type CandidateSource = "detected" | "udp" | "udt" | "tcp";

export type CandidateBundle = {
  key: string;
  stream: StreamListItem;
  protocol?: TargetProtocolChoice;
  source: CandidateSource;
  components: Array<{ role?: string; source?: string; destination?: string }>;
};

export function buildCandidateBundles(streams: StreamListItem[], decodeAs: Record<string, DecodeAsProtocol>): CandidateBundle[] {
  const bundles = new Map<string, CandidateBundle>();
  for (const stream of streams) {
    if (!endpointFor(stream)) continue;
    const source = candidateSource(stream);
    if (!source) continue;
    const key = bundleKey(stream, source);
    const detectedProtocol = isTargetProtocol(stream.proto) ? (stream.proto === "RTP" && hasFec(stream) ? "RTP-FEC" : stream.proto) : undefined;
    const selectedProtocol = decodeAs[stream.streamKey];
    const bundle: CandidateBundle = {
      key,
      stream,
      protocol: detectedProtocol ?? (selectedProtocol && candidateProtocolChoices(source).includes(selectedProtocol) ? selectedProtocol : undefined),
      source,
      components: stream.flows.map((flow) => ({ role: flow.role, source: flow.endpointSrc, destination: flow.endpointDst }))
    };
    const current = bundles.get(key);
    if (!current || (stream.lastSeen ?? 0) > (current.stream.lastSeen ?? 0)) bundles.set(key, bundle);
  }
  return [...bundles.values()];
}

export function candidateMatches(bundle: CandidateBundle, query: string) {
  const needle = query.trim().toLocaleLowerCase();
  if (!needle) return true;
  const stream = bundle.stream;
  return [stream.displayName, stream.label, stream.proto, bundle.protocol, stream.interfaceName, stream.endpointA, stream.endpointB, stream.sessionDst, candidateScopeLabel(stream), ...bundle.components.flatMap((component) => [component.role, component.source, component.destination])].filter((value): value is string => Boolean(value)).join(" ").toLocaleLowerCase().includes(needle);
}

export function isConfiguredBundle(bundle: CandidateBundle, rules: ProtocolRule[]) {
  return rules.some((rule) => Boolean(rule.id) && candidateChoices(bundle).some((choice) => ruleMatchesBundle(rule, bundle.stream, choice)));
}

export function isShadowedGenericBundle(bundle: CandidateBundle, bundles: CandidateBundle[]) {
  if (bundle.source === "detected") return false;
  return bundles.some((other) => other.key !== bundle.key && other.source === "detected" && sameCommunication(bundle.stream, other.stream));
}

export function endpointFor(stream: StreamListItem) {
  return stream.sessionDst ?? stream.flows.find((flow) => flow.role === "media")?.endpointDst ?? stream.flows[0]?.endpointDst ?? stream.endpointB;
}

/** Endpoints that can be safely offered for an explicit raw TCP/UDP/UDT selection. */
export function selectorEndpointOptions(stream: StreamListItem) {
  return [...new Set([
    ...stream.flows.flatMap((flow) => [flow.endpointSrc, flow.endpointDst]),
    stream.endpointA,
    stream.endpointB,
    stream.sessionDst
  ].filter((value): value is string => Boolean(value)))];
}

/**
 * A detected RTP session already has a directional session destination.  A
 * detected SRT session needs a listener inferred from its handshake.  Raw
 * TCP/UDP/UDT has neither guarantee and must be selected explicitly by the user.
 */
export function automaticSelectorEndpoint(bundle: CandidateBundle) {
  if (bundle.protocol === "RTP" || bundle.protocol === "RTP-FEC") return bundle.stream.sessionDst ?? endpointFor(bundle.stream);
  if (bundle.protocol === "SRT" && bundle.source === "detected") return bundle.stream.listenerEndpoint;
  return undefined;
}

export function selectorEndpointFor(bundle: CandidateBundle, selectedEndpoint?: string) {
  return selectedEndpoint ?? automaticSelectorEndpoint(bundle);
}

export function candidateScopeLabel(stream: StreamListItem) {
  const layer = stream.scope.layers[0];
  return layer?.kind === "vlan" ? `VLAN ${layer.id ?? "unknown"}` : layer?.kind === "vxlan" ? `VXLAN ${layer.vni ?? "unknown"}` : stream.scope.known ? "Untagged" : "Scope unknown";
}

export function candidateSubject(bundle: CandidateBundle) {
  const stream = bundle.stream;
  const flow = stream.flows.find((item) => item.role === "media") ?? stream.flows[0];
  const source = flow?.endpointSrc ?? stream.endpointA;
  const destination = flow?.endpointDst ?? endpointFor(stream);
  return source && destination && source !== destination ? `${source} → ${destination}` : destination ?? source ?? stream.label;
}

export function makeRules(bundle: CandidateBundle, selectedEndpoint?: string): ProtocolRule[] {
  if (!bundle.protocol) return [];
  const endpoint = selectorEndpointFor(bundle, selectedEndpoint);
  if (!endpoint) return [];
  const vlan = bundle.stream.scope.layers.find((layer): layer is Extract<typeof layer, { kind: "vlan" }> => layer.kind === "vlan")?.id;
  const fec = bundle.protocol === "RTP-FEC";
  const proto: TargetProtocol = bundle.protocol === "RTP-FEC" ? "RTP" : bundle.protocol;
  return [{ id: globalThis.crypto?.randomUUID?.() ?? "target_" + Math.random().toString(36).slice(2), target_type: "single", proto, ...(fec ? { fec: true } : {}), stream_name: bundle.stream.displayName ?? bundle.stream.label, ...(proto === "HLS" && !isEndpoint(endpoint) ? { hosts: [endpoint] } : { endpoints: [endpoint] }), ...(bundle.stream.interfaceName ? { interfaces: [bundle.stream.interfaceName] } : {}), ...(vlan ? { vlan } : {}), enabled: true, observe: true }];
}

function candidateSource(stream: StreamListItem): CandidateSource | undefined {
  if (isTargetProtocol(stream.proto)) return "detected";
  if (stream.proto === "UDP") return "udp";
  if (stream.proto === "TCP") return "tcp";
  if (stream.proto === "UDT") return "udt";
  return undefined;
}

export function candidateProtocolChoices(source: CandidateSource): Exclude<DecodeAsProtocol, "">[] {
  if (source === "tcp") return ["TCP"];
  if (source === "udp") return ["RTP", "RTP-FEC", "UDP", "SRT"];
  return source === "udt" ? ["SRT"] : [];
}

function candidateChoices(bundle: CandidateBundle): TargetProtocolChoice[] {
  if (bundle.source === "detected") return bundle.protocol ? [bundle.protocol] : [];
  return candidateProtocolChoices(bundle.source);
}

function ruleMatchesBundle(rule: ProtocolRule, stream: StreamListItem, choice: TargetProtocolChoice) {
  const proto = choice === "RTP-FEC" ? "RTP" : choice;
  if (rule.proto.toUpperCase() !== proto) return false;
  if (Boolean(rule.fec) !== (choice === "RTP-FEC")) return false;
  const scopeVlan = stream.scope.layers.find((layer): layer is Extract<typeof layer, { kind: "vlan" }> => layer.kind === "vlan")?.id;
  if (scopeVlan !== undefined && rule.vlan !== undefined && rule.vlan !== null && String(rule.vlan) !== String(scopeVlan)) return false;
  if (scopeVlan === undefined && rule.vlan !== undefined && rule.vlan !== null) return false;
  const interfaces = strings(rule.interfaces);
  if (interfaces.length && (!stream.interfaceName || !interfaces.includes(stream.interfaceName))) return false;
  const automatic = proto === "SRT" ? stream.listenerEndpoint : proto === "RTP" ? stream.sessionDst ?? endpointFor(stream) : endpointFor(stream);
  const selectors = proto === "HLS" && automatic && !isEndpoint(automatic) ? strings(rule.hosts).concat(strings(rule.domains)) : strings(rule.endpoints);
  const candidates = proto === "SRT" || proto === "UDP" || proto === "TCP" ? selectorEndpointOptions(stream) : [automatic].filter((value): value is string => Boolean(value));
  return candidates.some((endpoint) => selectors.includes(endpoint));
}

function sameCommunication(left: StreamListItem, right: StreamListItem) {
  if (left.interfaceName !== right.interfaceName || candidateScopeLabel(left) !== candidateScopeLabel(right)) return false;
  const leftEndpoints = communicationEndpoints(left);
  const rightEndpoints = communicationEndpoints(right);
  return leftEndpoints.length > 0 && leftEndpoints.every((endpoint) => rightEndpoints.includes(endpoint));
}

function communicationEndpoints(stream: StreamListItem) {
  const flow = stream.flows.find((item) => item.role === "media") ?? stream.flows[0];
  return [flow?.endpointSrc ?? stream.endpointA, flow?.endpointDst ?? endpointFor(stream)].filter((value): value is string => Boolean(value)).sort();
}

function bundleKey(stream: StreamListItem, source: CandidateSource) {
  if (source === "detected") return stream.streamKey;
  return [source, stream.interfaceName ?? "", candidateScopeLabel(stream), ...communicationEndpoints(stream)].join("|");
}

function strings(value: string | string[] | undefined) { return Array.isArray(value) ? value : value ? [value] : []; }
function isEndpoint(value: string) { return /(?:\]|\d):\d+$/.test(value); }
// Raw TCP/UDP still need an explicit choice of monitoring protocol and endpoint.
function isTargetProtocol(value: string): value is Exclude<TargetProtocol, "UDP" | "TCP"> { return value === "RTP" || value === "SRT" || value === "HLS"; }
function hasFec(stream: StreamListItem) { return stream.flowRoles.some((role) => role === "fec_row" || role === "fec_col"); }

