const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const Module = require('node:module');
const esbuild = require('../server/node_modules/esbuild');
const React = require('../node_modules/react');
const { renderToStaticMarkup } = require('../node_modules/react-dom/server');
const root = path.resolve(__dirname, '..');

function load(relativePath) {
  const bundled = esbuild.buildSync({ entryPoints: [path.join(root, relativePath)], bundle: true,
    write: false, platform: 'node', format: 'cjs', packages: 'external', jsx: 'automatic' });
  const loaded = new Module(__filename + '.bundle', module);
  loaded.paths = module.paths;
  loaded._compile(bundled.outputFiles[0].text, __filename + '.bundle');
  return loaded.exports;
}
const { ProtocolMapSettings } = load('server/src/protocolMapSettings.ts');
const { AlertsSettings } = load('server/src/alertsSettings.ts');
const { buildCandidateBundles, makeRules, isConfiguredBundle, candidateProtocolChoices } = load('client/src/components/candidateBundles.ts');
const { AlertConditionTable, newAlertCondition } = load('client/src/components/AlertConditionTable.tsx');

for (const proto of ['UDP', 'TCP']) test(`${proto} targets preserve name, NIC and VLAN through settings and expose alert bindings`, async t => {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'stm-udp-settings-'));
  t.after(() => fs.rm(dir, { recursive: true, force: true }));
  const config = path.join(dir, 'stm.json');
  await fs.writeFile(config, JSON.stringify({ configs: { protocol_map: 'protocols.json', alerts: 'alerts.json' } }));
  await fs.writeFile(path.join(dir, 'protocols.json'), JSON.stringify({ protocols: [] }));
  await fs.writeFile(path.join(dir, 'alerts.json'), JSON.stringify({ policies: [], bindings: [] }));
  await fs.copyFile(path.join(root, '../conf/alerts_config.schema.json'), path.join(dir, 'alerts_config.schema.json'));
  const maps = new ProtocolMapSettings(config), alerts = new AlertsSettings(config);
  const initial = await maps.get();
  const rule = { id: proto.toLowerCase() + '-input', proto, stream_name: proto + ' input',
    endpoints: ['127.0.0.1:9999'], interfaces: ['lo'], vlan: 100, enabled: true };
  const saved = await maps.update({ ...initial, document: { observe_mode: 'configured_only', protocols: [rule] } });
  assert.deepEqual(saved.document.protocols, [rule]);
  assert.equal(saved.apply, 'restart_required');
  await assert.rejects(maps.update({ ...initial, document: { protocols: [] } }), /changed on the server/);
  for (const patch of [{ decode_as: ['udp.port==9999,rtp'] }, { fec: true }, { hosts: 'example.com' },
    { domains: 'example.com' }, { endpoints: '127.0.0.1:65536' }, { endpoints: 'bad:9999' }, { endpoints: undefined }]) {
    await assert.rejects(maps.update({ ...saved, document: { protocols: [{ ...rule, ...patch }] } }), /UDP|TCP|HLS only|endpoint or host/);
  }
  const current = await alerts.get();
  assert.ok(current.protocols.includes(proto));
  assert.deepEqual(current.monitoringTargets, [{ id: rule.id, proto, target_type: 'single', title: rule.stream_name }]);
  const condition = { ...newAlertCondition(proto, {}), metric: 'packet_count.window', operator: '==', error_threshold: 0, recover_threshold: 0 };
  const document = { policies: [], bindings: [{ scope: { kind: 'managed_target', target_id: rule.id }, mode: 'individual', conditions: [condition] }] };
  assert.deepEqual((await alerts.update({ revision: current.revision, document })).document, document);
});

test('Assistant keeps raw UDP explicit and still supports RTP, FEC and SRT conversion', () => {
  const stream = { streamKey: 'udp-flow', proto: 'UDP', label: 'UDP test', interfaceName: 'lo',
    scope: { known: true, layers: [{ kind: 'vlan', id: '100' }] }, flowRoles: ['flow'],
    flows: [{ endpointSrc: '127.0.0.1:40000', endpointDst: '127.0.0.1:9999', role: 'flow' }] };
  const [unselected] = buildCandidateBundles([stream], {});
  assert.equal(unselected.source, 'udp');
  assert.equal(unselected.protocol, undefined);
  assert.deepEqual(makeRules(unselected, stream.flows[0].endpointDst), []);
  for (const choice of ['UDP', 'RTP', 'RTP-FEC', 'SRT']) {
    const [bundle] = buildCandidateBundles([stream], { [stream.streamKey]: choice });
    assert.equal(bundle.source, 'udp');
    const [rule] = makeRules(bundle, stream.flows[0].endpointDst);
    assert.equal(rule.proto, choice === 'RTP-FEC' ? 'RTP' : choice);
    assert.equal(Boolean(rule.fec), choice === 'RTP-FEC');
    assert.equal(rule.decode_as, undefined);
    assert.equal(rule.stream_name, stream.label);
    assert.deepEqual(rule.interfaces, ['lo']);
    assert.equal(rule.vlan, '100');
  }
  const [bundle] = buildCandidateBundles([stream], { [stream.streamKey]: 'UDP' });
  const [rule] = makeRules(bundle, stream.flows[0].endpointSrc);
  assert.equal(isConfiguredBundle(bundle, [rule]), true, 'src selector is valid too');
  assert.equal(isConfiguredBundle(bundle, [{ ...rule, interfaces: ['other'] }]), false);
  assert.equal(isConfiguredBundle(bundle, [{ ...rule, vlan: 101 }]), false);
  const [rtp] = buildCandidateBundles([{ ...stream, proto: 'RTP', streamKey: 'rtp' }], { rtp: 'UDP' });
  assert.equal(rtp.source, 'detected');
  assert.equal(rtp.protocol, 'RTP', 'explicit raw UDP choice cannot reclassify detected RTP');
});

test('Assistant offers only TCP monitoring for TCP candidates and matches either endpoint', () => {
  const stream = { streamKey: 'tcp-flow', proto: 'TCP', label: 'TCP test', displayName: 'TCP input', interfaceName: 'eno1',
    scope: { known: true, layers: [{ kind: 'vlan', id: '100' }] }, flowRoles: ['flow'],
    flows: [{ endpointSrc: '192.0.2.1:40000', endpointDst: '192.0.2.2:9000', role: 'flow' }] };
  assert.deepEqual(candidateProtocolChoices('tcp'), ['TCP']);
  const [unselected] = buildCandidateBundles([stream], {});
  assert.equal(unselected.source, 'tcp');
  assert.equal(unselected.protocol, undefined);
  for (const selection of ['UDP', 'SRT', 'RTP']) {
    assert.equal(buildCandidateBundles([stream], { [stream.streamKey]: selection })[0].protocol, undefined);
  }
  const [bundle] = buildCandidateBundles([stream], { [stream.streamKey]: 'TCP' });
  assert.deepEqual(makeRules(bundle), [], 'a stable endpoint is required');
  for (const endpoint of [stream.flows[0].endpointSrc, stream.flows[0].endpointDst]) {
    const [rule] = makeRules(bundle, endpoint);
    assert.equal(rule.proto, 'TCP');
    assert.equal(rule.stream_name, 'TCP input');
    assert.deepEqual(rule.endpoints, [endpoint]);
    assert.deepEqual(rule.interfaces, ['eno1']);
    assert.equal(rule.vlan, '100');
    assert.equal(rule.decode_as, undefined);
    assert.equal(rule.fec, undefined);
    assert.equal(isConfiguredBundle(bundle, [rule]), true);
    assert.equal(isConfiguredBundle(bundle, [{ ...rule, interfaces: ['wrong'] }]), false);
    assert.equal(isConfiguredBundle(bundle, [{ ...rule, vlan: 101 }]), false);
    const hls = buildCandidateBundles([{ ...stream, proto: 'HLS' }], {})[0];
    assert.equal(isConfiguredBundle(hls, [rule]), false, 'TCP target cannot match a higher-level protocol');
  }
  assert.deepEqual(buildCandidateBundles([{ ...stream, proto: 'TLS' }, { ...stream, proto: 'HTTP' }], {}), []);
});

