export type RuntimeAttention = "current" | "pending" | "restarting" | "failed" | "unavailable";

type RuntimeStatusContextValue = {
  runtime: RuntimeProcessesResponse | null;
  operation: RuntimeRestartOperation | null;
  error: string | null;
  refresh: () => Promise<RuntimeProcessesResponse | null>;
  replaceRuntime: (runtime: RuntimeProcessesResponse) => void;
  restartPending: () => Promise<RuntimeRestartOperation | null>;
