const RuntimeStatusContext = createContext<RuntimeStatusContextValue | undefined>(undefined);

export function RuntimeStatusProvider({ children }: { children: ReactNode }) {
  const [runtime, setRuntime] = useState<RuntimeProcessesResponse | null>(null);
  const [operation, setOperation] = useState<RuntimeRestartOperation | null>(null);
  const [error, setError] = useState<string | null>(null);

