export function runtimeAttention(runtime: RuntimeProcessesResponse | null, error: string | null = null): RuntimeAttention {
  if (runtime?.processes.some((process) => process.activation.state === "restart_failed")) return "failed";
  if (runtime?.processes.some((process) => process.activation.state === "restarting")) return "restarting";
  if (runtime?.processes.some((process) => process.activation.state === "restart_required")) return "pending";
