      window.removeEventListener("focus", onVisibility);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [refresh]);

  useEffect(() => {
    if (!operation || operation.state !== "running") return;
    let active = true;
    let timer = 0;
    const poll = async () => {
      try {
        const next = await getRuntimeRestart(operation.id);
        if (!active) return;
        setOperation(next.operation);
        replaceRuntime(next.runtime);
        if (next.operation.state === "running") timer = window.setTimeout(() => { void poll(); }, 1_000);
      } catch (caught) {
        if (active) setError(caught instanceof Error ? caught.message : "Unable to check service restart");
      }
    };
    timer = window.setTimeout(() => { void poll(); }, 1_000);
    return () => { active = false; window.clearTimeout(timer); };
  }, [operation, replaceRuntime]);

  useEffect(() => {
    if (operation?.state === "running") return;
    const attention = runtimeAttention(runtime, error);
    const delay = attention === "current" ? 60_000 : 30_000;
    const timer = window.setTimeout(() => { void refresh(); }, delay);
    return () => window.clearTimeout(timer);
  }, [error, operation?.state, refresh, runtime]);

  const value = useMemo<RuntimeStatusContextValue>(() => ({ runtime, operation, error, refresh, replaceRuntime, restartPending }), [runtime, operation, error, refresh, replaceRuntime, restartPending]);
  return <RuntimeStatusContext.Provider value={value}>{children}</RuntimeStatusContext.Provider>;
}

export function useRuntimeStatus() {
  const value = useContext(RuntimeStatusContext);
  if (!value) throw new Error("useRuntimeStatus must be used inside RuntimeStatusProvider");
  return value;
}

export function runtimeAttention(runtime: RuntimeProcessesResponse | null, error: string | null = null): RuntimeAttention {
  if (runtime?.processes.some((process) => process.activation.state === "restart_failed")) return "failed";
  if (runtime?.processes.some((process) => process.activation.state === "restarting")) return "restarting";
  if (runtime?.processes.some((process) => process.activation.state === "restart_required")) return "pending";
  if (error || runtime?.control.available === false) return "unavailable";
  return "current";
}

export function restartableProcesses(runtime: RuntimeProcessesResponse | null) {
  return runtime?.processes.filter((process) => process.activation.state === "restart_required" || process.activation.state === "restart_failed") ?? [];
}

export function activationLabel(value: RuntimeProcessesResponse["processes"][number]["activation"]["state"]) {
  return value === "current" ? "Current" : value === "restart_required" ? "Restart required" : value === "restarting" ? "Restarting" : "Restart failed";
}

export function activationAreaLabel(area: "capture" | "protocol_map" | "alerts") {
  return area === "capture" ? "Capture NIC / BPF (STM may restart)" : area === "protocol_map" ? "Monitoring targets" : "Alert policies";
}
