test('UI animations default On, migrate old persisted settings and retain explicit Off across restart and old-client saves',async t=>{
  const dir=await fs.mkdtemp(path.join(os.tmpdir(),'stm-maintenance-values-'));
  t.after(()=>fs.rm(dir,{recursive:true,force:true}));
  const options={definitionFile:path.resolve(__dirname,'../maintenance-settings.json'),runtimeFile:path.join(dir,'runtime-settings.json'),defaults};
  let settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().values.uiAnimationsEnabled,true);
  const legacy={...defaults};delete legacy.uiAnimationsEnabled;legacy.tooltipDelayMs=450;
  await fs.writeFile(options.runtimeFile,JSON.stringify({revision:7,values:legacy}));
  settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().revision,7);assert.equal(settings.get().values.tooltipDelayMs,450);
  assert.equal(settings.get().values.uiAnimationsEnabled,true,'missing old setting is filled without discarding the other values');
  await settings.update(7,{...settings.get().values,uiAnimationsEnabled:false});
  settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().values.uiAnimationsEnabled,false);
  await settings.update(8,legacy);
  assert.equal(settings.get().values.uiAnimationsEnabled,false,'an old client cannot reset the shared animation setting');
  for(const value of [null,0,'on'])await assert.rejects(settings.update(9,{...settings.get().values,uiAnimationsEnabled:value}),/must be boolean/);
  await assert.rejects(settings.update(8,settings.get().values),/settings changed/);
});

test('Maintenance API persists animation settings, broadcasts to two clients and restores them after a real server restart',{timeout:30000},async t=>{
  const dir=await fs.mkdtemp(path.join(os.tmpdir(),'stm-maintenance-api-'));
  const probe=net.createServer();await new Promise(r=>probe.listen(0,'127.0.0.1',r));
  const port=probe.address().port;await new Promise(r=>probe.close(r));
  const base='http://127.0.0.1:'+port;let child;
  const sockets=[];
  const stop=async()=>{if(child&&child.exitCode===null){child.kill('SIGTERM');await once(child,'exit');}};
  t.after(async()=>{for(const socket of sockets)socket.terminate();await stop();await fs.rm(dir,{recursive:true,force:true});});
  const start=async()=>{
    child=spawn(process.execPath,[path.resolve(__dirname,'../server/dist/index.js'),'--host=127.0.0.1','--port='+port,'--log-dir='+dir,'--state-dir='+dir+'/state','--process-control-socket='+dir+'/disabled.sock'],
      {cwd:path.resolve(__dirname,'..'),env:{...process.env,STM_ANALYSIS_STATE_FILE:'',STM_PLAYBACK_STATE_FILE:'',STM_CONFIG_FILE:''},stdio:['ignore','ignore','pipe']});
    let log='';child.stderr.on('data',x=>log+=x);
    for(let i=0;i<150;i++){
      assert.equal(child.exitCode,null,log);
      try{if((await fetch(base+'/api/config')).ok)return;}catch{}
      await sleep(30);
    }
    assert.fail('Server startup failed: '+log);
  };
  const get=async route=>(await fetch(base+route)).json();
  const save=body=>fetch(base+'/api/maintenance/frontend-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  await start();
  assert.equal((await get('/api/config')).uiAnimationsEnabled,true);
  const initial=await get('/api/maintenance/frontend-settings');
  const setting=initial.sections.flatMap(s=>s.settings).find(s=>s.key==='uiAnimationsEnabled');
  assert.equal(setting.type,'boolean');assert.equal(setting.apply,'live');assert.match(setting.description,/OS reduced-motion/);
  const received=[[],[]];
  for(let i=0;i<2;i++){
    const socket=new WebSocket(base.replace('http:','ws:')+'/ws');sockets.push(socket);
    socket.on('message',raw=>received[i].push(JSON.parse(raw)));await once(socket,'open');
  }
  const response=await save({revision:initial.revision,values:{...initial.values,uiAnimationsEnabled:false}});
  assert.equal(response.status,200);const updated=await response.json();
  for(let i=0;i<100&&!received.every(messages=>messages.some(m=>m.type==='config:update'&&m.config.uiAnimationsEnabled===false));i++)await sleep(20);
  assert.ok(received.every(messages=>messages.some(m=>m.type==='config:update'&&m.config.uiAnimationsEnabled===false)));
  assert.equal((await get('/api/config')).uiAnimationsEnabled,false);
  assert.equal((await save({revision:initial.revision,values:initial.values})).status,409);
  assert.equal((await save({revision:updated.revision,values:{...updated.values,uiAnimationsEnabled:'false'}})).status,400);
  for(const socket of sockets)socket.terminate();
  await stop();await start();
  assert.equal((await get('/api/config')).uiAnimationsEnabled,false);
  const restored=await get('/api/maintenance/frontend-settings');
  assert.equal(restored.values.uiAnimationsEnabled,false);
  const legacy={...restored.values};delete legacy.uiAnimationsEnabled;
  assert.equal((await save({revision:restored.revision,values:legacy})).status,200);
  assert.equal((await get('/api/config')).uiAnimationsEnabled,false);
});
