  grid-template-columns: minmax(180px, 1fr) minmax(320px, 480px);
}
.stream-target-panel {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-left: 1px solid var(--line);
  background: var(--surface);
  color: var(--text);
}
