import { createHash } from "node:crypto";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import type { SystemCapturePolicy } from "./capturePolicySettings";

const execFileAsync = promisify(execFile);

export type CaptureDocument = { interfaces?: string[]; auto_interfaces?: boolean; include_loopback?: boolean; exclude_interfaces?: string[]; bpf_filter?: string };
export type CaptureCandidate = { name: string; selectable: boolean; reason?: string; selected: boolean };
export type CaptureSettingsResponse = { revision: string; document: CaptureDocument; candidates: CaptureCandidate[]; apply: "capture_restart_required" };
export class CaptureSettingsConflictError extends Error {}
export class CaptureSettingsValidationError extends Error {}

export class CaptureSettings {
  constructor(private readonly stmConfigFile: string, private readonly getPolicy: () => Promise<SystemCapturePolicy>) {}

  async get(): Promise<CaptureSettingsResponse> {
    const text = await readFile(this.stmConfigFile, "utf8");
    const root = parseObject(text);
    const document = captureDocument(root.capture);
    const policy = await this.getPolicy();
    return { revision: revisionOf(text), document, candidates: await this.candidates(root, document, policy), apply: "capture_restart_required" };
  }

  async update(input: { revision: unknown; document: unknown }): Promise<CaptureSettingsResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) throw new CaptureSettingsConflictError("capture config changed on the server; reload before applying");
    const policy = await this.getPolicy();
    const document = validateCaptureDocument(input.document, policy);
    const text = await readFile(this.stmConfigFile, "utf8");
    const root = parseObject(text);
    const existing = root.capture && typeof root.capture === "object" && !Array.isArray(root.capture) ? root.capture as Record<string, unknown> : {};
    root.capture = { ...existing, ...toJson(document) };
    await atomicWrite(this.stmConfigFile, JSON.stringify(root, null, 2) + "\n");
    return this.get();
  }

  private async candidates(root: Record<string, unknown>, document: CaptureDocument, policy: SystemCapturePolicy): Promise<CaptureCandidate[]> {
    const capture = root.capture && typeof root.capture === "object" && !Array.isArray(root.capture) ? root.capture as Record<string, unknown> : {};
    const program = typeof capture.program === "string" && capture.program.trim() ? capture.program : "dumpcap";
    let names: string[] = [];
    try {
      const result = await execFileAsync(program, ["-D"], { timeout: 5000, maxBuffer: 1024 * 1024 });
      names = result.stdout.split("\n").flatMap((line) => line.match(/^\s*\d+\.\s+(\S+)/) ? [line.match(/^\s*\d+\.\s+(\S+)/)![1]] : []);
    } catch { return []; }
    const selected = new Set(document.interfaces ?? []);
    return names.map((name) => {
      const forbidden = policy.guardrails.forbiddenInterfaces.find((pattern) => wildcard(pattern, name));
      const excluded = document.exclude_interfaces?.find((pattern) => wildcard(pattern, name));
      const loopback = name === "lo" && document.include_loopback !== true;
      return forbidden ? { name, selected: selected.has(name), selectable: false, reason: "System policy: " + forbidden }
        : excluded ? { name, selected: selected.has(name), selectable: false, reason: "Capture exclusion: " + excluded }
        : loopback ? { name, selected: selected.has(name), selectable: false, reason: "Loopback is disabled" }
  vlan?: number | string | null;
  stream_name?: string;
};

export type MonitoringTargetGroup = {
  id: string;
  kind: "bidirectional_pair" | "redundancy_set";
  name?: string;
  members: string[];
  paths?: Record<string, string>;
};

export type ProtocolMapDocument = {
  observe_mode?: "all" | "configured_only" | "configured_plus_other";
  protocols: ProtocolRule[];
  target_groups?: MonitoringTargetGroup[];
};

export type ProtocolMapResponse = {
  revision: string;
  path: string;
  document: ProtocolMapDocument;
  apply: "restart_required";
};

