import { useEffect, useRef, useState } from "react";
import { applySetup, getSetupState, previewSetup } from "../api/client";
import { useI18n } from "../i18n";
import { restartableProcesses, useRuntimeStatus } from "../runtimeStatus";
import type { AlertsDocument, ProtocolRule, SetupDraft, SetupPreview, SetupState, StreamListItem } from "../types/api";
import { buildCandidateBundles, candidateProtocolChoices, candidateSubject, selectorEndpointOptions, type TargetProtocolChoice } from "./candidateBundles";
import { confirmedTargetStream, defaultTargetEndpoint, newStreamTarget, ruleList, setupDraftForTarget, targetRulesForStream } from "./monitoringTargetSelection";
import { TargetAlertPolicyPanel } from "./TargetAlertPolicyPanel";
import { Icon } from "./ui/Icon";
import { formatBitrate } from "./format";

type Props = {
  stream: StreamListItem;
  streams: StreamListItem[];
  writable: boolean;
  live: boolean;
  connected: boolean;
  onAlertsSaved: (document: AlertsDocument) => void;
  onInspect: (stream: StreamListItem) => void;
  onReturnLive: () => void;
  onClose: () => void;
  onEditingState: (dirty: boolean, busy: boolean) => void;
};

export function StreamTargetSettings({ stream, streams, writable, live, connected, onAlertsSaved, onInspect, onReturnLive, onClose, onEditingState }: Props) {
  const { t } = useI18n();
  const { runtime, error: runtimeError, replaceRuntime, refresh, restartPending, operation } = useRuntimeStatus();
  const [state, setState] = useState<SetupState | null>(null);
  const [rule, setRule] = useState<ProtocolRule | null>(null);
  const [protocol, setProtocol] = useState<TargetProtocolChoice | "">("");
  const [alerts, setAlerts] = useState<AlertsDocument | null>(null);
  const [preview, setPreview] = useState<{ draft: SetupDraft; result: SetupPreview } | null>(null);
  const [saved, setSaved] = useState<{ rule: ProtocolRule; after: number } | null>(null);
  const [busy, setBusy] = useState(true);
  const [message, setMessage] = useState("");
  const [dirty, setDirty] = useState(false);
  const [confirmRestart, setConfirmRestart] = useState(false);
  const [loadVersion, setLoadVersion] = useState(0);
  const panel = useRef<HTMLElement>(null);
  const request = useRef(false);
  const bundle = buildCandidateBundles([stream], { [stream.streamKey]: protocol === "HLS" ? "" : protocol })[0];
  const matches = state ? targetRulesForStream(stream, state.protocolMap.document.protocols) : [];
  const original = rule?.id ? state?.protocolMap.document.protocols.find(item => item.id === rule.id) : undefined;
  const restarting = operation?.state === "running" || runtime?.processes.some(process => process.activation.state === "restarting");
  const locked = busy || restarting || !writable || !connected;
  const customDecode = ruleList(rule?.decode_as).length > 0;
  const candidates = candidateProtocolChoices(bundle?.source ?? "detected");
  const detectedChoices: TargetProtocolChoice[] = bundle?.protocol === "RTP" || bundle?.protocol === "RTP-FEC" ? ["RTP", "RTP-FEC"] : bundle?.protocol ? [bundle.protocol] : [];
  const choices = [...new Set([...(original ? [original.proto === "RTP" && original.fec ? "RTP-FEC" as const : original.proto] : []), ...(bundle?.source === "detected" ? detectedChoices : candidates)])];
  const confirmed = saved && live && connected && !runtimeError ? confirmedTargetStream(streams, saved.rule, saved.after, runtime) : undefined;
  const pending = restartableProcesses(runtime);
  const stm = runtime?.processes.find(process => process.name === "stm");

  useEffect(() => { onEditingState(dirty, busy); }, [dirty, busy, onEditingState]);

  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    panel.current?.focus();
    return () => { if (opener?.isConnected) opener.focus(); };
  }, []);

  useEffect(() => {
    let active = true;
    setBusy(true); setMessage("");
    void getSetupState().then(next => {
      if (!active) return;
      setState(next); replaceRuntime(next.runtime); setAlerts(next.alerts.document);
      const existing = targetRulesForStream(stream, next.protocolMap.document.protocols);
      if (existing.length === 1) selectRule(existing[0]);
      else { setRule(null); setProtocol(""); }
      setDirty(false); setPreview(null); setSaved(null);
    }).catch((error: unknown) => { if (active) setMessage(error instanceof Error ? error.message : t("streamTarget.loadFailed")); })
      .finally(() => { if (active) setBusy(false); });
    return () => { active = false; };
  }, [loadVersion]);

  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);

  function selectRule(next: ProtocolRule) {
    setRule(next); setProtocol(next.proto === "RTP" && next.fec ? "RTP-FEC" : next.proto);
    setPreview(null); setMessage(""); setSaved(null);
  }
  function change(patch: Partial<ProtocolRule>) {
    setRule(current => current ? { ...current, ...patch } : current);
    setDirty(true); setPreview(null); setSaved(null); setMessage("");
  }
  function chooseProtocol(value: TargetProtocolChoice | "") {
    setProtocol(value); setDirty(true); setPreview(null); setSaved(null); setMessage("");
    if (rule) {
      const { fec: _fec, ...rest } = rule;
      setRule({ ...rest, proto: value === "RTP-FEC" ? "RTP" : value as ProtocolRule["proto"], ...(value === "RTP-FEC" ? { fec: true } : {}) });
    } else if (bundle && value) {
      setRule(newStreamTarget(bundle, value) ?? null);
    }
  }
  function leave(action: () => void) {
    if (!busy && (!dirty || window.confirm(t("streamTarget.discard")))) action();
  }
  async function review() {
    if (!state || !rule || request.current || locked) return;
    request.current = true; setBusy(true); setMessage("");
    const draft = setupDraftForTarget(state, rule, alerts!);
    try { setPreview({ draft, result: await previewSetup(draft) }); }
    catch (error) { setMessage(error instanceof Error ? error.message : t("streamTarget.saveFailed")); }
    finally { request.current = false; setBusy(false); }
  }
  async function save() {
    if (!preview || !rule || request.current || locked) return;
    request.current = true; setBusy(true); setMessage("");
    try {
      const result = await applySetup(preview.draft);
      setState(result.state); setAlerts(result.state.alerts.document); onAlertsSaved(result.state.alerts.document); replaceRuntime(result.runtime);
      setSaved({ rule, after: Math.max(Date.now() / 1000, stream.lastSeen, ...streams.filter(item => item.flows.some(flow => flow.monitoringTargetIds?.includes(rule.id!))).map(item => item.lastSeen)) });
      setPreview(null); setDirty(false);
    } catch (error) { setPreview(null); setMessage(error instanceof Error ? error.message : t("streamTarget.saveFailed")); }
    finally { request.current = false; setBusy(false); }
  }
  async function restart() {
    if (request.current || locked) return;
    request.current = true; setBusy(true); setMessage(""); setConfirmRestart(false);
    try { await restartPending(); }
    catch (error) { setMessage(error instanceof Error ? error.message : t("streamTarget.restartFailed")); }
    finally { request.current = false; setBusy(false); }
  }

  const status = !live ? "returnLive" : !connected || runtimeError || !runtime?.control.available || !stm ? "statusUnavailable"
    : restarting ? "restarting" : stm.activation.state === "restart_failed" ? "restartFailed"
    : stm.activation.state === "restart_required" ? "pending" : stm.state !== "RUNNING" || stm.ready === false ? "serviceNotRunning"
    : saved?.rule.enabled === false || saved?.rule.observe === false ? "disabled"
    : confirmed ? "confirmed" : "waiting";
  return <aside ref={panel} tabIndex={-1} className="stream-target-panel" aria-busy={busy} aria-label={t("streamTarget.title")} onKeyDown={event => {
    if (event.key === "Escape") { event.stopPropagation(); leave(onClose); }
  }}>
    <header className="stream-target-header"><strong>{t("streamTarget.title")}</strong><button type="button" className="icon-only maintenance-secondary-button" disabled={busy} aria-label={t("streamTarget.close")} onClick={() => leave(onClose)}><Icon name="close" size={16} /></button></header>
    <div className="stream-target-content">
