import type { AlertsDocument, ProtocolRule, RuntimeProcessesResponse, SetupDraft, SetupState, StreamListItem } from "../types/api";
import { automaticSelectorEndpoint, buildCandidateBundles, endpointFor, isConfiguredBundle, makeRules, selectorEndpointOptions, type CandidateBundle, type TargetProtocolChoice } from "./candidateBundles";

export function defaultTargetEndpoint(candidate: CandidateBundle) {
  if (candidate.source !== "detected") return undefined;
  return automaticSelectorEndpoint(candidate) ?? (candidate.protocol === "HLS" ? endpointFor(candidate.stream) : undefined);
}

export function newStreamTarget(candidate: CandidateBundle, protocol: TargetProtocolChoice) {
  const next = { ...candidate, protocol };
  const endpoint = defaultTargetEndpoint(next);
  const [rule] = makeRules(next, endpoint ?? selectorEndpointOptions(candidate.stream)[0]);
  if (!rule) return undefined;
  const vlan = candidate.stream.scope.layers.find(layer => layer.kind === "vlan");
  return { ...rule, ...(endpoint ? {} : { endpoints: [] }), ...(vlan?.kind === "vlan" && vlan.id !== undefined ? { vlan: vlan.id } : {}) };
}

export function setupDraftForTarget(state: SetupState, rule: ProtocolRule, alerts: AlertsDocument): SetupDraft {
  const document = state.protocolMap.document;
  const existing = document.protocols.some(item => item.id === rule.id);
  return { revision: state.revision, capture: state.capture.document, alerts,
    protocolMap: { path: state.protocolMap.path, document: { ...document,
      protocols: existing ? document.protocols.map(item => item.id === rule.id ? rule : item) : [...document.protocols, rule] } } };
}

/** Prefer the BE's target IDs; selector matching also finds disabled/pending rules. */
export function targetRulesForStream(stream: StreamListItem, rules: ProtocolRule[]) {
  const ids = new Set(stream.flows.flatMap(flow => flow.monitoringTargetIds ?? []));
  const bundles = buildCandidateBundles([stream], {});
  return rules.filter(rule => rule.id && (ids.has(rule.id) || bundles.some(bundle => {
    if (isConfiguredBundle(bundle, [rule])) return true;
    // Raw traffic has no directional session destination yet. Either explicitly
    // selected endpoint must also find a pending RTP/FEC target after reopening.
    return bundle.source !== "detected" && selectorEndpointOptions(stream).some(endpoint =>
      isConfiguredBundle({ ...bundle, stream: { ...stream, sessionDst: endpoint } }, [rule]));
  })));
}

export function confirmedTargetStream(streams: StreamListItem[], rule: ProtocolRule, after: number, runtime: RuntimeProcessesResponse | null) {
  const stm = runtime?.processes.find(process => process.name === "stm");
  if (!rule.id || rule.enabled === false || rule.observe === false || !runtime?.control.available ||
      stm?.activation.state !== "current" || stm.state !== "RUNNING" || stm.ready === false) return undefined;
  const since = Math.max(after, (stm.startedAt ?? 0) / 1000);
  return streams.find(stream => stream.proto === rule.proto && stream.active && stream.flows.some(flow =>
    flow.active && flow.lastSeen > since && flow.monitoringTargetIds?.includes(rule.id!)));
}

export function ruleList(value: string | string[] | undefined): string[] {
  return typeof value === "string" ? [value] : value ?? [];
