type Props = { status: string; error: string; onAdd: () => void; onReset: () => void; onSave: () => void; onDone: () => void; onCancel: () => void };
export function InspectorEditControls({ status, error, onAdd, onReset, onSave, onDone, onCancel }: Props) {
  return <><button type="button" className="dashboard-action-button icon-only" disabled={status === "saving"} onClick={onAdd} aria-label="Add cell" title="Add cell"><Icon name="add" size={15} /></button>
    <button type="button" className="dashboard-action-button icon-only" disabled={status === "saving"} onClick={onReset} aria-label="Reset layout" title="Reset layout"><Icon name="reset" size={15} /></button>
    <button type="button" className="dashboard-action-button icon-only primary" disabled={status === "saving"} onClick={onSave} aria-label="Save layout" title="Save layout"><Icon name={status === "saved" ? "done" : "save"} size={15} /></button>
    <button type="button" className="dashboard-action-button icon-only" disabled={status === "saving"} onClick={onDone} aria-label="Done editing" title="Done editing"><Icon name="done" size={15} /></button>
    <button type="button" className="dashboard-action-button icon-only" disabled={status === "saving"} onClick={onCancel} aria-label="Cancel editing" title="Cancel editing"><Icon name="close" size={15} /></button>
    {error && <span role="alert" className="inspector-layout-error" title={error}>{error}</span>}</>;
}
export function InspectorUnsavedDialog({ open, saving, error, onSave, onDiscard, onContinue }: { open: boolean; saving: boolean; error: string; onSave: () => void; onDiscard: () => void; onContinue: () => void }) {
  const { locale } = useI18n();
  if (!open) return null;
  const ja = locale === "ja";
  return <div className="inspector-edit-backdrop" onKeyDown={event => { event.stopPropagation(); if (event.key === "Escape" && !saving) onContinue(); }}>
    <section role="dialog" aria-modal="true" aria-label={ja ? "未保存のレイアウト" : "Unsaved layout"} className="inspector-unsaved-dialog">
      <p>{ja ? "レイアウトの変更を保存しますか？" : "Save the layout changes before leaving?"}</p>{error && <p role="alert">{error}</p>}
      <button autoFocus disabled={saving} onClick={onSave}>{ja ? "保存して終了" : "Save and leave"}</button>
      <button disabled={saving} onClick={onDiscard}>{ja ? "破棄して終了" : "Discard and leave"}</button>
      <button disabled={saving} onClick={onContinue}>{ja ? "編集を続ける" : "Continue editing"}</button>
    </section>
  </div>;
}
