  const [alerts, setAlerts] = useState<AlertsDocument | null>(null);
  const [preview, setPreview] = useState<{ draft: SetupDraft; result: SetupPreview } | null>(null);
  const [saved, setSaved] = useState<{ rule: ProtocolRule; after: number } | null>(null);
  const [busy, setBusy] = useState(true);
  const [message, setMessage] = useState("");
  const [dirty, setDirty] = useState(false);
