    setPreview(null); setMessage(""); setSaved(null);
  }
  function change(patch: Partial<ProtocolRule>) {
    setRule(current => current ? { ...current, ...patch } : current);
    setDirty(true); setPreview(null); setSaved(null); setMessage("");
  }
  function chooseProtocol(value: TargetProtocolChoice | "") {
    setProtocol(value); setDirty(true); setPreview(null); setSaved(null); setMessage("");
    if (rule) {
      const { fec: _fec, ...rest } = rule;
      setRule({ ...rest, proto: value === "RTP-FEC" ? "RTP" : value as ProtocolRule["proto"], ...(value === "RTP-FEC" ? { fec: true } : {}) });
    } else if (bundle && value) {
      setRule(newStreamTarget(bundle, value) ?? null);
    }
  }
  function leave(action: () => void) {
    if (!busy) onRequestLeave(() => { setDirty(false); action(); });
  }
  async function review() {
    if (!state || !rule || request.current || locked) return;
    request.current = true; setBusy(true); setMessage("");
    const draft = setupDraftForTarget(state, rule, alerts!);
    try { setPreview({ draft, result: await previewSetup(draft) }); }
    catch (error) { setMessage(error instanceof Error ? error.message : t("streamTarget.saveFailed")); }
    finally { request.current = false; setBusy(false); }
  }
  async function save() {
    if (!preview || !rule || request.current || locked) return;
    request.current = true; setBusy(true); setMessage("");
    try {
      const result = await applySetup(preview.draft);
      setState(result.state); setAlerts(result.state.alerts.document); onAlertsSaved(result.state.alerts.document); replaceRuntime(result.runtime);
      setSaved({ rule, after: Math.max(Date.now() / 1000, stream.lastSeen, ...streams.filter(item => item.flows.some(flow => flow.monitoringTargetIds?.includes(rule.id!))).map(item => item.lastSeen)) });
      setPreview(null); setDirty(false);
    } catch (error) { setPreview(null); setMessage(error instanceof Error ? error.message : t("streamTarget.saveFailed")); }
    finally { request.current = false; setBusy(false); }
  }
  async function restart() {
    if (request.current || locked) return;
    request.current = true; setBusy(true); setMessage(""); setConfirmRestart(false);
    try { await restartPending(); }
    catch (error) { setMessage(error instanceof Error ? error.message : t("streamTarget.restartFailed")); }
    finally { request.current = false; setBusy(false); }
  }

  const status = !live ? "returnLive" : !connected || runtimeError || !runtime?.control.available || !stm ? "statusUnavailable"
    : restarting ? "restarting" : stm.activation.state === "restart_failed" ? "restartFailed"
    : stm.activation.state === "restart_required" ? "pending" : stm.state !== "RUNNING" || stm.ready === false ? "serviceNotRunning"
    : saved?.rule.enabled === false || saved?.rule.observe === false ? "disabled"
    : confirmed ? "confirmed" : "waiting";
  return <aside ref={panel} tabIndex={-1} className="stream-target-panel" aria-busy={busy} aria-label={t("streamTarget.title")} onKeyDown={event => {
    if (event.key === "Escape") { event.stopPropagation(); leave(onClose); }
  }}>
    <header className="stream-target-header"><strong>{t("streamTarget.title")}</strong><button type="button" className="icon-only maintenance-secondary-button" disabled={busy} aria-label={t("streamTarget.close")} onClick={() => leave(onClose)}><Icon name="close" size={16} /></button></header>
    <div className="stream-target-content">
      <p>{t("streamTarget.selected")}: <strong>{stream.displayName ?? stream.label}</strong></p>
      <p className="stream-target-subject">{bundle ? candidateSubject(bundle) : stream.streamKey}</p>
      <p>{t("streamTarget.detected")}: {stream.proto} · {stream.interfaceName ?? "—"}</p>
      <p className="protocol-map-notice">{t("streamTarget.sessionHint")}</p>
      {!writable && <p role="status">{t("streamTarget.readOnly")}</p>}
      {!connected && <p role="status">{t("streamTarget.disconnected")}</p>}
      {message && <p role="alert" className="service-operation-error">{message}</p>}
      {busy && <p role="status">{t("streamTarget.working")}</p>}
      {!state && !busy && <button type="button" onClick={() => setLoadVersion(value => value + 1)}>{t("streamTarget.reload")}</button>}
      {state && <>
        <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => leave(() => setLoadVersion(value => value + 1))}>{t("streamTarget.reload")}</button>
        {matches.length > 1 && <label>{t("streamTarget.chooseTarget")}<select value={original?.id ?? ""} disabled={locked} onChange={event => {
          const next = matches.find(item => item.id === event.target.value);
          if (next) leave(() => { selectRule(next); setAlerts(state.alerts.document); setDirty(false); });
        }}><option value="" disabled>{t("streamTarget.chooseTarget")}</option>{matches.map(item => <option key={item.id} value={item.id}>{item.stream_name ?? item.id}</option>)}</select></label>}
        {!matches.length && !bundle && <p>{t("streamTarget.unsupported")}</p>}
        {(rule || (!matches.length && bundle)) && <form onSubmit={event => { event.preventDefault(); void review(); }}>
          <p><strong>{t(original ? "streamTarget.edit" : "streamTarget.add")}</strong>{rule?.id && <small className="stream-target-id">{rule.id}</small>}</p>
          <fieldset disabled={locked || Boolean(saved)}>
            <label>{t("streamTarget.protocol")}<select required value={protocol} disabled={customDecode || choices.length === 1 && Boolean(original)} onChange={event => chooseProtocol(event.target.value as TargetProtocolChoice)}><option value="" disabled>{t("streamTarget.chooseProtocol")}</option>{choices.map(value => <option key={value} value={value}>{value}</option>)}</select></label>
            {rule && <>
              <label>{t("streamTarget.name")}<input maxLength={128} value={rule.stream_name ?? ""} onChange={event => change({ stream_name: event.target.value || undefined })} /></label>
              {!original && !defaultTargetEndpoint(bundle!) && <label>{t("streamTarget.stableEndpoint")}<select required value={ruleList(rule.endpoints)[0] ?? ""} onChange={event => change({ endpoints: [event.target.value] })}><option value="" disabled>{t("streamTarget.chooseEndpoint")}</option>{selectorEndpointOptions(stream).map(endpoint => <option key={endpoint}>{endpoint}</option>)}</select></label>}
              {(original || defaultTargetEndpoint(bundle!)) && <label>{t(rule.hosts || rule.domains ? "streamTarget.hosts" : "streamTarget.endpoints")}<textarea required disabled={customDecode} value={ruleList(rule.hosts ?? rule.domains ?? rule.endpoints).join("\n")} onChange={event => {
                const values = event.target.value.split("\n"); change(rule.hosts ? { hosts: values } : rule.domains ? { domains: values } : { endpoints: values });
              }} /></label>}
              {customDecode && <p className="protocol-map-notice">{t("streamTarget.customDecode")}</p>}
              {protocol === "RTP-FEC" && <p className="protocol-map-notice">{t("streamTarget.fecHint")}</p>}
              <label>{t("streamTarget.interfaces")}<input value={ruleList(rule.interfaces).join(", ")} onChange={event => change({ interfaces: event.target.value.trim() ? event.target.value.split(",").map(value => value.trim()) : undefined })} /></label>
              <label>{t("streamTarget.vlan")}<select value={rule.vlan === undefined ? "any" : rule.vlan === null ? "untagged" : "id"} onChange={event => change({ vlan: event.target.value === "any" ? undefined : event.target.value === "untagged" ? null : 0 })}><option value="any">{t("streamTarget.any")}</option><option value="untagged">{t("streamTarget.untagged")}</option><option value="id">VLAN ID</option></select></label>
              {rule.vlan !== undefined && rule.vlan !== null && <label>VLAN ID<input type="number" required min={0} max={4094} value={rule.vlan} onChange={event => change({ vlan: event.target.value })} /></label>}
              <label className="stream-target-check"><input type="checkbox" checked={rule.enabled !== false} onChange={event => change({ enabled: event.target.checked })} />{t("streamTarget.enabled")}</label>
              <label className="stream-target-check"><input type="checkbox" checked={rule.observe !== false} onChange={event => change({ observe: event.target.checked })} />{t("streamTarget.observe")}</label>
              {alerts && <TargetAlertPolicyPanel target={{ id: rule.id!, proto: rule.proto, target_type: rule.target_type ?? "single", title: rule.stream_name, ...(rule.fec ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }} document={alerts} metrics={state.alerts.metrics} protocols={state.alerts.protocols} flowRoles={state.alerts.flowRoles} busy={locked} onDocument={next => { setAlerts(next); setDirty(true); setPreview(null); }} />}
            </>}
          </fieldset>
          {!saved && <button type="submit" className="maintenance-save-button" disabled={locked || !rule || !protocol}>{t("streamTarget.review")}</button>}
        </form>}
        {preview && <section className="stream-target-review" aria-label={t("streamTarget.review")}>
          <h3>{t("streamTarget.review")}</h3>
          <p>{t("streamTarget.reviewHint")}</p>
          <ul>{preview.result.changes.filter(item => item.action === "update").map(item => <li key={item.area}>{item.area} · {item.restart ? t("streamTarget.restartRequired", { name: item.restart }) : "—"}</li>)}</ul>
          {preview.result.warnings.map(warning => <p key={warning}>{warning}</p>)}
          <button type="button" className="maintenance-save-button" disabled={locked} onClick={() => void save()}>{t("streamTarget.save")}</button>
        </section>}
        {saved && <section className="stream-target-verification" aria-live="polite">
          <h3>{t("streamTarget.saved")}</h3><p>{t("streamTarget." + status)}</p>
          {!live && writable && <button type="button" className="maintenance-secondary-button" onClick={onReturnLive}>{t("streamTarget.live")}</button>}
          {stm?.activation.error && <p role="alert">{stm.activation.error}</p>}
          <button type="button" className="maintenance-secondary-button" disabled={!connected || busy} onClick={() => void refresh()}>{t("streamTarget.refresh")}</button>
          {pending.length > 0 && <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting} onClick={() => setConfirmRestart(true)}>{t("streamTarget.restart")}</button>}
          {confirmed && <><p>{confirmed.proto} · {formatBitrate(confirmed.bitrate.value)}</p><button type="button" className="maintenance-save-button" onClick={() => onInspect(confirmed)}>{t("streamTarget.inspect")}</button></>}
          <button type="button" className="maintenance-secondary-button" disabled={busy || restarting} onClick={() => { setSaved(null); setMessage(""); }}>{t("streamTarget.continueEditing")}</button>
        </section>}
        {confirmRestart && <section role="alertdialog" aria-label={t("streamTarget.restart")}>
          <p>{t("streamTarget.restartHint")}</p><ul>{pending.map(process => <li key={process.name}>{process.name}</li>)}</ul>
          <button type="button" disabled={busy} onClick={() => setConfirmRestart(false)}>{t("streamTarget.cancel")}</button>
          <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting || !pending.length} onClick={() => void restart()}>{t("streamTarget.restart")}</button>
        </section>}
      </>}
    </div>
  </aside>;
}
}

