  background: var(--accent);
  color: var(--text-inverse);
:root,
:root[data-theme="light"] {
  color-scheme: light;
  --font-sans: "Aptos", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-size-xs: 11px;
  --font-size-sm: 13px;
  --font-size-md: 14px;
  --font-size-lg: 16px;
  --font-size-xl: 20px;
  --line-height-compact: 1.25;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --radius-sm: 3px;
  --radius-md: 5px;
  --radius-lg: 8px;
  --control-height: 30px;
  --header-control-height: var(--control-height);
  --header-control-height-compact: 24px;
  --pane-header-height: 36px;
  --context-bar-height: 40px;
  --bg: #f6f7f9;
  --bg-subtle: #eef1f5;
  --surface: #ffffff;
  --surface-raised: #ffffff;
  --surface-muted: #f7f8fa;
  --panel: #ffffff;
  --panel-strong: #ffffff;
  --line: #d9dee7;
  --line-strong: #c8d0db;
  --text: #2c333d;
  --text-strong: #141922;
  --muted: #687386;
  --accent: #5b47d6;
  --accent-2: #168b87;
  --accent-soft: rgba(91, 71, 214, .10);
  --accent-border: rgba(91, 71, 214, .30);
  --success: #16824f;
  --success-soft: rgba(22, 130, 79, .11);
  --warning: #a56308;
  --warning-soft: rgba(165, 99, 8, .12);
  /* Async UI status, separate from monitored alert/threshold colors. */
  --async-loading-bg: #fff8e7;
  --async-loading-border: #e6d3a7;
  --async-loading-ink: #806024;
  --async-attention-bg: #fff0df;
  --async-attention-border: #e6bd91;
  --async-attention-ink: #92541c;
  --error: #be3f3f;
  --error-soft: rgba(190, 63, 63, .11);
  --danger: #be3f3f;
