import type { ReactNode } from "react";
import { Icon, type IconName } from "./Icon";

type PaneHeaderProps = {
  title?: ReactNode;
  meta?: ReactNode;
  actions?: ReactNode;
  trailingActions?: ReactNode;
  className?: string;
  icon?: IconName;
};

export function PaneHeader({ title, meta, actions, trailingActions, className = "", icon }: PaneHeaderProps) {
  return (
    <header className={`pane-header ${className}`.trim()}>
      {(title || meta) && (
        <div className="pane-header-copy">
          {icon && <Icon className="pane-header-icon" name={icon} size={14} />}
          {title && <strong className="pane-header-title" data-tooltip={typeof title === "string" ? title : undefined}>{title}</strong>}
          {meta && <span className="pane-header-meta">{meta}</span>}
        </div>
      )}
      {actions && <div className="pane-header-actions">{actions}</div>}
      {trailingActions && <div className="pane-header-trailing-actions">{trailingActions}</div>}
    </header>
  );
}


type PaneFrameProps = {
  header: ReactNode;
  children: ReactNode;
  className?: string;
};

export function PaneFrame({ header, children, className = "" }: PaneFrameProps) {
  return (
    <section className={("pane-frame " + className).trim()}>
      {header}
      <div className="pane-body">{children}</div>
    </section>
  );
}
