import { createContext, useCallback, useContext, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type MutableRefObject, type ReactNode } from "react";
import { Icon } from "./ui/Icon";
import { getAnalysisSource, type AnalysisSource } from "../analysisSource";
import type { EventMarkerBucket } from "../timelineMarkers";
import type { EventLogItem } from "../types/api";
import type { TimelineAnchorName } from "../timelineCursor";
import { TimelineEventBucketPopover } from "./TimelineEventBucketPanel";
import { SearchInput } from "./ui/SearchInput";
import { PaneSplitter } from "./ui/PaneSplitter";
import { useI18n } from "../i18n";
import { readInvestigationDockHeight, rememberInvestigationDockHeight } from "../investigationPreferences";

export type TimelineDockBridge = {
  select: (event: EventLogItem) => void;
  reveal: (event: EventLogItem) => void;
  canReveal: (event: EventLogItem) => boolean;
  setAnchor: (name: TimelineAnchorName, event: EventLogItem) => void;
  refresh: (bucket: EventMarkerBucket) => EventMarkerBucket | undefined;
};
export type TimelineDockActions = {
  select: (event: EventLogItem, origin: string) => void;
  reveal: (event: EventLogItem, origin: string) => void;
  setAnchor: (name: TimelineAnchorName, event: EventLogItem, origin: string) => void;
  openEvents: (event: EventLogItem) => void;
  refreshMarkers: () => void;
};
type EventSelection = { origin: string; bucket: EventMarkerBucket; source: AnalysisSource; epoch?: number; revision: number };

export type InvestigationDockTab = "events" | "alerts";
type DockContext = {
  activeTab: InvestigationDockTab | null;
  open: (tab: InvestigationDockTab) => void;
  close: () => void;
  queries: Record<InvestigationDockTab, string>;
  changeQuery: (tab: InvestigationDockTab, query: string) => void;
  eventSelection: EventSelection | null;
  preview: EventLogItem | undefined;
  previewEvent: (event?: EventLogItem) => void;
  openTimelineEvents: (origin: string, bucket: EventMarkerBucket) => void;
  clearEvents: () => void;
  refreshEvents: () => void;
  registerTimeline: (origin: string, bridge: MutableRefObject<TimelineDockBridge>) => () => void;
  findTimeline: (origin: string) => TimelineDockBridge | undefined;
};
const InvestigationDockContext = createContext<DockContext | null>(null);

export function InvestigationDockProvider({ children }: { children: ReactNode }) {
  const [activeTab, setActiveTab] = useState<InvestigationDockTab | null>(null);
  const [queries, setQueries] = useState({ events: "", alerts: "" });
  const changeQuery = useCallback((tab: InvestigationDockTab, query: string) => setQueries(current => ({ ...current, [tab]: query })), []);
  const [eventSelection, setEventSelection] = useState<EventSelection | null>(null);
  const [preview, setPreview] = useState<EventLogItem>();
  const nextRevision = useRef(0);
  const bridges = useRef(new Map<string, MutableRefObject<TimelineDockBridge>>());
  const findTimeline = useCallback((origin: string) => bridges.current.get(origin)?.current, []);
  const registerTimeline = useCallback((origin: string, bridge: MutableRefObject<TimelineDockBridge>) => {
    bridges.current.set(origin, bridge);
    return () => { if (bridges.current.get(origin) === bridge) bridges.current.delete(origin); };
  }, []);
  const opener = useRef<HTMLElement | null>(null);
  const open = useCallback((tab: InvestigationDockTab) => {
    if (document.activeElement instanceof HTMLElement && document.activeElement !== document.body && !document.activeElement.closest(".investigation-dock")) opener.current = document.activeElement;
    setActiveTab(tab);
    setPreview(undefined);
  }, []);
  const close = useCallback(() => {
    setActiveTab(null);
    setQueries({ events: "", alerts: "" });
    setEventSelection(null);
    setPreview(undefined);
    const target = opener.current?.isConnected && opener.current.getClientRects().length ? opener.current : document.querySelector<HTMLElement>(".investigation-workspace-main");
    target?.focus({ preventScroll: true });
  }, []);
  const clearEvents = useCallback(() => { setEventSelection(null); setPreview(undefined); setQueries(current => ({ ...current, events: "" })); }, []);
  const openTimelineEvents = useCallback((origin: string, bucket: EventMarkerBucket) => {
    const source = getAnalysisSource();
    setQueries(current => ({ ...current, events: "" }));
    setEventSelection({ origin, bucket: { ...bucket, events: [...bucket.events], summaries: bucket.summaries ? [...bucket.summaries] : undefined }, source, epoch: source.epoch, revision: ++nextRevision.current });
    open("events");
  }, [open]);
  const refreshEvents = useCallback(() => {
    setPreview(undefined);
    const revision = ++nextRevision.current;
    setEventSelection(current => current ? { ...current, bucket: bridges.current.get(current.origin)?.current.refresh(current.bucket) ?? current.bucket, revision } : null);
  }, []);
  const value = useMemo(() => ({ activeTab, open, close, queries, changeQuery, eventSelection, preview, previewEvent: setPreview, openTimelineEvents, clearEvents, refreshEvents, registerTimeline, findTimeline }),
    [activeTab, open, close, queries, changeQuery, eventSelection, preview, openTimelineEvents, clearEvents, refreshEvents, registerTimeline, findTimeline]);
  return <InvestigationDockContext.Provider value={value}>{children}</InvestigationDockContext.Provider>;
}

export function useInvestigationDock() { return useContext(InvestigationDockContext); }

/** The dock is a layout row, never an overlay on either the main pane or Inspector. */
export function InvestigationWorkspace({ children, events, alerts, timelineActions, selectedEventId }: { children: ReactNode; events?: ReactNode; alerts?: ReactNode; timelineActions?: TimelineDockActions; selectedEventId?: string | null }) {
  const dock = useInvestigationDock();
  const { t } = useI18n();
  const source = getAnalysisSource(), sourceEpoch = source.epoch;
  useLayoutEffect(() => {
    const selection = dock?.eventSelection;
    if (selection && (selection.source !== source || selection.epoch !== sourceEpoch)) dock.clearEvents();
  }, [source, sourceEpoch, dock?.eventSelection, dock?.clearEvents]);
  const host = useRef<HTMLDivElement>(null);
  const [availableHeight, setAvailableHeight] = useState(600);
  const [preferredHeight, setPreferredHeight] = useState(readInvestigationDockHeight);
  const [resizing, setResizing] = useState(false);
  const drag = useRef<{ id: number; y: number; height: number; lastHeight: number } | null>(null);
  const finishDrag = useCallback(() => {
    if (drag.current) rememberInvestigationDockHeight(drag.current.lastHeight);
    drag.current = null;
    setResizing(false);
  }, []);
  useLayoutEffect(() => {
    if (!host.current) return;
    const measure = () => setAvailableHeight(host.current?.clientHeight ?? 600);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(host.current);
    return () => observer.disconnect();
  }, []);
  const minimum = Math.min(180, availableHeight * 0.35);
  const maximum = Math.max(minimum, Math.min(availableHeight * 0.6, availableHeight - 280));
  const limits = useRef({ minimum, maximum });
  limits.current = { minimum, maximum };
  useLayoutEffect(() => {
    const move = (event: PointerEvent) => {
      if (drag.current?.id !== event.pointerId) return;
      const { minimum, maximum } = limits.current;
      const height = Math.min(maximum, Math.max(minimum, drag.current.height + drag.current.y - event.clientY));
      drag.current.lastHeight = height;
      setPreferredHeight(height);
    };
    const finish = (event: PointerEvent) => { if (drag.current?.id === event.pointerId) finishDrag(); };
    const cancel = finishDrag;
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", finish);
    window.addEventListener("pointercancel", finish);
    window.addEventListener("blur", cancel);
    return () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", finish);
      window.removeEventListener("pointercancel", finish);
      window.removeEventListener("blur", cancel);
    };
  }, [finishDrag]);
  const clamp = (height: number) => Math.min(maximum, Math.max(minimum, height));
  const height = clamp(preferredHeight ?? availableHeight * 0.3);
  const opened = dock?.activeTab !== null && dock?.activeTab !== undefined;
  const style = { "--investigation-dock-height": `${height}px` } as CSSProperties;
  return <div ref={host} className={`investigation-workspace${opened ? " has-investigation-dock" : ""}`} style={style}>
    <div className="investigation-workspace-main" tabIndex={-1}>{children}</div>
    {opened && <>
      <PaneSplitter className="investigation-dock-splitter" label="Resize investigation dock" orientation="horizontal" dragging={resizing} style={{ bottom: height }}
        aria-valuemin={Math.round(minimum)} aria-valuemax={Math.round(maximum)} aria-valuenow={Math.round(height)} tabIndex={0}
        onPointerDown={event => {
          if (event.button !== 0) return;
          event.preventDefault(); event.currentTarget.focus({ preventScroll: true }); event.currentTarget.setPointerCapture(event.pointerId);
          drag.current = { id: event.pointerId, y: event.clientY, height, lastHeight: height };
          setResizing(true);
        }} onLostPointerCapture={finishDrag}
        onKeyDown={event => {
          if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); finishDrag(); dock.close(); return; }
          if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
          event.preventDefault(); event.stopPropagation();
          const next = clamp(event.key === "Home" ? minimum : event.key === "End" ? maximum : height + (event.key === "ArrowUp" ? 24 : -24));
          setPreferredHeight(next); rememberInvestigationDockHeight(next);
        }} />
    <section className="investigation-dock" aria-label="Investigation dock" onKeyDown={event => {
      if (event.key === "Escape" && !event.defaultPrevented) { event.preventDefault(); event.stopPropagation(); finishDrag(); dock.close(); }
    }}>
      <header className="pane-header investigation-dock-header">
        <div role="tablist" aria-label="Investigation panels">
          {(["events", "alerts"] as const).map(tab => <button key={tab} id={`investigation-tab-${tab}`} type="button" role="tab"
            tabIndex={dock.activeTab === tab ? 0 : -1} aria-selected={dock.activeTab === tab} aria-controls={`investigation-panel-${tab}`}
            onKeyDown={event => {
              if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
              event.preventDefault(); event.stopPropagation();
              const next = event.key === "Home" ? "events" : event.key === "End" ? "alerts" : tab === "events" ? "alerts" : "events";
              dock.open(next); document.getElementById(`investigation-tab-${next}`)?.focus({ preventScroll: true });
            }} onClick={() => dock.open(tab)}>{tab === "events" ? "Event details" : "Alert center"}</button>)}
        </div>
        <div className="pane-header-actions">
          <SearchInput className="pane-search investigation-search" value={dock.queries[dock.activeTab!]}
            onChange={query => dock.changeQuery(dock.activeTab!, query)} maxLength={256}
            label={t(dock.activeTab === "events" ? "dock.searchEvents" : "dock.searchAlerts")}
            placeholder={t(dock.activeTab === "events" ? "dock.searchEventsHint" : "dock.searchAlertsHint")} />
        </div>
        <button type="button" className="investigation-dock-close" aria-label="Close investigation dock" onClick={dock.close}><Icon name="close" size={16} /></button>
      </header>
      <div className="investigation-dock-panels">
        <div id="investigation-panel-events" role="tabpanel" aria-labelledby="investigation-tab-events" hidden={dock.activeTab !== "events"}>{events ?? <TimelineEventDockPanel actions={timelineActions} selectedEventId={selectedEventId} />}</div>
        <div id="investigation-panel-alerts" role="tabpanel" aria-labelledby="investigation-tab-alerts" hidden={dock.activeTab !== "alerts"}>{alerts ?? <p className="investigation-dock-empty">No Alerts available.</p>}</div>
      </div>
    </section></>}
  </div>;
}

function TimelineEventDockPanel({ actions, selectedEventId }: { actions?: TimelineDockActions; selectedEventId?: string | null }) {
  const dock = useInvestigationDock()!;
  const selection = dock.eventSelection, source = getAnalysisSource();
  if (!selection || selection.source !== source || selection.epoch !== source.epoch) return <p className="investigation-dock-empty">Select a Timeline event to view its details.</p>;
  const { origin, bucket, revision } = selection;
  const bridge = () => dock.findTimeline(origin);
  return <TimelineEventBucketPopover key={`${origin}:${bucket.key}:${bucket.laneKey ?? "rail"}:${revision}`} bucket={bucket}
    query={dock.queries.events}
    embedded active={dock.activeTab === "events"} selectedEventId={selectedEventId} onClose={dock.close}
    onPreviewEvent={(_id, event) => dock.previewEvent(event)}
    onSelectEvent={event => { const target = bridge(); if (target) target.select(event); else actions?.select(event, origin); }}
    canRevealEvent={event => bridge()?.canReveal(event) ?? (!!event.streamKey && !!actions)}
    onRevealEvent={event => { const target = bridge(); if (target) target.reveal(event); else actions?.reveal(event, origin); }}
    onSetAnchor={(name, event) => { const target = bridge(); if (target) target.setAnchor(name, event); else actions?.setAnchor(name, event, origin); }}
    onOpenEvents={actions ? actions.openEvents : undefined} onRefresh={dock.refreshEvents}
    onRefreshMarkers={actions ? () => { dock.clearEvents(); actions.refreshMarkers(); } : undefined} />;
}
import { useCallback, useRef, useState } from "react";

export function useStreamTargetGuard() {
  const status = useRef({ dirty: false, busy: false });
  const [pending, setPending] = useState<(() => void) | null>(null);
  const requestLeave = useCallback((action: () => void) => {
    if (status.current.busy) return;
    if (status.current.dirty) { setPending(() => action); return; }
    action();
  }, []);
  const discard = () => {
    const action = pending;
    setPending(null);
    status.current = { dirty: false, busy: false };
    action?.();
  };
  return { status, pending: pending !== null, requestLeave, discard, cancel: () => setPending(null) };
}
