.is-docked .timeline-event-detail-controls { gap: 4px; padding-top: 3px; padding-bottom: 3px; }
.is-docked .timeline-event-detail-controls span { margin-right: 0; }
.is-docked .timeline-event-snapshot { margin-right: auto; color: var(--muted); font-size: var(--font-size-xs); }
.is-docked .timeline-event-detail-controls, .is-docked .timeline-event-detail-note, .is-docked .timeline-event-detail-status { padding-left: var(--space-2); padding-right: var(--space-2); }
.is-docked .timeline-event-detail-controls button, .is-docked .timeline-event-detail-status button {
  min-height: 24px; padding: 2px 6px; border: 1px solid var(--line); border-radius: var(--radius-sm);
  background: var(--surface); color: var(--text); font-size: var(--font-size-xs);
}
.is-docked .timeline-event-detail-controls button:disabled { color: var(--muted); opacity: .5; cursor: default; }
.is-docked .timeline-event-bucket-item.selected,

export function App() {
  return <InvestigationDockProvider><AppContent /></InvestigationDockProvider>;
}

function AppContent() {
  const source = useAnalysisSource();
  const runtimeStatus = useRuntimeStatus();
  const { locale, t } = useI18n();
  const initialParams = new URLSearchParams(window.location.search);
  const [standaloneView, setStandaloneView] = useState(() => standaloneViewFromPath(window.location.pathname));
  const navigationGuard = useRef<(action: () => void) => void>(action => action());
  const selectionGuard = useRef<(action: () => void) => void>(action => action());
  const paneCloseGuard = useRef<(action: () => void) => void>(action => action());
  const [activeTab, setActiveTabRaw] = useState<MainTab>("streams");
  const setActiveTab = (tab: MainTab) => navigationGuard.current(() => setActiveTabRaw(tab));
  const activateInvestigationTab = (tab: MainTab) => {
    if (standaloneView) {
      const next: StandaloneView = tab === "streams" || tab === "timeline" || tab === "events" || tab === "detail" ? tab : null;
      const url = new URL(window.location.href);
      url.pathname = next ? `/view/${next}` : "/";
      window.history.replaceState(null, "", url);
      setStandaloneView(next);
    }
    setActiveTabRaw(tab);
  };
  const [inspectorWorkspaceReturnTab, setInspectorWorkspaceReturnTab] = useState<MainTab | null>(null);
  const [captureHealth, setCaptureHealth] = useState<CaptureHealthSnapshot | null>(null);
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    const saved = window.localStorage.getItem("stm-theme");
    return saved === "dark" ? "dark" : "light";
  });
  const [streamTarget, setStreamTarget] = useState<StreamListItem | null>(null);
  const targetGuard = useStreamTargetGuard();
  const streamTargetGuard = targetGuard.status;
  const leaveStreamTarget = targetGuard.requestLeave;
  const [selectedStreamKey, setSelectedStreamKeyRaw] = useState<string | null>(() => initialParams.get("streamKey"));
  const setSelectedStreamKey = (value: string | null) => selectionGuard.current(() => setSelectedStreamKeyRaw(value));
  const [selectedFlowKey, setSelectedFlowKeyRaw] = useState<string | null>(() => initialParams.get("flowKey"));
  const setSelectedFlowKey = (value: string | null) => selectionGuard.current(() => setSelectedFlowKeyRaw(value));
  const [dismissedRecentAlertKeys, setDismissedRecentAlertKeys] = useState<Set<string>>(() => new Set());
  const [selectedInterfaceKey, setSelectedInterfaceKeyRaw] = useState<string | null>(() => initialParams.get("interfaceKey"));
  const setSelectedInterfaceKey = (value: string | null) => selectionGuard.current(() => setSelectedInterfaceKeyRaw(value));
  const [query, setQuery] = useState(() => initialParams.get("query") ?? "");
  const [expandLevel, setExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("expand")));
  const [streamsViewMode, setStreamsViewMode] = useState<StreamsViewMode>(() => streamsViewModeFromParam(initialParams.get("streamsView")));
  const [streamsRankTarget, setStreamsRankTarget] = useState<StreamsRankTarget>(() => streamsRankTargetFromParam(initialParams.get("streamsTarget")));
  const [streamsSortOrder, setStreamsSortOrder] = useState<StreamsSortOrder>(() => streamsSortOrderFromParam(initialParams.get("streamsOrder")));
  const [timelineExpandLevel, setTimelineExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("timelineExpand") ?? initialParams.get("expand")));
  const [detailMode, setDetailMode] = useState<DetailMode>(() => detailModeFromParam(initialParams.get("mode")));
  const [metricsRange, setMetricsRange] = useState(() => rangeFromParam(initialParams.get("metricsRange") ?? initialParams.get("range"), "5m"));
//  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "5m"));
  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "1h"));
  const [eventsRange, setEventsRange] = useState(() => rangeFromParam(initialParams.get("range"), "24h"));
  const [dashboardRange, setDashboardRange] = useState(() => rangeFromParam(initialParams.get("dashboardRange"), "1h"));
  const [dashboardSelectedTimeSec, setDashboardSelectedTimeSec] = useState<number | null>(null);
  const [inspectorSettingsCell, setInspectorSettingsCell] = useState<{ surface: "workspace" | "pane"; id: string } | null>(null);
  const [inspectorLayoutPreferences, setInspectorLayoutPreferences] = useState<Record<string, string>>(() => { try { return JSON.parse(localStorage.getItem("stm-inspector-layout-selections") ?? "{}"); } catch { return {}; } });
  const paneRestoreState = useRef<InspectorContextState | null>(null);
  const workspaceEditor = useInspectorLayoutEditor<InspectorLayout>(saveInspectorLayoutRecord, saved => { setInspectorLayouts(layouts => [...layouts.filter(layout => layout.id !== saved.id), saved]); setInspectorLayoutPreferences(current => ({ ...current, [scopeKey({ surface: "workspace", targetKind: saved.targetKind, protocol: saved.protocol ?? "*" })]: saved.id })); }, () => setInspectorSettingsCell(null));
  const paneEditor = useInspectorLayoutEditor<InspectorPaneLayout>(saveInspectorPaneLayout, saved => setInspectorPaneLayouts(layouts => [...layouts.filter(layout => layout.id !== saved.id), saved]), () => { if (paneRestoreState.current) { setInspectorContext(paneRestoreState.current); paneRestoreState.current = null; } setInspectorSettingsCell(null); });
  const inspectorEditing = workspaceEditor.draft !== null;
  const inspectorDraftActive = useRef(false);
  inspectorDraftActive.current = Boolean(workspaceEditor.draft || paneEditor.draft);
  selectionGuard.current = action => workspaceEditor.requestLeave(action);
  navigationGuard.current = action => workspaceEditor.requestLeave(() => paneEditor.requestLeave(() => leaveStreamTarget(() => { setStreamTarget(null); action(); })));
  paneCloseGuard.current = action => paneEditor.requestLeave(action);
  useEffect(() => { try { localStorage.setItem("stm-inspector-layout-selections", JSON.stringify(inspectorLayoutPreferences)); } catch { /* Browser storage may be unavailable. */ } }, [inspectorLayoutPreferences]);
  const [inspectorAlertOverlayMode, setInspectorAlertOverlayMode] = useState<ChartAlertOverlayMode>(() => {
    try {
      const value = window.localStorage.getItem(INSPECTOR_ALERT_OVERLAY_STORAGE_KEY);
      return value === "off" || value === "diagnostics" ? value : "basic";
    } catch {
      return "basic";
    }
  };
  const contextTargetLabel = contextInspectorTarget?.kind === "interface" ? contextInterface?.name ?? contextInspectorTarget.interfaceKey : contextInspectorTarget?.kind === "flow" ? contextInspectorTarget.flowKey : contextInspectorTarget?.streamKey ?? "No target selected";
  const inspectorContextStyle: CSSProperties | undefined = inspectorContextWidth === null ? undefined : { "--inspector-context-width": inspectorContextWidth + "px" } as CSSProperties;
  const targetSettingsWritable = source.advancing && source.badge === null;
  const targetSettingsSelection = streams.find(stream => stream.streamKey === selectedStreamKey);
  const selectStreamsTarget = (streamKey: string, flowKey: string | null = null, afterSelect?: () => void) => {
    const target = streams.find(stream => stream.streamKey === streamKey);
    const select = () => {
      setSelectedInterfaceKeyRaw(null); setSelectedStreamKeyRaw(streamKey); setSelectedFlowKeyRaw(flowKey);
      if (streamTarget && target && streamTarget.streamKey !== streamKey) setStreamTarget(target);
      afterSelect?.();
    };
    selectionGuard.current(() => {
      if (streamTarget && streamTarget.streamKey !== streamKey) leaveStreamTarget(select);
      else select();
    });
  };
  const selectStreamsInterface = (interfaceKey: string, afterSelect?: () => void) => {
    const select = () => {
      setSelectedInterfaceKeyRaw(interfaceKey); setSelectedStreamKeyRaw(null); setSelectedFlowKeyRaw(null);
      setStreamTarget(null); afterSelect?.();
    };
    selectionGuard.current(() => {
      if (streamTarget) leaveStreamTarget(select);
      else select();
    });
  };
  const renderStreamTargetAction = () => <button type="button" className="dashboard-action-button button-with-icon stream-target-open"
    disabled={!targetSettingsSelection || !targetSettingsWritable || socketState !== "connected"}
    onClick={() => {
      if (streamTarget?.streamKey === targetSettingsSelection?.streamKey) document.querySelector<HTMLElement>(".stream-target-panel")?.focus();
      else leaveStreamTarget(() => setStreamTarget(targetSettingsSelection ?? null));
    }}>
    <Icon name="monitoringSettings" size={15} />{t("streamTarget.title")}
  </button>;
  const renderStreamTargetPanel = () => streamTarget && <StreamTargetSettings key={streamTarget.streamKey} stream={streamTarget} streams={streams}
    writable={targetSettingsWritable} live={targetSettingsWritable && !paused && tabContextTimeSec === null} connected={socketState === "connected"}
    onRequestLeave={leaveStreamTarget}
    onEditingState={(dirty, busy) => { streamTargetGuard.current = { dirty, busy }; }}
    onAlertsSaved={setAlertDocument} onClose={() => { streamTargetGuard.current = { dirty: false, busy: false }; setStreamTarget(null); }}
    onReturnLive={resumeLiveTime}
    onInspect={stream => navigationGuard.current(() => {
      resumeLiveTime(); setQuery(""); selectInspectorStream(stream.streamKey);
      if (standaloneView) activateInvestigationTab("detail");
      else openInspectorContext();
    })} />;
  const renderInspectorContext = () => inspectorContext.open && activeTab !== "detail" ? <div className="inspector-context-frame" onKeyDown={(event) => { if (event.key === "Escape") { event.stopPropagation(); closeInspectorContext(); } }}>
    <PaneSplitter className="inspector-context-splitter" label="Resize Inspector" orientation="vertical" dragging={resizingPane === "width"} onPointerDown={startResizeInspectorContext} onKeyDown={(event) => {
      />
      {dashboardContextTimeSec !== null && eventsLoading && <DashboardCellLoadingOverlay label={t("common.loading")} />}
    </div>;
  };

  const renderInspectorEditingUI = () => <>
    <StreamTargetDiscardDialog open={targetGuard.pending} onDiscard={targetGuard.discard} onCancel={targetGuard.cancel} />
    <InspectorCellSettingsDrawer cell={inspectorSettingsCell?.surface === "workspace" ? workspaceEditor.draft?.cells.find(cell => cell.id === inspectorSettingsCell.id) ?? null : paneEditor.draft?.cells.find(cell => cell.id === inspectorSettingsCell?.id) ?? null} targetKind={inspectorSettingsCell?.surface === "workspace" ? inspectorLayout.targetKind : contextInspectorTargetKind} metrics={inspectorSettingsCell?.surface === "workspace" ? inspectorMetricChoices : paneMetricChoices} catalogError={inspectorCatalogError} disabled={workspaceEditor.status === "saving" || paneEditor.status === "saving"} onChange={cell => inspectorSettingsCell?.surface === "workspace" ? workspaceEditor.updateCell(cell.id, () => cell) : paneEditor.updateCell(cell.id, () => cell)} onClose={() => setInspectorSettingsCell(null)} />
    <InspectorUnsavedDialog open={workspaceEditor.pending} saving={workspaceEditor.status === "saving"} error={workspaceEditor.error} onSave={() => void workspaceEditor.saveAndLeave()} onDiscard={workspaceEditor.discardAndLeave} onContinue={workspaceEditor.continueEditing} />
    <InspectorUnsavedDialog open={paneEditor.pending} saving={paneEditor.status === "saving"} error={paneEditor.error} onSave={() => void paneEditor.saveAndLeave()} onDiscard={paneEditor.discardAndLeave} onContinue={paneEditor.continueEditing} />
  </>;

  if (standaloneView) {
    const detailStreamForStandalone: StreamState | null = (selectedStream?.streamKey === selectedStreamKey ? selectedStream : null) ?? (selectedListItem
      ? {
          ...selectedListItem,
          flows: selectedListItem.flows.map((flow) => ({
            ...flow,
            metrics: {}
          }))
        }
      : null);
    const linkedLayout = resolveInspectorCellLayout(inspectorLayouts, initialParams.get("layout"));
    const linkedProtocolSupported = !linkedLayout?.protocol || linkedLayout.protocol === "*" || Boolean(registeredProtocol(linkedLayout.protocol));
    const linkedCell = linkedProtocolSupported ? linkedLayout?.cells.find((cell) => cell.id === initialParams.get("cell")) : undefined;

    return (
      <TooltipProvider delayMs={appConfig.tooltipDelayMs}>
      <main className="app-shell standalone-shell" aria-busy={loading}>
        <AnalysisSourceBadge badge={source.badge} />
        {loading && (
          <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
            <div className="loading-card">
              <span className="loading-label">{loadingLabel}</span>
              <span className="loading-subtext">{loadingSubtext}</span>
            </div>
          </div>
        )}
        <InvestigationWorkspace timelineActions={timelineDockActions} selectedEventId={selectedEvent?.id} alerts={renderAlertCenterPanel()}>
        {standaloneView === "streams" && (
          <section className="standalone-view standalone-streams">
            {renderStatusHeader()}
            <div className="list-toolbar standalone-toolbar">
              <div className="list-toolbar-header">
                <div>
                  <h2>{t("dashboard.activeStreams")}</h2>
                  <StreamsViewControls viewMode={streamsViewMode} rankTarget={streamsRankTarget} sortOrder={streamsSortOrder}
                    onChangeView={(mode, order) => { setStreamsViewMode(mode); setStreamsSortOrder(order); }} onChangeRankTarget={setStreamsRankTarget}>
                    <button type="button" className="icon-only" onClick={() => setStreamsSortOrder(nextStreamsSortOrder(streamsSortOrder))} aria-label={t("tooltip.sortStreams", { order: streamsSortOrder })} data-tooltip-key="tooltip.sortStreams" data-tooltip-order={streamsSortOrder}><Icon name={streamsSortOrder === "bitrate-asc" ? "sortOldest" : "sortNewest"} size={15} /></button>
                  </StreamsViewControls>
                  <p>{filteredStreams.length} visible / {streams.length} total</p>
                </div>
                <div className="list-toolbar-actions">
                  {renderStreamTargetAction()}
{/*
                  <button type="button" className="list-sort-refresh-button" onClick={() => setStreamSortRefreshToken((value) => value + 1)}>
                    Sort refresh
                  </button>
*/}
                  <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                    <button type="button" className={expandLevel === "interface" ? "active" : ""} onClick={() => setExpandLevel("interface")} aria-pressed={expandLevel === "interface"}>{t("common.nic")}</button>
                    <button type="button" className={expandLevel === "proto" ? "active" : ""} onClick={() => setExpandLevel("proto")} aria-pressed={expandLevel === "proto"}>{t("common.proto")}</button>
                    <button type="button" className={expandLevel === "stream" ? "active" : ""} onClick={() => setExpandLevel("stream")} aria-pressed={expandLevel === "stream"}>{t("common.stream")}</button>
                    <button type="button" className={expandLevel === "flow" ? "active" : ""} onClick={() => setExpandLevel("flow")} aria-pressed={expandLevel === "flow"}>{t("common.flow")}</button>
                  </div>
                </div>
              </div>
              {renderStandaloneSearch("Filter streams")}
            </div>
            <div className={`streams-target-workspace${streamTarget ? " has-target-editor" : ""}`}>
            <StreamTable
              streams={filteredStreams}
              interfaces={interfaces}
              selectedStreamKey={selectedStreamKey}
              viewMode={streamsViewMode}
              rankTarget={streamsRankTarget}
              sortOrder={streamsSortOrder}
              selectedFlowKey={selectedFlowKey}
              selectedInterfaceKey={selectedInterfaceKey}
              overviewMode
              expandLevel={expandLevel}
              onSelectInterface={selectStreamsInterface}
              onSelectStream={selectStreamsTarget}
              onSelectFlow={selectStreamsTarget}
              onInspect={(streamKey, flowKey) => navigationGuard.current(() => { selectStreamsTarget(streamKey, flowKey); activateInvestigationTab("detail"); })}
              onInspectInterface={(interfaceKey) => navigationGuard.current(() => { selectStreamsInterface(interfaceKey); activateInvestigationTab("detail"); })}
              timeTravel={tabContextTimeSec !== null}
              showAlerts={appConfig.streamsAlertDisplay}
              recentAlertRetentionMin={appConfig.streamsRecentAlertRetentionMin}
              referenceTimeSec={tabContextTimeSec ?? latestAvailableTimeSec ?? dataNowSec()}
              dismissedRecent={dismissedRecentAlertKeys}
              onClearRecent={clearGlobalRecentAlerts}
            />
            {renderStreamTargetPanel()}
            </div>
          </section>
        )}
        {standaloneView === "timeline" && (
          <section className="standalone-view standalone-timeline">
            {renderStatusHeader()}
            <div className="timeline-header standalone-toolbar">
              <h3>{t("nav.timeline")}</h3>
<div className="list-toolbar-actions">
              {renderStandaloneSearch("Filter timeline")}
              <HeaderSelect label={t("common.range")} className="header-time-range" value={timelineRange} onChange={(event) => changeTimelineRange(event.target.value)}>
                {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
              </HeaderSelect>
            emphasizeLatest={emphasizeLatest}
            onToggleView={toggleView}
            onToggleTheme={toggleTheme}
            theme={theme}
            alertCenter={renderAlertCenter()}
            onOpenPreferences={() => setActiveTab("preferences")}
            onOpenMaintenance={() => setActiveTab("maintenance")}
            runtime={socketState === "connected" ? runtimeStatus.runtime : null}
            runtimeError={socketState === "connected" ? runtimeStatus.error : "Frontend server disconnected"}
            onOpenServiceOperation={() => setActiveTab("service-operation")}
          />

          <InvestigationWorkspace timelineActions={timelineDockActions} selectedEventId={selectedEvent?.id} alerts={renderAlertCenterPanel()}>
          {activeTab === "dashboard" ? renderDashboardView() : (
            <section className={`main-tab-view main-tab-${activeTab}${inspectorContext.open && activeTab !== "detail" ? " has-inspector-context" : ""}`} style={inspectorContext.open ? inspectorContextStyle : undefined}>
              {activeTab === "streams" && (
                <PaneFrame
                  className="streams-tab-frame"
                  header={<PaneHeader
                    title={t("nav.streams")}
                    icon="streams"
                    meta="Active stream list"
                    actions={<div className="header-action-row stream-tab-actions">
                      {renderStreamTargetAction()}
                      <SearchInput className="pane-search" value={query} onChange={setQuery} placeholder="Filter streams" label="stream search" />
                      <div className="expand-level-controls" role="tablist" aria-label="Tree expand level">
                        <button type="button" className={"icon-only " + (expandLevel === "interface" ? "active" : "")} onClick={() => setExpandLevel("interface")} aria-label="Expand to NIC" data-tooltip-key="tooltip.expandNic"><Icon name="topology" size={15} /></button>
                        <button type="button" className={"icon-only " + (expandLevel === "proto" ? "active" : "")} onClick={() => setExpandLevel("proto")} aria-label="Expand to protocol" data-tooltip-key="tooltip.expandProtocol"><Icon name="protocolMap" size={15} /></button>
                        <button type="button" className={"icon-only " + (expandLevel === "stream" ? "active" : "")} onClick={() => setExpandLevel("stream")} aria-label="Expand to stream" data-tooltip-key="tooltip.expandStream"><Icon name="layoutList" size={15} /></button>
                        <button type="button" className={"icon-only " + (expandLevel === "flow" ? "active" : "")} onClick={() => setExpandLevel("flow")} aria-label="Expand to flow" data-tooltip-key="tooltip.expandFlow"><Icon name="list" size={15} /></button>
                      </div>
                      <StreamsViewControls viewMode={streamsViewMode} rankTarget={streamsRankTarget} sortOrder={streamsSortOrder}
                        onChangeView={(mode, order) => { setStreamsViewMode(mode); setStreamsSortOrder(order); }} onChangeRankTarget={setStreamsRankTarget}>
                        <button type="button" className="icon-only" onClick={() => setStreamsSortOrder(nextStreamsSortOrder(streamsSortOrder))} aria-label={t("tooltip.sortStreams", { order: streamsSortOrder })} data-tooltip-key="tooltip.sortStreams" data-tooltip-order={streamsSortOrder}><Icon name={streamsSortOrder === "bitrate-asc" ? "sortOldest" : "sortNewest"} size={15} /></button>
                      </StreamsViewControls>
                    </div>}
                  />}
                >
                  <div className={`streams-target-workspace${streamTarget ? " has-target-editor" : ""}`}>
                  <StreamTable
                    streams={filteredStreams}
                    interfaces={interfaces}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceKey={selectedInterfaceKey}
                    overviewMode
                    expandLevel={expandLevel}
                    viewMode={streamsViewMode}
                    rankTarget={streamsRankTarget}
                    sortOrder={streamsSortOrder}
                    onSelectInterface={selectStreamsInterface}
                    onSelectStream={selectStreamsTarget}
                    onSelectFlow={selectStreamsTarget}
                    onInspect={(streamKey, flowKey) => selectStreamsTarget(streamKey, flowKey, openInspectorContext)}
                    onInspectInterface={(interfaceKey) => selectStreamsInterface(interfaceKey, openInspectorContext)}
                    timeTravel={tabContextTimeSec !== null}
              showAlerts={appConfig.streamsAlertDisplay}
              recentAlertRetentionMin={appConfig.streamsRecentAlertRetentionMin}
              referenceTimeSec={tabContextTimeSec ?? latestAvailableTimeSec ?? dataNowSec()}
              dismissedRecent={dismissedRecentAlertKeys}
              onClearRecent={clearGlobalRecentAlerts}
                  />
                  {renderStreamTargetPanel()}
                  </div>
                </PaneFrame>
              )}
              {activeTab === "detail" && renderInspectorView()}
              {activeTab === "timeline" && (
                <PaneFrame
                  className="timeline-tab-frame"
                  header={<PaneHeader
                    title={t("nav.timeline")}
                    icon="timeline"
    finally { request.current = false; setBusy(false); }
  }

  const status = !live ? "returnLive" : !connected || runtimeError || !runtime?.control.available || !stm ? "statusUnavailable"
    : restarting ? "restarting" : stm.activation.state === "restart_failed" ? "restartFailed"
    : stm.activation.state === "restart_required" ? "pending" : stm.state !== "RUNNING" || stm.ready === false ? "serviceNotRunning"
    : saved?.rule.enabled === false || saved?.rule.observe === false ? "disabled"
    : confirmed ? "confirmed" : "waiting";
  return <aside ref={panel} tabIndex={-1} className="stream-target-panel" aria-busy={busy} aria-label={t("streamTarget.title")} onKeyDown={event => {
    if (event.key === "Escape") { event.stopPropagation(); leave(onClose); }
  }}>
    <PaneHeader className="stream-target-header" title={t("streamTarget.title")} icon="monitoringSettings" actions={<IconActionButton icon="close" label={t("streamTarget.close")} disabled={busy} onClick={() => leave(onClose)} />} />
    <div className="stream-target-content">
      <div className="stream-target-summary">
        <p>{t("streamTarget.selected")}: <strong>{stream.displayName ?? stream.label}</strong></p>
        <p className="stream-target-subject">{bundle ? candidateSubject(bundle) : stream.streamKey}</p>
        <p>{t("streamTarget.detected")}: {stream.proto} · {stream.interfaceName ?? "—"}</p>
        <p className="protocol-map-notice">{t("streamTarget.sessionHint")}</p>
      </div>
      {!writable && <p role="status">{t("streamTarget.readOnly")}</p>}
      {!connected && <p role="status">{t("streamTarget.disconnected")}</p>}
      {message && <p role="alert" className="service-operation-error">{message}</p>}
      {busy && <p role="status">{t("streamTarget.working")}</p>}
      {!state && !busy && <button type="button" className="maintenance-secondary-button" onClick={() => setLoadVersion(value => value + 1)}>{t("streamTarget.reload")}</button>}
      {state && <>
        <div className="stream-target-actions"><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => leave(() => setLoadVersion(value => value + 1))}>{t("streamTarget.reload")}</button></div>
        {matches.length > 1 && <label className="stream-target-field">{t("streamTarget.chooseTarget")}<select value={original?.id ?? ""} disabled={locked} onChange={event => {
          const next = matches.find(item => item.id === event.target.value);
          if (next) leave(() => { selectRule(next); setAlerts(state.alerts.document); setDirty(false); });
        }}><option value="" disabled>{t("streamTarget.chooseTarget")}</option>{matches.map(item => <option key={item.id} value={item.id}>{item.stream_name ?? item.id}</option>)}</select></label>}
        {!matches.length && !bundle && <p>{t("streamTarget.unsupported")}</p>}
        {(rule || (!matches.length && bundle)) && <form className="stream-target-form" onSubmit={event => { event.preventDefault(); void review(); }}>
          <p><strong>{t(original ? "streamTarget.edit" : "streamTarget.add")}</strong>{rule?.id && <small className="stream-target-id">{rule.id}</small>}</p>
          <fieldset className="stream-target-fields" disabled={locked || Boolean(saved)}>
            <label className="stream-target-field">{t("streamTarget.protocol")}<select required value={protocol} disabled={customDecode || choices.length === 1 && Boolean(original)} onChange={event => chooseProtocol(event.target.value as TargetProtocolChoice)}><option value="" disabled>{t("streamTarget.chooseProtocol")}</option>{choices.map(value => <option key={value} value={value}>{value}</option>)}</select></label>
            {rule && <>
              <label className="stream-target-field">{t("streamTarget.name")}<input maxLength={128} value={rule.stream_name ?? ""} onChange={event => change({ stream_name: event.target.value || undefined })} /></label>
              {!original && !defaultTargetEndpoint(bundle!) && <label className="stream-target-field">{t("streamTarget.stableEndpoint")}<select required value={ruleList(rule.endpoints)[0] ?? ""} onChange={event => change({ endpoints: [event.target.value] })}><option value="" disabled>{t("streamTarget.chooseEndpoint")}</option>{selectorEndpointOptions(stream).map(endpoint => <option key={endpoint}>{endpoint}</option>)}</select></label>}
              {(original || defaultTargetEndpoint(bundle!)) && <label className="stream-target-field">{t(rule.hosts || rule.domains ? "streamTarget.hosts" : "streamTarget.endpoints")}<textarea required disabled={customDecode} value={ruleList(rule.hosts ?? rule.domains ?? rule.endpoints).join("\n")} onChange={event => {
                const values = event.target.value.split("\n"); change(rule.hosts ? { hosts: values } : rule.domains ? { domains: values } : { endpoints: values });
              }} /></label>}
              {customDecode && <p className="protocol-map-notice">{t("streamTarget.customDecode")}</p>}
              {protocol === "RTP-FEC" && <p className="protocol-map-notice">{t("streamTarget.fecHint")}</p>}
              <label className="stream-target-field">{t("streamTarget.interfaces")}<input value={ruleList(rule.interfaces).join(", ")} onChange={event => change({ interfaces: event.target.value.trim() ? event.target.value.split(",").map(value => value.trim()) : undefined })} /></label>
              <label className="stream-target-field">{t("streamTarget.vlan")}<select value={rule.vlan === undefined ? "any" : rule.vlan === null ? "untagged" : "id"} onChange={event => change({ vlan: event.target.value === "any" ? undefined : event.target.value === "untagged" ? null : 0 })}><option value="any">{t("streamTarget.any")}</option><option value="untagged">{t("streamTarget.untagged")}</option><option value="id">VLAN ID</option></select></label>
              {rule.vlan !== undefined && rule.vlan !== null && <label className="stream-target-field">VLAN ID<input type="number" required min={0} max={4094} value={rule.vlan} onChange={event => change({ vlan: event.target.value })} /></label>}
              <label className="stream-target-check"><input type="checkbox" checked={rule.enabled !== false} onChange={event => change({ enabled: event.target.checked })} />{t("streamTarget.enabled")}</label>
              <label className="stream-target-check"><input type="checkbox" checked={rule.observe !== false} onChange={event => change({ observe: event.target.checked })} />{t("streamTarget.observe")}</label>
              {alerts && <TargetAlertPolicyPanel target={{ id: rule.id!, proto: rule.proto, target_type: rule.target_type ?? "single", title: rule.stream_name, ...(rule.fec ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }} document={alerts} metrics={state.alerts.metrics} protocols={state.alerts.protocols} flowRoles={state.alerts.flowRoles} busy={locked} onDocument={next => { setAlerts(next); setDirty(true); setPreview(null); }} />}
            </>}
          </fieldset>
          {!saved && <div className="stream-target-actions"><button type="submit" className="maintenance-save-button" disabled={locked || !rule || !protocol}>{t("streamTarget.review")}</button></div>}
        </form>}
        {preview && <section className="stream-target-review" aria-label={t("streamTarget.review")}>
          <h3>{t("streamTarget.review")}</h3>
          <p>{t("streamTarget.reviewHint")}</p>
          <ul>{preview.result.changes.filter(item => item.action === "update").map(item => <li key={item.area}>{item.area} · {item.restart ? t("streamTarget.restartRequired", { name: item.restart }) : "—"}</li>)}</ul>
          {preview.result.warnings.map(warning => <p key={warning}>{warning}</p>)}
          <div className="stream-target-actions"><button type="button" className="maintenance-save-button" disabled={locked} onClick={() => void save()}>{t("streamTarget.save")}</button></div>
        </section>}
        {saved && <section className="stream-target-verification" aria-live="polite">
          <h3>{t("streamTarget.saved")}</h3><p>{t("streamTarget." + status)}</p>
          {stm?.activation.error && <p role="alert">{stm.activation.error}</p>}
          {confirmed && <p>{confirmed.proto} · {formatBitrate(confirmed.bitrate.value)}</p>}
          <div className="stream-target-actions">
            {!live && writable && <button type="button" className="maintenance-secondary-button" onClick={onReturnLive}>{t("streamTarget.live")}</button>}
            <button type="button" className="maintenance-secondary-button" disabled={!connected || busy} onClick={() => void refresh()}>{t("streamTarget.refresh")}</button>
            {pending.length > 0 && <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting} onClick={() => setConfirmRestart(true)}>{t("streamTarget.restart")}</button>}
            {confirmed && <button type="button" className="maintenance-save-button" onClick={() => onInspect(confirmed)}>{t("streamTarget.inspect")}</button>}
            <button type="button" className="maintenance-secondary-button" disabled={busy || restarting} onClick={() => { setSaved(null); setMessage(""); }}>{t("streamTarget.continueEditing")}</button>
          </div>
        </section>}
        {confirmRestart && <section role="alertdialog" aria-label={t("streamTarget.restart")}>
          <p>{t("streamTarget.restartHint")}</p><ul>{pending.map(process => <li key={process.name}>{process.name}</li>)}</ul>
          <div className="stream-target-actions">
            <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => setConfirmRestart(false)}>{t("streamTarget.cancel")}</button>
            <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting || !pending.length} onClick={() => void restart()}>{t("streamTarget.restart")}</button>
          </div>
        </section>}
      </>}
    </div>
  </aside>;
}
}
