export function useStreamTargetGuard() {
  const status = useRef({ dirty: false, busy: false });
  const [pending, setPending] = useState<(() => void) | null>(null);
  const requestLeave = useCallback((action: () => void) => {
    if (status.current.busy) return;
    if (status.current.dirty) { setPending(() => action); return; }
    action();
  }, []);
  const discard = () => {
    const action = pending;
    setPending(null);
    status.current = { dirty: false, busy: false };
    action?.();
  };
  return { status, pending: pending !== null, requestLeave, discard, cancel: () => setPending(null) };
}
