import { createContext, useCallback, useContext, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type MutableRefObject, type ReactNode } from "react";
import { Icon } from "./ui/Icon";
import { getAnalysisSource, type AnalysisSource } from "../analysisSource";
import type { EventMarkerBucket } from "../timelineMarkers";
import type { EventLogItem } from "../types/api";
import type { TimelineAnchorName } from "../timelineCursor";
import { TimelineEventBucketPopover } from "./TimelineEventBucketPanel";
import { SearchInput } from "./ui/SearchInput";
import { PaneSplitter } from "./ui/PaneSplitter";
import { useI18n } from "../i18n";
import { readInvestigationDockHeight, rememberInvestigationDockHeight } from "../investigationPreferences";

export type TimelineDockBridge = {
  select: (event: EventLogItem) => void;
  reveal: (event: EventLogItem) => void;
  canReveal: (event: EventLogItem) => boolean;
  setAnchor: (name: TimelineAnchorName, event: EventLogItem) => void;
  refresh: (bucket: EventMarkerBucket) => EventMarkerBucket | undefined;
};
export type TimelineDockActions = {
  select: (event: EventLogItem, origin: string) => void;
  reveal: (event: EventLogItem, origin: string) => void;
  setAnchor: (name: TimelineAnchorName, event: EventLogItem, origin: string) => void;
  openEvents: (event: EventLogItem) => void;
  refreshMarkers: () => void;
};
type EventSelection = { origin: string; bucket: EventMarkerBucket; source: AnalysisSource; epoch?: number; revision: number };

export type InvestigationDockTab = "events" | "alerts" | "settings";
type QueryTab = "events" | "alerts";
type CloseGuard = (close: () => void) => void;
type DockContext = {
  activeTab: InvestigationDockTab | null;
  open: (tab: InvestigationDockTab) => void;
  close: () => void;
  registerCloseGuard: (guard: CloseGuard) => () => void;
  queries: Record<QueryTab, string>;
  changeQuery: (tab: QueryTab, query: string) => void;
  eventSelection: EventSelection | null;
  preview: EventLogItem | undefined;
  previewEvent: (event?: EventLogItem) => void;
  openTimelineEvents: (origin: string, bucket: EventMarkerBucket) => void;
  clearEvents: () => void;
  refreshEvents: () => void;
  registerTimeline: (origin: string, bridge: MutableRefObject<TimelineDockBridge>) => () => void;
  findTimeline: (origin: string) => TimelineDockBridge | undefined;
};
const InvestigationDockContext = createContext<DockContext | null>(null);

export function InvestigationDockProvider({ children }: { children: ReactNode }) {
  const [activeTab, setActiveTab] = useState<InvestigationDockTab | null>(null);
  const [queries, setQueries] = useState({ events: "", alerts: "" });
  const changeQuery = useCallback((tab: QueryTab, query: string) => setQueries(current => ({ ...current, [tab]: query })), []);
  const [eventSelection, setEventSelection] = useState<EventSelection | null>(null);
  const [preview, setPreview] = useState<EventLogItem>();
  const nextRevision = useRef(0);
  const bridges = useRef(new Map<string, MutableRefObject<TimelineDockBridge>>());
  const findTimeline = useCallback((origin: string) => bridges.current.get(origin)?.current, []);
  const registerTimeline = useCallback((origin: string, bridge: MutableRefObject<TimelineDockBridge>) => {
    bridges.current.set(origin, bridge);
    return () => { if (bridges.current.get(origin) === bridge) bridges.current.delete(origin); };
  }, []);
  const closeGuard = useRef<CloseGuard | null>(null);
  const registerCloseGuard = useCallback((guard: CloseGuard) => {
    closeGuard.current = guard;
    return () => { if (closeGuard.current === guard) closeGuard.current = null; };
  }, []);
  const opener = useRef<HTMLElement | null>(null);
  const open = useCallback((tab: InvestigationDockTab) => {
    if (document.activeElement instanceof HTMLElement && document.activeElement !== document.body && !document.activeElement.closest(".investigation-dock")) opener.current = document.activeElement;
    setActiveTab(tab);
    setPreview(undefined);
  }, []);
  const close = useCallback(() => {
    const finish = () => {
      setActiveTab(null);
      setQueries({ events: "", alerts: "" });
      setEventSelection(null);
      setPreview(undefined);
      const target = opener.current?.isConnected && opener.current.getClientRects().length ? opener.current : document.querySelector<HTMLElement>(".investigation-workspace-main");
      target?.focus({ preventScroll: true });
    };
    if (closeGuard.current) closeGuard.current(finish);
    else finish();
  }, []);
  const clearEvents = useCallback(() => { setEventSelection(null); setPreview(undefined); setQueries(current => ({ ...current, events: "" })); }, []);
  const openTimelineEvents = useCallback((origin: string, bucket: EventMarkerBucket) => {
    const source = getAnalysisSource();
    setQueries(current => ({ ...current, events: "" }));
    setEventSelection({ origin, bucket: { ...bucket, events: [...bucket.events], summaries: bucket.summaries ? [...bucket.summaries] : undefined }, source, epoch: source.epoch, revision: ++nextRevision.current });
    open("events");
  }, [open]);
  const refreshEvents = useCallback(() => {
    setPreview(undefined);
    const revision = ++nextRevision.current;
    setEventSelection(current => current ? { ...current, bucket: bridges.current.get(current.origin)?.current.refresh(current.bucket) ?? current.bucket, revision } : null);
  }, []);
  const value = useMemo(() => ({ activeTab, open, close, registerCloseGuard, queries, changeQuery, eventSelection, preview, previewEvent: setPreview, openTimelineEvents, clearEvents, refreshEvents, registerTimeline, findTimeline }),
    [activeTab, open, close, registerCloseGuard, queries, changeQuery, eventSelection, preview, openTimelineEvents, clearEvents, refreshEvents, registerTimeline, findTimeline]);
  return <InvestigationDockContext.Provider value={value}>{children}</InvestigationDockContext.Provider>;
}

export function useInvestigationDock() { return useContext(InvestigationDockContext); }

/** The dock is a layout row, never an overlay on either the main pane or Inspector. */
export function InvestigationWorkspace({ children, events, alerts, settings, settingsDirty = false, timelineActions, selectedEventId }: { children: ReactNode; events?: ReactNode; alerts?: ReactNode; settings?: ReactNode; settingsDirty?: boolean; timelineActions?: TimelineDockActions; selectedEventId?: string | null }) {
  const dock = useInvestigationDock();
  const { t } = useI18n();
  const source = getAnalysisSource(), sourceEpoch = source.epoch;
  useLayoutEffect(() => {
    const selection = dock?.eventSelection;
    if (selection && (selection.source !== source || selection.epoch !== sourceEpoch)) dock.clearEvents();
  }, [source, sourceEpoch, dock?.eventSelection, dock?.clearEvents]);
  const host = useRef<HTMLDivElement>(null);
  const [availableHeight, setAvailableHeight] = useState(600);
  const [preferredHeight, setPreferredHeight] = useState(readInvestigationDockHeight);
  const [resizing, setResizing] = useState(false);
  const drag = useRef<{ id: number; y: number; height: number; lastHeight: number } | null>(null);
  const finishDrag = useCallback(() => {
    if (drag.current) rememberInvestigationDockHeight(drag.current.lastHeight);
    drag.current = null;
    setResizing(false);
  }, []);
  useLayoutEffect(() => {
    if (!host.current) return;
    const measure = () => setAvailableHeight(host.current?.clientHeight ?? 600);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(host.current);
    return () => observer.disconnect();
  }, []);
  const minimum = Math.min(180, availableHeight * 0.35);
  const maximum = Math.max(minimum, Math.min(availableHeight * 0.6, availableHeight - 280));
  const limits = useRef({ minimum, maximum });
  limits.current = { minimum, maximum };
  useLayoutEffect(() => {
    const move = (event: PointerEvent) => {
      if (drag.current?.id !== event.pointerId) return;
      const { minimum, maximum } = limits.current;
      const height = Math.min(maximum, Math.max(minimum, drag.current.height + drag.current.y - event.clientY));
      drag.current.lastHeight = height;
      setPreferredHeight(height);
    };
    const finish = (event: PointerEvent) => { if (drag.current?.id === event.pointerId) finishDrag(); };
    const cancel = finishDrag;
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", finish);
