    embedded active={dock.activeTab === "events"} selectedEventId={selectedEventId} onClose={dock.close}
    onPreviewEvent={(_id, event) => dock.previewEvent(event)}
    onSelectEvent={event => { const target = bridge(); if (target) target.select(event); else actions?.select(event, origin); }}
    canRevealEvent={event => bridge()?.canReveal(event) ?? (!!event.streamKey && !!actions)}
