export function useInvestigationDock() { return useContext(InvestigationDockContext); }

/** The dock is a layout row, never an overlay on either the main pane or Inspector. */
export function InvestigationWorkspace({ children, events, alerts, settings, settingsTarget, settingsDirty = false, timelineActions, selectedEventId }: { children: ReactNode; events?: ReactNode; alerts?: ReactNode; settings?: ReactNode; settingsTarget?: string; settingsDirty?: boolean; timelineActions?: TimelineDockActions; selectedEventId?: string | null }) {
  const dock = useInvestigationDock();
  const { t } = useI18n();
  const source = getAnalysisSource(), sourceEpoch = source.epoch;
  useLayoutEffect(() => {
    const selection = dock?.eventSelection;
    if (selection && (selection.source !== source || selection.epoch !== sourceEpoch)) dock.clearEvents();
  }, [source, sourceEpoch, dock?.eventSelection, dock?.clearEvents]);
  const settingsHeading = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    if (dock?.activeTab === "settings") settingsHeading.current?.focus({ preventScroll: true });
  }, [dock?.activeTab]);
  const host = useRef<HTMLDivElement>(null);
  const [availableHeight, setAvailableHeight] = useState(600);
  const [preferredHeight, setPreferredHeight] = useState(readInvestigationDockHeight);
  const [resizing, setResizing] = useState(false);
  const drag = useRef<{ id: number; y: number; height: number; lastHeight: number } | null>(null);
          setPreferredHeight(next); rememberInvestigationDockHeight(next);
        }} />
    <section className="investigation-dock" aria-label="Investigation dock" onKeyDown={event => {
      if (event.key === "Escape" && !event.defaultPrevented) { event.preventDefault(); event.stopPropagation(); finishDrag(); dock.close(); }
    }}>
      <header className="pane-header investigation-dock-header">
        {dock.activeTab === "settings" ? <div ref={settingsHeading} className="investigation-settings-heading" tabIndex={-1}>
          <Icon name="monitoringSettings" size={16} />
          <strong>{t("streamTarget.title")}</strong>
          {settingsTarget && <span className="investigation-settings-target" title={settingsTarget}>{settingsTarget}</span>}
          {settingsDirty && <span className="investigation-settings-unsaved" aria-label={t("streamTarget.unsavedTitle")}>{t("streamTarget.unsaved")}</span>}
        </div> : <>
        <div role="tablist" aria-label="Investigation panels">
          {tabs.map(tab => <button key={tab} id={`investigation-tab-${tab}`} type="button" role="tab"
            tabIndex={dock.activeTab === tab ? 0 : -1} aria-selected={dock.activeTab === tab} aria-controls={`investigation-panel-${tab}`}
            onKeyDown={event => {
              if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
              event.preventDefault(); event.stopPropagation();
              const next = tabs[event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : (tabs.indexOf(tab) + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length];
              dock.open(next); document.getElementById(`investigation-tab-${next}`)?.focus({ preventScroll: true });
            }} onClick={() => dock.open(tab)}>{tab === "events" ? "Event details" : "Alert center"}</button>)}
        </div>
        <div className="pane-header-actions">
          <SearchInput className="pane-search investigation-search" value={dock.queries[queryTab]}
            onChange={query => dock.changeQuery(queryTab, query)} maxLength={256}
            label={t(dock.activeTab === "events" ? "dock.searchEvents" : "dock.searchAlerts")}
            placeholder={t(dock.activeTab === "events" ? "dock.searchEventsHint" : "dock.searchAlertsHint")} />
        </div>
        {settings !== undefined && settingsTarget !== undefined && <button type="button" className="investigation-settings-resume button-with-icon"
          aria-label={`${t("streamTarget.resume")}: ${settingsTarget}`} title={`${t("streamTarget.resume")}: ${settingsTarget}`} onClick={() => dock.open("settings")}>
          <Icon name="monitoringSettings" size={16} /><span className="investigation-settings-resume-label">{t("streamTarget.resume")}</span>
          {settingsDirty && <span className="investigation-settings-dirty" aria-label={t("streamTarget.unsavedTitle")}>●</span>}
        </button>}
        </>}
        <button type="button" className="investigation-dock-close" aria-label="Close investigation dock" onClick={dock.close}><Icon name="close" size={16} /></button>
      </header>
