  const rtp={...raw,proto:'RTP',streamKey:'new-rtp',flows:[{...raw.flows[0],monitoringTargetIds:['camera']}]};
  assert.equal(confirmedTargetStream([rtp],rule,100,runtime),rtp,'stream key can change after decoding');
  for(const traffic of [raw,{...rtp,active:false},{...rtp,flows:[{...rtp.flows[0],active:false}]},{...rtp,flows:[{...rtp.flows[0],lastSeen:100}]},{...rtp,flows:[{...rtp.flows[0],monitoringTargetIds:['other']}]}]){
