    assert.equal(confirmedTargetStream([rtp],rule,100,{...runtime,processes:[{...runtime.processes[0],activation:{state}}]}),undefined);
  }
  assert.equal(confirmedTargetStream([rtp],rule,100,{...runtime,processes:[{...runtime.processes[0],startedAt:102000}]}),undefined,'pre-restart traffic is not confirmation');
  assert.equal(confirmedTargetStream([rtp],rule,100,{...runtime,processes:[{...runtime.processes[0],state:'STOPPED'}]}),undefined);
  assert.equal(confirmedTargetStream([rtp],rule,100,{...runtime,control:{available:false}}),undefined);
