type Props = {
  docked?: boolean;
  stream: StreamListItem;
  streams: StreamListItem[];
  writable: boolean;
  live: boolean;
  connected: boolean;
  onAlertsSaved: (document: AlertsDocument) => void;
  onInspect: (stream: StreamListItem) => void;
  onReturnLive: () => void;
  onClose: () => void;
  onEditingState: (dirty: boolean, busy: boolean) => void;
  onRequestLeave: (action: () => void) => void;
};

export function StreamTargetSettings({ docked = false, stream, streams, writable, live, connected, onAlertsSaved, onInspect, onReturnLive, onClose, onEditingState, onRequestLeave }: Props) {
  const { t } = useI18n();
  const { runtime, error: runtimeError, replaceRuntime, refresh, restartPending, operation } = useRuntimeStatus();
  const [state, setState] = useState<SetupState | null>(null);
  const [rule, setRule] = useState<ProtocolRule | null>(null);
  const [protocol, setProtocol] = useState<TargetProtocolChoice | "">("");
  const [alerts, setAlerts] = useState<AlertsDocument | null>(null);
  const [preview, setPreview] = useState<{ draft: SetupDraft; result: SetupPreview } | null>(null);
  const [saved, setSaved] = useState<{ rule: ProtocolRule; after: number } | null>(null);
  const [busy, setBusy] = useState(true);
  const [message, setMessage] = useState("");
  const [dirty, setDirty] = useState(false);
  const [confirmRestart, setConfirmRestart] = useState(false);
  const [loadVersion, setLoadVersion] = useState(0);
  const panel = useRef<HTMLElement>(null);
  const request = useRef(false);
  const bundle = buildCandidateBundles([stream], { [stream.streamKey]: protocol === "HLS" ? "" : protocol })[0];
  const matches = state ? targetRulesForStream(stream, state.protocolMap.document.protocols) : [];
  const original = rule?.id ? state?.protocolMap.document.protocols.find(item => item.id === rule.id) : undefined;
  const restarting = operation?.state === "running" || runtime?.processes.some(process => process.activation.state === "restarting");
  const locked = busy || restarting || !writable || !connected;
  const customDecode = ruleList(rule?.decode_as).length > 0;
  const candidates = candidateProtocolChoices(bundle?.source ?? "detected");
  const detectedChoices: TargetProtocolChoice[] = bundle?.protocol === "RTP" || bundle?.protocol === "RTP-FEC" ? ["RTP", "RTP-FEC"] : bundle?.protocol ? [bundle.protocol] : [];
  const choices = [...new Set([...(original ? [original.proto === "RTP" && original.fec ? "RTP-FEC" as const : original.proto] : []), ...(bundle?.source === "detected" ? detectedChoices : candidates)])];
  const confirmed = saved && live && connected && !runtimeError ? confirmedTargetStream(streams, saved.rule, saved.after, runtime) : undefined;
  const pending = restartableProcesses(runtime);
  const stm = runtime?.processes.find(process => process.name === "stm");

  useEffect(() => { onEditingState(dirty, busy); }, [dirty, busy, onEditingState]);

  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    panel.current?.focus();
    return () => { if (opener?.isConnected) opener.focus(); };
  }, []);

  useEffect(() => {
    let active = true;
    setBusy(true); setMessage("");
    void getSetupState().then(next => {
      if (!active) return;
      setState(next); replaceRuntime(next.runtime); setAlerts(next.alerts.document);
      const existing = targetRulesForStream(stream, next.protocolMap.document.protocols);
      if (existing.length === 1) selectRule(existing[0]);
      else { setRule(null); setProtocol(""); }
      setDirty(false); setPreview(null); setSaved(null);
    }).catch((error: unknown) => { if (active) setMessage(error instanceof Error ? error.message : t("streamTarget.loadFailed")); })
      .finally(() => { if (active) setBusy(false); });
    return () => { active = false; };
  }, [loadVersion]);

  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);

  function selectRule(next: ProtocolRule) {
    setRule(next); setProtocol(next.proto === "RTP" && next.fec ? "RTP-FEC" : next.proto);
    setPreview(null); setMessage(""); setSaved(null);
  }
  function change(patch: Partial<ProtocolRule>) {
    setRule(current => current ? { ...current, ...patch } : current);
    setDirty(true); setPreview(null); setSaved(null); setMessage("");
  }
  function chooseProtocol(value: TargetProtocolChoice | "") {
