          <fieldset className="stream-target-fields" disabled={locked || Boolean(saved)}>
            <label className="stream-target-field">{t("streamTarget.protocol")}<select required value={protocol} disabled={customDecode || choices.length === 1 && Boolean(original)} onChange={event => chooseProtocol(event.target.value as TargetProtocolChoice)}><option value="" disabled>{t("streamTarget.chooseProtocol")}</option>{choices.map(value => <option key={value} value={value}>{value}</option>)}</select></label>
            {rule && <>
              <label className="stream-target-field">{t("streamTarget.name")}<input maxLength={128} value={rule.stream_name ?? ""} onChange={event => change({ stream_name: event.target.value || undefined })} /></label>
              {!original && !defaultTargetEndpoint(bundle!) && <label className="stream-target-field">{t("streamTarget.stableEndpoint")}<select required value={ruleList(rule.endpoints)[0] ?? ""} onChange={event => change({ endpoints: [event.target.value] })}><option value="" disabled>{t("streamTarget.chooseEndpoint")}</option>{selectorEndpointOptions(stream).map(endpoint => <option key={endpoint}>{endpoint}</option>)}</select></label>}
              {(original || defaultTargetEndpoint(bundle!)) && <label className="stream-target-field">{t(rule.hosts || rule.domains ? "streamTarget.hosts" : "streamTarget.endpoints")}<textarea required disabled={customDecode} value={ruleList(rule.hosts ?? rule.domains ?? rule.endpoints).join("\n")} onChange={event => {
                const values = event.target.value.split("\n"); change(rule.hosts ? { hosts: values } : rule.domains ? { domains: values } : { endpoints: values });
              }} /></label>}
              {customDecode && <p className="protocol-map-notice">{t("streamTarget.customDecode")}</p>}
              {protocol === "RTP-FEC" && <p className="protocol-map-notice">{t("streamTarget.fecHint")}</p>}
              <label className="stream-target-field">{t("streamTarget.interfaces")}<input value={ruleList(rule.interfaces).join(", ")} onChange={event => change({ interfaces: event.target.value.trim() ? event.target.value.split(",").map(value => value.trim()) : undefined })} /></label>
              <label className="stream-target-field">{t("streamTarget.vlan")}<select value={rule.vlan === undefined ? "any" : rule.vlan === null ? "untagged" : "id"} onChange={event => change({ vlan: event.target.value === "any" ? undefined : event.target.value === "untagged" ? null : 0 })}><option value="any">{t("streamTarget.any")}</option><option value="untagged">{t("streamTarget.untagged")}</option><option value="id">VLAN ID</option></select></label>
              {rule.vlan !== undefined && rule.vlan !== null && <label className="stream-target-field">VLAN ID<input type="number" required min={0} max={4094} value={rule.vlan} onChange={event => change({ vlan: event.target.value })} /></label>}
              <div className="stream-target-checks">
                <label className="stream-target-check"><input type="checkbox" checked={rule.enabled !== false} onChange={event => change({ enabled: event.target.checked })} />{t("streamTarget.enabled")}</label>
                <label className="stream-target-check"><input type="checkbox" checked={rule.observe !== false} onChange={event => change({ observe: event.target.checked })} />{t("streamTarget.observe")}</label>
              </div>
              {alerts && <TargetAlertPolicyPanel target={{ id: rule.id!, proto: rule.proto, target_type: rule.target_type ?? "single", title: rule.stream_name, ...(rule.fec ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }} document={alerts} metrics={state.alerts.metrics} protocols={state.alerts.protocols} flowRoles={state.alerts.flowRoles} busy={locked} onDocument={next => { setAlerts(next); setDirty(true); setPreview(null); }} />}
            </>}
          </fieldset>
          {!saved && <div className="stream-target-actions"><button type="submit" className="maintenance-save-button" disabled={locked || !rule || !protocol}>{t("streamTarget.review")}</button></div>}
        </form>}
        {preview && <section className="stream-target-review" aria-label={t("streamTarget.review")}>
          <h3>{t("streamTarget.review")}</h3>
          <p>{t("streamTarget.reviewHint")}</p>
          <ul>{preview.result.changes.filter(item => item.action === "update").map(item => <li key={item.area}>{item.area} · {item.restart ? t("streamTarget.restartRequired", { name: item.restart }) : "—"}</li>)}</ul>
          {preview.result.warnings.map(warning => <p key={warning}>{warning}</p>)}
          <div className="stream-target-actions"><button type="button" className="maintenance-save-button" disabled={locked} onClick={() => void save()}>{t("streamTarget.save")}</button></div>
        </section>}
        {saved && <section className="stream-target-verification" aria-live="polite">
          <h3>{t("streamTarget.saved")}</h3><p>{t("streamTarget." + status)}</p>
          {stm?.activation.error && <p role="alert">{stm.activation.error}</p>}
          {confirmed && <p>{confirmed.proto} · {formatBitrate(confirmed.bitrate.value)}</p>}
          <div className="stream-target-actions">
            {!live && writable && <button type="button" className="maintenance-secondary-button" onClick={onReturnLive}>{t("streamTarget.live")}</button>}
            <button type="button" className="maintenance-secondary-button" disabled={!connected || busy} onClick={() => void refresh()}>{t("streamTarget.refresh")}</button>
            {pending.length > 0 && <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting} onClick={() => setConfirmRestart(true)}>{t("streamTarget.restart")}</button>}
            {confirmed && <button type="button" className="maintenance-save-button" onClick={() => onInspect(confirmed)}>{t("streamTarget.inspect")}</button>}
            <button type="button" className="maintenance-secondary-button" disabled={busy || restarting} onClick={() => { setSaved(null); setMessage(""); }}>{t("streamTarget.continueEditing")}</button>
          </div>
        </section>}
        {confirmRestart && <section role="alertdialog" aria-label={t("streamTarget.restart")}>
          <p>{t("streamTarget.restartHint")}</p><ul>{pending.map(process => <li key={process.name}>{process.name}</li>)}</ul>
          <div className="stream-target-actions">
            <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => setConfirmRestart(false)}>{t("streamTarget.cancel")}</button>
            <button type="button" className="maintenance-save-button" disabled={locked || !runtime?.control.available || restarting || !pending.length} onClick={() => void restart()}>{t("streamTarget.restart")}</button>
          </div>
        </section>}
      </>}
    </div>
    const select = () => {
      setSelectedInterfaceKeyRaw(null); setSelectedStreamKeyRaw(streamKey); setSelectedFlowKeyRaw(flowKey);
      if (streamTarget && target && streamTarget.streamKey !== streamKey && investigationDock.activeTab === "settings") { setStreamTargetDirty(false); setStreamTarget(target); }
      afterSelect?.();
    };
    selectionGuard.current(() => {
      if (streamTarget && streamTarget.streamKey !== streamKey && investigationDock.activeTab === "settings") leaveStreamTarget(select);
      else select();
    });
  };
  const selectStreamsInterface = (interfaceKey: string, afterSelect?: () => void) => {
    const select = () => {
      setSelectedInterfaceKeyRaw(interfaceKey); setSelectedStreamKeyRaw(null); setSelectedFlowKeyRaw(null);
      if (investigationDock.activeTab === "settings") releaseStreamTarget();
      afterSelect?.();
    };
    selectionGuard.current(() => {
      if (streamTarget && investigationDock.activeTab === "settings") leaveStreamTarget(select);
      else select();
    });
  };
  const openStreamTargetSettings = () => {
    const open = () => {
      if (targetSettingsSelection && streamTarget?.streamKey !== targetSettingsSelection.streamKey) {
        setStreamTargetDirty(false); setStreamTarget(targetSettingsSelection);
      }
      investigationDock.open("settings");
    };
    if (streamTarget?.streamKey !== targetSettingsSelection?.streamKey) leaveStreamTarget(open);
    else open();
  };
  const renderStreamTargetAction = () => <button type="button" className="dashboard-action-button button-with-icon stream-target-open"
    disabled={!targetSettingsSelection || !targetSettingsWritable || socketState !== "connected"}
    onClick={openStreamTargetSettings}>
    <Icon name="monitoringSettings" size={15} />{t("streamTarget.title")}
  </button>;
  const renderStreamTargetPanel = () => streamTarget ? <div className="stream-target-dock-content">
    {selectedStreamKey !== streamTarget.streamKey && <div className="stream-target-context" role="status">
      <span>{t("streamTarget.differentSelection", { name: streamTarget.displayName ?? streamTarget.label })}</span>
      <button type="button" className="maintenance-secondary-button" disabled={!targetSettingsSelection || !targetSettingsWritable || socketState !== "connected"} onClick={openStreamTargetSettings}>{t("streamTarget.useSelection")}</button>
    </div>}
    <StreamTargetSettings key={streamTarget.streamKey} docked stream={streamTarget} streams={streams}
      writable={targetSettingsWritable} live={targetSettingsWritable && !paused && tabContextTimeSec === null} connected={socketState === "connected"}
      onRequestLeave={leaveStreamTarget} onEditingState={updateStreamTargetEditing}
      onAlertsSaved={setAlertDocument} onClose={investigationDock.close}
      onReturnLive={resumeLiveTime}
      onInspect={stream => navigationGuard.current(() => {
        resumeLiveTime(); setQuery(""); selectInspectorStream(stream.streamKey);
        if (standaloneView) activateInvestigationTab("detail");
        else openInspectorContext();
      })} />
    </div> : <div className="investigation-dock-empty stream-target-empty">
      <p>{t("streamTarget.chooseCommunication")}</p>
      <button type="button" className="maintenance-secondary-button" onClick={() => navigationGuard.current(() => activateInvestigationTab("streams"))}>{t("streamTarget.openStreams")}</button>
    </div>;
  const renderInspectorContext = () => inspectorContext.open && activeTab !== "detail" ? <div className="inspector-context-frame" onKeyDown={(event) => { if (event.key === "Escape") { event.stopPropagation(); closeInspectorContext(); } }}>
    <PaneSplitter className="inspector-context-splitter" label="Resize Inspector" orientation="vertical" dragging={resizingPane === "width"} onPointerDown={startResizeInspectorContext} onKeyDown={(event) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      event.preventDefault();
      const hostWidth = event.currentTarget.closest(".main-tab-view")?.getBoundingClientRect().width ?? 0;
      const step = event.shiftKey ? 64 : 24;
      adjustInspectorContextWidth(hostWidth, event.key === "ArrowLeft" ? step : -step);
    }} />
    <aside className="inspector-context-pane" aria-label="Inspector">
    <PaneHeader className="inspector-context-toolbar" icon="detail" title="Inspector" meta={(contextPinned ? "Pinned" : "Following selection") + " · " + contextTargetLabel} actions={<div className="dashboard-actions">
  const [captureHealth, setCaptureHealth] = useState<CaptureHealthSnapshot | null>(null);
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    const saved = window.localStorage.getItem("stm-theme");
