  }, [streamTargetGuard]);
  const updateStreamTargetEditing = useCallback((dirty: boolean, busy: boolean) => {
    streamTargetGuard.current = { dirty, busy }; setStreamTargetDirty(dirty);
  }, [streamTargetGuard]);
  const leaveStreamTarget = targetGuard.requestLeave;
  useEffect(() => investigationDock.registerCloseGuard(close => leaveStreamTarget(() => {
    releaseStreamTarget(); close();
  })), [investigationDock.registerCloseGuard, leaveStreamTarget, releaseStreamTarget]);
  const [selectedStreamKey, setSelectedStreamKeyRaw] = useState<string | null>(() => initialParams.get("streamKey"));
  const setSelectedStreamKey = (value: string | null) => selectionGuard.current(() => setSelectedStreamKeyRaw(value));
  const [selectedFlowKey, setSelectedFlowKeyRaw] = useState<string | null>(() => initialParams.get("flowKey"));
  const setSelectedFlowKey = (value: string | null) => selectionGuard.current(() => setSelectedFlowKeyRaw(value));
  const [dismissedRecentAlertKeys, setDismissedRecentAlertKeys] = useState<Set<string>>(() => new Set());
  const [selectedInterfaceKey, setSelectedInterfaceKeyRaw] = useState<string | null>(() => initialParams.get("interfaceKey"));
  const setSelectedInterfaceKey = (value: string | null) => selectionGuard.current(() => setSelectedInterfaceKeyRaw(value));
  const [query, setQuery] = useState(() => initialParams.get("query") ?? "");
  const [expandLevel, setExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("expand")));
export type MaintenanceSettingsResponse = {
  revision: number;
  sections: Array<{ id: string; label: string; description?: string; settings: MaintenanceSetting[] }>;
  values: AppConfig;
};

export type ProtocolRule = { enabled?: boolean; observe?: boolean; proto: "RTP" | "SRT" | "HLS" | "UDP" | "TCP"; endpoints?: string | string[]; hosts?: string | string[]; domains?: string | string[]; interfaces?: string | string[]; decode_as?: string | string[]; fec?: boolean; vlan?: number | string | null; stream_name?: string; id?: string; target_type?: "single" | "group"; };
export type MonitoringTargetGroup = { id: string; kind: "bidirectional_pair" | "redundancy_set"; name?: string; members: string[]; paths?: Record<string, string>; };
export type ProtocolMapDocument = { observe_mode?: "all" | "configured_only" | "configured_plus_other"; protocols: ProtocolRule[]; target_groups?: MonitoringTargetGroup[]; };
export type ProtocolMapResponse = { revision: string; path: string; document: ProtocolMapDocument; apply: "restart_required"; };
export type SystemCapturePolicy = { configured: boolean; path?: string; revision?: string; guardrails: { forbiddenInterfaces: string[]; requiredBpfExclusions: string[]; }; };
export type CaptureDocument = { interfaces?: string[]; auto_interfaces?: boolean; include_loopback?: boolean; exclude_interfaces?: string[]; bpf_filter?: string; };
export type CaptureCandidate = { name: string; selectable: boolean; reason?: string; selected: boolean; };
export type CaptureSettingsResponse = { revision: string; document: CaptureDocument; candidates: CaptureCandidate[]; apply: "capture_restart_required"; };
export type RuntimeProcessState = "RUNNING" | "STARTING" | "STOPPING" | "STOPPED" | "BACKOFF" | "FATAL" | "EXITED" | "UNKNOWN";
export type RuntimeActivationState = "current" | "restart_required" | "restarting" | "restart_failed";
export type RuntimeProcessName = "capture" | "stm" | "projector" | "healthd" | "frontend";
export type RuntimeProcess = { name: RuntimeProcessName; state: RuntimeProcessState; pid?: number; startedAt?: number; detail?: string; ready?: boolean; activation: { state: RuntimeActivationState; areas: Array<"capture" | "protocol_map" | "alerts">; updatedAt: number; operationId?: string; error?: string; }; };
export type RuntimeProcessesResponse = { control: { available: boolean; reason?: string; }; processes: RuntimeProcess[]; updatedAt: number; };
export type RuntimeRestartOperation = { id: string; state: "running" | "succeeded" | "failed"; targets: RuntimeProcessName[]; processes: Array<{ name: RuntimeProcessName; state: RuntimeProcessState; pid?: number; startedAt?: number; detail?: string; ready?: boolean; }>; startedAt: number; completedAt?: number; error?: string; };
export type SetupState = { revision: string; policy: SystemCapturePolicy; capture: CaptureSettingsResponse; protocolMap: ProtocolMapResponse; alerts: AlertsResponse; runtime: RuntimeProcessesResponse; };
