test('confirmation requires active fresh traffic, the BE target ID, expected protocol and activated running STM',()=>{
  const rtp={...raw,proto:'RTP',streamKey:'new-rtp',flows:[{...raw.flows[0],monitoringTargetIds:['camera']}]};
