  for(const traffic of [raw,{...rtp,active:false},{...rtp,flows:[{...rtp.flows[0],active:false}]},{...rtp,flows:[{...rtp.flows[0],lastSeen:100}]},{...rtp,flows:[{...rtp.flows[0],monitoringTargetIds:['other']}]}]){
