  const hosts = asStrings(rule.hosts).concat(asStrings(rule.domains));
  if (rule.enabled !== false && !endpoints.length && !hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: an endpoint or host is required while enabled`);
  if (["RTP", "SRT", "UDP", "TCP"].includes(rule.proto.toUpperCase()) && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: hosts are supported by HLS only`);
  if (["UDP", "TCP"].includes(rule.proto.toUpperCase())) {
    if (asStrings(rule.decode_as).length || rule.fec === true) throw new ProtocolMapValidationError(`row ${index + 1}: ${rule.proto} does not support decode_as or FEC`);
    if (endpoints.some((endpoint) => !isIpEndpoint(endpoint))) throw new ProtocolMapValidationError(`row ${index + 1}: ${rule.proto} requires an IP endpoint with port 0-65535`);
  }
  if (rule.proto.toUpperCase() === "HLS" && endpoints.length && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: choose an endpoint or host, not both`);
