import { directTargetBinding, policyTitle, removeBinding, replaceBinding, resolveAlertPolicy } from "../alertsPolicy";
import type { AlertBinding, AlertBindingMode, AlertMetricDefinition, AlertRule, AlertsDocument, MonitoringTargetDefinition } from "../types/api";
import { AlertConditionTable, newAlertCondition } from "./AlertConditionTable";

export function TargetAlertPolicyPanel({ target, document, metrics, protocols, flowRoles, busy, onDocument }: { target: MonitoringTargetDefinition; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onDocument: (document: AlertsDocument) => void }) {
  const direct = directTargetBinding(document, target.id);
  const effective = resolveAlertPolicy(document, { target: "flow", proto: target.proto, monitoringTargetIds: [target.id] });
  const mode = direct?.mode ?? "inherit";
  const update = (next: AlertBinding) => onDocument(replaceBinding(document, next));
  const setMode = (next: "inherit" | AlertBindingMode) => {
    if (next === "inherit") { onDocument(removeBinding(document, { kind: "managed_target", target_id: target.id })); return; }
    const scope = { kind: "managed_target" as const, target_id: target.id, target_type: target.target_type };
    const fallbackPolicy = document.policies.find((policy) => policy.conditions.some((condition) => condition.proto === target.proto)) ?? document.policies[0];
    if (next === "shared") update({ scope, mode: "shared", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
    else if (next === "shared_with_adjustments") update({ scope, mode: "shared_with_adjustments", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
    else if (next === "individual") update({ scope, mode: "individual", conditions: [newAlertCondition(target.proto, flowRoles, [], target.flowRoles)] });
    else update({ scope, mode: "disabled" });
  };
  const selectSharedPolicy = (policyId: string) => { if (direct && (direct.mode === "shared" || direct.mode === "shared_with_adjustments")) update({ ...direct, policy_id: policyId }); };
  const updateIndividual = (conditions: AlertRule[]) => { if (direct?.mode === "individual") update({ ...direct, conditions }); };
  const basePolicy = direct?.policy_id ? document.policies.find((policy) => policy.id === direct.policy_id) : undefined;
  const adjustedConditions = basePolicy?.conditions.map((rule) => ({ ...rule, ...(direct?.adjustments?.[rule.id] ?? {}) })) ?? [];
  const updateAdjusted = (rules: AlertRule[]) => {
    if (direct?.mode !== "shared_with_adjustments" || !basePolicy) return;
    const base = new Map(basePolicy.conditions.map((rule) => [rule.id, rule]));
    const adjustments = Object.fromEntries(rules.flatMap((rule) => {
      const source = base.get(rule.id);
      if (!source) return [];
      const patch = adjustmentPatch(source, rule);
      return Object.keys(patch).length ? [[rule.id, patch]] : [];
    }));
    const { adjustments: _previousAdjustments, ...withoutAdjustments } = direct;
    update({ ...withoutAdjustments, ...(Object.keys(adjustments).length ? { adjustments } : {}) });
  };
  const updateAdditional = (additional_conditions: AlertRule[]) => { if (direct?.mode === "shared_with_adjustments") { const { additional_conditions: _previousAdditional, ...withoutAdditional } = direct; update({ ...withoutAdditional, ...(additional_conditions.length ? { additional_conditions } : {}) }); } };

  return <section className="protocol-map-alert-policy"><header><div><h3>{target.title || target.id}</h3><p>{target.title ? `${target.id} · ` : ""}{target.proto} · {target.target_type}</p></div><strong>{targetModeLabel(mode)}</strong></header><div className="protocol-map-alert-policy-controls"><label>Monitoring method<select value={mode} disabled={busy} onChange={(event) => setMode(event.target.value as "inherit" | AlertBindingMode)}><option value="inherit">Use protocol or group default</option><option value="shared">Common policy only</option><option value="individual">Target-specific policy only</option><option value="shared_with_adjustments">Common policy with target-specific adjustments</option><option value="disabled">Alert evaluation disabled</option></select></label>{mode === "inherit" && <p className="protocol-map-notice">{effective.mode === "unconfigured" ? "No applicable default policy is configured." : `Effective policy: ${policyTitle(document, effective.binding?.policy_id) ?? targetModeLabel(effective.mode)}`}</p>}{(mode === "shared" || mode === "shared_with_adjustments") && <label>Common policy<select value={direct?.policy_id ?? ""} disabled={busy || document.policies.length === 0} onChange={(event) => selectSharedPolicy(event.target.value)}><option value="" disabled>Select a common policy</option>{document.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.title || policy.id}</option>)}</select></label>}{mode === "disabled" && <p className="protocol-map-notice">No alert conditions will be evaluated for this Monitoring target, even if a protocol default exists.</p>}</div>{mode === "individual" && <AlertConditionTable title="Target-specific conditions" rules={direct?.conditions ?? []} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateIndividual} />}{mode === "shared_with_adjustments" && basePolicy && <><AlertConditionTable title="Target-specific adjustments" rules={adjustedConditions} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateAdjusted} lockedIdentity /><AlertConditionTable title="Additional target-specific conditions" rules={direct?.additional_conditions ?? []} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateAdditional} /></>}</section>;
}

export function targetPolicyModeLabel(mode: "inherit" | AlertBindingMode) { return targetModeLabel(mode); }

function targetModeLabel(mode: "inherit" | AlertBindingMode) { return mode === "inherit" ? "Inherited default" : mode === "shared" ? "Common policy" : mode === "individual" ? "Target-specific policy" : mode === "shared_with_adjustments" ? "Common policy + adjustments" : "Alert evaluation disabled"; }
function adjustmentPatch(base: AlertRule, effective: AlertRule): Partial<AlertRule> { const fields: Array<keyof AlertRule> = ["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"]; return Object.fromEntries(fields.flatMap((field) => base[field] !== effective[field] ? [[field, effective[field]]] : [])) as Partial<AlertRule>; }
