    <InspectorUnsavedDialog open={paneEditor.pending} saving={paneEditor.status === "saving"} error={paneEditor.error} onSave={() => void paneEditor.saveAndLeave()} onDiscard={paneEditor.discardAndLeave} onContinue={paneEditor.continueEditing} />
  </>;

