function inspectorDetailUrl(target: InspectorTarget) {
  const url = new URL("/view/detail", window.location.origin);
  if (target.kind === "interface") url.searchParams.set("interfaceKey", target.interfaceKey);
  else {
    url.searchParams.set("streamKey", target.streamKey);
    if (target.kind === "flow") url.searchParams.set("flowKey", target.flowKey);
  }
  return url.toString();
}

function InspectorTargetActionsMenu({ target, onRevealInStreams }: { target: StreamInspectorTarget | null; onRevealInStreams: () => void }) {
  const { t } = useI18n();
  if (!target) return null;
  const key = target.kind === "flow" ? target.flowKey : target.streamKey;
  return <HeaderActionMenu label={t("tooltip.inspectorActions")} tooltipKey="tooltip.inspectorActions">{close => <>
      <button type="button" role="menuitem" onClick={() => { close(); void copyText(inspectorDetailUrl(target)); }}><Icon name="copy" size={15} /><span>{t("tooltip.copyInspectorUrl")}</span></button>
      <button type="button" role="menuitem" onClick={() => { close(); void copyText(key); }}><Icon name="copy" size={15} /><span>{t(target.kind === "flow" ? "tooltip.copyFlowKey" : "tooltip.copyStreamKey")}</span></button>
      <button type="button" role="menuitem" onClick={() => { close(); onRevealInStreams(); }}><Icon name="streams" size={15} /><span>{t("tooltip.openInStreams")}</span></button>
  </>}</HeaderActionMenu>;
}

