import { useEffect, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { Icon } from "./Icon";

type Props = { label: string; tooltipKey: string; children: (close: () => void) => ReactNode };

// Keep the popup outside the header's horizontal scrollport.
export function HeaderActionMenu({ label, tooltipKey, children }: Props) {
  const [opened, setOpened] = useState(false);
  const [position, setPosition] = useState({ top: 0, left: 0 });
  const menuRef = useRef<HTMLSpanElement>(null);
  const popupRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node) && !popupRef.current?.contains(event.target as Node)) setOpened(false);
    };
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") setOpened(false); };
    const onViewportChange = () => setOpened(false);
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    window.addEventListener("resize", onViewportChange);
    window.addEventListener("scroll", onViewportChange, true);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("resize", onViewportChange);
      window.removeEventListener("scroll", onViewportChange, true);
    };
  }, [opened]);
  return <span ref={menuRef} className="inspector-target-actions-menu" onPointerDown={event => event.stopPropagation()} onClick={event => event.stopPropagation()}>
    <button type="button" className="dashboard-action-button icon-only" aria-label={label} aria-expanded={opened} data-tooltip-key={tooltipKey} onClick={event => {
      const rect = event.currentTarget.getBoundingClientRect();
      setPosition({ top: rect.bottom + 2, left: Math.max(8, Math.min(rect.right - 196, window.innerWidth - 204)) });
      setOpened(current => !current);
    }}><Icon name="more" size={15} /></button>
    {opened && createPortal(<span ref={popupRef} className="inspector-target-actions-popup header-action-popup" style={position} role="menu" aria-label={label}>
      {children(() => setOpened(false))}
    </span>, document.body)}
  </span>;
}
