import { useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { getSetupState } from "../api/client";
import { useI18n } from "../i18n";
import type { ProtocolRule, StreamListItem } from "../types/api";
import { ruleList } from "./monitoringTargetSelection";

export function MonitoringTargetPicker({ streams, onSelect, onClose, onOpenLegacy }: {
  streams: StreamListItem[];
  onSelect: (rule: ProtocolRule) => void;
  onClose: () => void;
  onOpenLegacy: () => void;
}) {
  const { t } = useI18n();
  const dialog = useRef<HTMLDialogElement>(null);
  const heading = useId();
  const [rules, setRules] = useState<ProtocolRule[]>([]);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [version, setVersion] = useState(0);
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    dialog.current?.showModal();
    return () => { dialog.current?.close(); if (opener?.isConnected) opener.focus(); };
  }, []);
  useEffect(() => {
    let active = true;
    setLoading(true); setError("");
    void getSetupState().then(state => { if (active) setRules(state.protocolMap.document.protocols); })
      .catch((caught: unknown) => { if (active) setError(caught instanceof Error ? caught.message : t("streamTarget.loadFailed")); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [version]);
  const detected = new Set(streams.filter(stream => stream.active).flatMap(stream => stream.flows.filter(flow => flow.active).flatMap(flow => flow.monitoringTargetIds ?? [])));
  const search = query.trim().toLocaleLowerCase();
  const filtered = rules.filter(rule => rule.id && [rule.stream_name, rule.id, rule.proto, ...ruleList(rule.endpoints), ...ruleList(rule.hosts), ...ruleList(rule.domains), ...ruleList(rule.interfaces)].join(" ").toLocaleLowerCase().includes(search));
  return createPortal(<dialog ref={dialog} className="stream-target-discard-dialog monitoring-target-picker" aria-labelledby={heading} onCancel={event => { event.preventDefault(); onClose(); }} onKeyDown={event => event.stopPropagation()}>
    <h2 id={heading}>{t("streamTarget.chooseRegistered")}</h2>
    <label className="stream-target-field">{t("streamTarget.searchTargets")}<input autoFocus type="search" value={query} onChange={event => setQuery(event.target.value)} /></label>
    <div className="monitoring-target-picker-list" aria-busy={loading}>
      {loading ? <p role="status">{t("common.loading")}</p> : error ? <>
        <p role="alert">{error}</p><button type="button" className="maintenance-secondary-button" onClick={() => setVersion(value => value + 1)}>{t("streamTarget.reload")}</button>
      </> : <>
        {!filtered.length && <p role="status">{t("streamTarget.noTargets")}</p>}
        {filtered.map(rule => <button type="button" key={rule.id} className="maintenance-secondary-button monitoring-target-picker-item" onClick={() => onSelect(rule)}>
          <strong>{rule.stream_name || rule.id}</strong>
          <span>{rule.proto}{rule.fec ? "-FEC" : ""} · {[...ruleList(rule.endpoints), ...ruleList(rule.hosts), ...ruleList(rule.domains)].join(", ") || "—"}</span>
          <small>{rule.id} · {ruleList(rule.interfaces).join(", ") || t("streamTarget.any")} · {t(rule.enabled === false ? "streamTarget.targetDisabled" : rule.observe === false ? "streamTarget.observationDisabled" : "streamTarget.targetEnabled")} · {t(detected.has(rule.id!) ? "streamTarget.currentlyDetected" : "streamTarget.notDetected")}</small>
        </button>)}
        {rules.some(rule => !rule.id) && <p>{t("streamTarget.legacyTargets")}</p>}
      </>}
    </div>
    <div className="stream-target-discard-actions">
      <button type="button" className="maintenance-secondary-button" onClick={onOpenLegacy}>{t("streamTarget.openTargets")}</button>
      <button type="button" className="maintenance-secondary-button" onClick={onClose}>{t("streamTarget.cancel")}</button>
    </div>
  </dialog>, document.body);
}
