int alert_evaluator::load(const std::filesystem::path &path) {
	m_bindings.clear();
	m_states.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		trace(0, "alert_evaluator: failed to open %s", path.string().c_str());
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		trace(0, "alert_evaluator: failed to parse %s: %s", path.string().c_str(), e.what());
		return -1;
	}

	if(!root.is_object() || !root.contains("policies") || !root["policies"].is_array() || !root.contains("bindings") || !root["bindings"].is_array()) {
		trace(0, "alert_evaluator: monitoring policy format requires policies and bindings arrays");
		return -1;
	}

	auto parse_rule = [this](const json &entry, const std::string &compiled_id) {
		if(!entry.is_object()) throw std::runtime_error("condition must be an object");
		if(!entry.contains("id") || !entry["id"].is_string() || entry["id"].get<std::string>().empty()) throw std::runtime_error("condition requires a non-empty string id");
		if(!entry.contains("metric") || !entry["metric"].is_string() || entry["metric"].get<std::string>().empty()) throw std::runtime_error("condition requires a non-empty string metric");

		rule r;
		r.id = compiled_id;
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target")) {
			if(!entry["target"].is_string()) throw std::runtime_error("condition target must be a string");
			r.target = entry["target"].get<std::string>();
			if(r.target != "any" && r.target != "flow" && r.target != "stream" && r.target != "interface") throw std::runtime_error("condition target is invalid");
		}
		if(entry.contains("proto")) {
			if(!entry["proto"].is_string()) throw std::runtime_error("condition proto must be a string");
			r.proto = entry["proto"].get<std::string>();
		}
		if(entry.contains("flow_roles")) {
			if(!entry["flow_roles"].is_array() || r.target != "flow") throw std::runtime_error("flow_roles requires flow target");
			for(const auto &role : entry["flow_roles"]) {
				if(!role.is_string() || role.get<std::string>().empty()) throw std::runtime_error("flow_roles must contain non-empty strings");
				if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role.get<std::string>()) != r.flow_roles.end()) throw std::runtime_error("flow_roles must not contain duplicates");
				r.flow_roles.push_back(role.get<std::string>());
			}
		}
		if(entry.contains("indicator_category")) {
			if(!entry["indicator_category"].is_string() || (entry["indicator_category"] != "quality" && entry["indicator_category"] != "other")) throw std::runtime_error("indicator_category must be quality or other");
			r.indicator_category = entry["indicator_category"].get<std::string>();
		}
		if(entry.contains("type")) {
			if(!entry["type"].is_string()) throw std::runtime_error("condition type must be a string");
			r.type = parse_rule_type(entry["type"].get<std::string>());
		}
		if(entry.contains("operator")) {
			if(!entry["operator"].is_string()) throw std::runtime_error("condition operator must be a string");
			r.op = parse_compare_op(entry["operator"].get<std::string>());
		}
		auto read_number = [&entry](const char *key, double &value) {
			if(!entry.contains(key)) return;
			if(!entry[key].is_number()) throw std::runtime_error(std::string(key) + " must be numeric");
			value = entry[key].get<double>();
			if(!std::isfinite(value)) throw std::runtime_error(std::string(key) + " must be finite");
		};
		read_number("error_threshold", r.error_threshold);
		if(entry.contains("recover_threshold")) read_number("recover_threshold", r.recover_threshold);
		else r.recover_threshold = r.error_threshold;
		read_number("delta_threshold", r.delta_threshold);
		read_number("trigger_after_sec", r.trigger_after_sec);
		if(entry.contains("recover_after_sec")) read_number("recover_after_sec", r.recover_after_sec);
		else r.recover_after_sec = r.type == rule_type::counter_delta ? 3.0 : 0.0;
		read_number("missing_after_sec", r.missing_after_sec);
		read_number("inactive_after_sec", r.inactive_after_sec);
		if(r.trigger_after_sec < 0.0 || r.recover_after_sec < 0.0 || r.missing_after_sec < 0.0 || r.inactive_after_sec < 0.0) throw std::runtime_error("alert durations must be non-negative");
		if(r.type == rule_type::availability && r.inactive_after_sec <= 0.0) throw std::runtime_error("availability conditions require inactive_after_sec greater than zero");
		if(entry.contains("severity")) {
			if(!entry["severity"].is_string() || entry["severity"].get<std::string>().empty()) throw std::runtime_error("severity must be a non-empty string");
			r.severity = entry["severity"].get<std::string>();
		}
		if(entry.contains("enabled") && !entry["enabled"].is_boolean()) throw std::runtime_error("enabled must be boolean");
		r.enabled = read_bool(entry, "enabled", true);
		return r;
	};

	auto apply_adjustment = [](rule &r, const json &adjustment) {
		if(!adjustment.is_object()) throw std::runtime_error("individual adjustment must be an object");
		for(const auto &[key, value] : adjustment.items()) {
			if(key == "enabled") {
				if(!value.is_boolean()) throw std::runtime_error("individual adjustment enabled must be boolean");
				r.enabled = value.get<bool>();
			}
			else if(key == "severity") {
				if(!value.is_string() || value.get<std::string>().empty()) throw std::runtime_error("individual adjustment severity must be a non-empty string");
				r.severity = value.get<std::string>();
			}
			else if(key == "error_threshold" || key == "recover_threshold" || key == "delta_threshold" || key == "trigger_after_sec" || key == "recover_after_sec" || key == "missing_after_sec" || key == "inactive_after_sec") {
				if(!value.is_number() || !std::isfinite(value.get<double>())) throw std::runtime_error("individual adjustment numeric value must be finite");
				const auto number = value.get<double>();
				if((key == "trigger_after_sec" || key == "recover_after_sec" || key == "missing_after_sec" || key == "inactive_after_sec") && number < 0.0) throw std::runtime_error("individual adjustment duration must be non-negative");
				if(key == "error_threshold") r.error_threshold = number;
				else if(key == "recover_threshold") r.recover_threshold = number;
				else if(key == "delta_threshold") r.delta_threshold = number;
				else if(key == "trigger_after_sec") r.trigger_after_sec = number;
				else if(key == "recover_after_sec") r.recover_after_sec = number;
				else if(key == "missing_after_sec") r.missing_after_sec = number;
				else r.inactive_after_sec = number;
			}
			else throw std::runtime_error("unsupported individual adjustment field " + key);
		}
		if(r.type == rule_type::availability && r.inactive_after_sec <= 0.0) throw std::runtime_error("availability conditions require inactive_after_sec greater than zero");
	};

	std::map<std::string, json> policies;
	for(const auto &policy : root["policies"]) {
		if(!policy.is_object() || !policy.contains("id") || !policy["id"].is_string() || policy["id"].get<std::string>().empty() || !policy.contains("conditions") || !policy["conditions"].is_array()) {
			trace(0, "alert_evaluator: policy requires id and conditions");
			return -1;
		}
		const auto id = policy["id"].get<std::string>();
		if(!policies.emplace(id, policy).second) {
			trace(0, "alert_evaluator: duplicate policy id %s", id.c_str());
			return -1;
		}
		std::set<std::string> condition_ids;
		try {
			for(const auto &condition : policy["conditions"]) {
				const auto condition_id = condition.at("id").get<std::string>();
				if(!condition_ids.insert(condition_id).second) throw std::runtime_error("duplicate condition id " + condition_id);
				(void)parse_rule(condition, id + "." + condition_id);
			}
		}
		catch(const std::exception &e) {
			trace(0, "alert_evaluator: invalid policy %s: %s", id.c_str(), e.what());
			return -1;
		}
	}

	std::set<std::string> binding_scopes;
	for(const auto &entry : root["bindings"]) {
		try {
			if(!entry.is_object() || !entry.contains("scope") || !entry["scope"].is_object() || !entry.contains("mode") || !entry["mode"].is_string()) throw std::runtime_error("binding requires scope and mode");
			const auto &scope = entry["scope"];
			if(!scope.contains("kind") || !scope["kind"].is_string()) throw std::runtime_error("binding scope requires kind");

import type { AlertBinding, AlertBindingScope, AlertPolicy, AlertRule, AlertsDocument } from "./types/api";

export type AlertPolicyContext = {
  target: "flow" | "interface";
  proto?: string;
  monitoringTargetIds?: string[];
};

export type ResolvedAlertCondition = {
  rule: AlertRule;
  source: "shared" | "individual" | "individual_adjustment" | "additional";
};

export type ResolvedAlertPolicy = {
  mode: AlertBinding["mode"] | "unconfigured";
  binding?: AlertBinding;
  policy?: AlertPolicy;
  conditions: ResolvedAlertCondition[];
};

export function resolveAlertPolicy(document: AlertsDocument | undefined, context: AlertPolicyContext): ResolvedAlertPolicy {
  if (!document) return { mode: "unconfigured", conditions: [] };
  const candidate = document.bindings
    .map((binding) => ({ binding, priority: bindingPriority(binding, context) }))
    .filter((item) => item.priority >= 0)
    .sort((left, right) => right.priority - left.priority || bindingKey(left.binding).localeCompare(bindingKey(right.binding)))[0]?.binding;
  if (!candidate) return { mode: "unconfigured", conditions: [] };
  if (candidate.mode === "disabled") return { mode: "disabled", binding: candidate, conditions: [] };
  if (candidate.mode === "individual") return {
    mode: candidate.mode,
    binding: candidate,
    conditions: (candidate.conditions ?? []).map((rule) => ({ rule, source: "individual" as const }))
  };
  const policy = document.policies.find((item) => item.id === candidate.policy_id);
  if (!policy) return { mode: candidate.mode, binding: candidate, conditions: [] };
  const conditions: ResolvedAlertCondition[] = policy.conditions.map((rule) => {
    const adjustment = candidate.mode === "shared_with_adjustments" ? candidate.adjustments?.[rule.id] : undefined;
    return { rule: { ...rule, ...(adjustment ?? {}) }, source: adjustment ? "individual_adjustment" as const : "shared" as const };
  });
  if (candidate.mode === "shared_with_adjustments") {
    conditions.push(...(candidate.additional_conditions ?? []).map((rule) => ({ rule, source: "additional" as const })));
  }
  return { mode: candidate.mode, binding: candidate, policy, conditions };
}

export function directTargetBinding(document: AlertsDocument, targetId: string) {
  return document.bindings.find((binding) => binding.scope.kind === "managed_target" && binding.scope.target_id === targetId);
}

export function bindingKey(binding: AlertBinding) {
  const scope = binding.scope;
  return scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
}

export function bindingPriority(binding: AlertBinding, context: AlertPolicyContext) {
  const scope = binding.scope;
  if (scope.kind === "protocol") {
    if (scope.proto && scope.proto !== context.proto) return -1;
    if (scope.target && scope.target !== "any" && scope.target !== context.target) return -1;
    return 0;
  }
  if (!context.monitoringTargetIds?.includes(scope.target_id)) return -1;
  return scope.target_type === "group" ? 1 : 2;
}

export function policyTitle(document: AlertsDocument, policyId: string | undefined) {
  if (!policyId) return undefined;
  const policy = document.policies.find((item) => item.id === policyId);
  return policy?.title || policy?.id || policyId;
}

export function emptyDocument(): AlertsDocument {
  return { policies: [], bindings: [] };
}

export function replaceBinding(document: AlertsDocument, next: AlertBinding) {
  const key = bindingKey(next);
  const bindings = document.bindings.some((binding) => bindingKey(binding) === key)
    ? document.bindings.map((binding) => bindingKey(binding) === key ? next : binding)
    : [...document.bindings, next];
  return { ...document, bindings };
}

export function removeBinding(document: AlertsDocument, scope: AlertBindingScope) {
  const key = scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
  return { ...document, bindings: document.bindings.filter((binding) => bindingKey(binding) !== key) };
}
import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { parseMetricSchema } from "./metricSchema";

export type AlertTarget = "any" | "flow" | "stream" | "interface";
export type AlertRuleType = "threshold" | "counter_delta" | "availability";
export type AlertOperator = ">" | ">=" | "<" | "<=" | "==" | "!=";
export type AlertIndicatorCategory = "quality" | "other";

export type AlertRule = {
  id: string;
  enabled?: boolean;
  target?: AlertTarget;
  proto?: string;
  flow_roles?: string[];
  indicator_category?: AlertIndicatorCategory;
  metric: string;
  type?: AlertRuleType;
  operator?: AlertOperator;
  error_threshold?: number;
  recover_threshold?: number;
  delta_threshold?: number;
  trigger_after_sec?: number;
  recover_after_sec?: number;
  missing_after_sec?: number;
  inactive_after_sec?: number;
  severity?: string;
};

export type AlertPolicy = { id: string; title?: string; conditions: AlertRule[] };
export type AlertBindingScope = { kind: "protocol"; proto?: string; target?: AlertTarget } | { kind: "managed_target"; target_id: string; target_type?: "single" | "group" };
export type AlertBindingMode = "shared" | "individual" | "shared_with_adjustments" | "disabled";
export type AlertBinding = { scope: AlertBindingScope; mode: AlertBindingMode; policy_id?: string; conditions?: AlertRule[]; adjustments?: Record<string, Partial<AlertRule>>; additional_conditions?: AlertRule[] };
export type AlertsDocument = { _note?: string; policies: AlertPolicy[]; bindings: AlertBinding[] };
export type MonitoringTargetDefinition = { id: string; target_type: "single" | "group"; proto: string; title?: string; flowRoles?: string[] };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean };
export type AlertsResponse = {
  revision: string;
  path: string;
  document: AlertsDocument;
  metrics: AlertMetricDefinition[];
  protocols: string[];
  flowRoles: Record<string, string[]>;
  apply: "restart_required";
  monitoringTargets: MonitoringTargetDefinition[];
};

export const supportedFlowRoles: Record<string, string[]> = { RTP: ["media", "fec_col", "fec_row"], SRT: ["data", "control", "mixed"] };

export class AlertsConflictError extends Error {}
export class AlertsValidationError extends Error {}

export class AlertsSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<AlertsResponse> {
    const configured = await this.readConfiguredAlerts();
    const schemaText = await readFile(this.schemaFile(), "utf8");
    const document = validateDocument(parseJson(configured.alertsText, "alerts config"));
    const schema = parseSchema(parseJson(schemaText, "alerts schema"));
    const monitoring = await this.readMonitoringTargets(configured.stmConfigText);
    return {
      revision: revisionOf(configured.stmConfigText, configured.alertsText, schemaText, monitoring.sourceText),
      path: configured.relativePath,
      document,
      metrics: schema.metrics,
      protocols: schema.protocols,
      flowRoles: supportedFlowRoles,
      apply: "restart_required",
      monitoringTargets: monitoring.targets
    };
  }

  async update(input: { revision: unknown; document: unknown }): Promise<AlertsResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new AlertsConflictError("alerts config changed on the server; reload before applying");
    }
    const document = validateDocument(input.document, current.metrics, current.protocols);
    const configured = await this.readConfiguredAlerts();
    await atomicWrite(configured.alertsFile, JSON.stringify(document, null, 2) + "\n");
    return this.get();
  }

  private async readConfiguredAlerts() {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.alerts ?? configs?.alert_config;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new AlertsValidationError("configs.alerts must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const alertsFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const alertsText = await readFile(alertsFile, "utf8");
    return { stmConfigText, relativePath, alertsFile, alertsText };
  }

  private async readMonitoringTargets(stmConfigText: string): Promise<{ targets: MonitoringTargetDefinition[]; sourceText: string }> {
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs) ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.protocol_map;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) return { targets: [], sourceText: "" };
    const sourceText = await readFile(path.resolve(path.dirname(this.stmConfigFile), validateRelativePath(configuredPath)), "utf8");
    const map = parseObject(sourceText, "protocol map");
    const protocols = Array.isArray(map.protocols) ? map.protocols : [];
    const targets = protocols.flatMap((item): MonitoringTargetDefinition[] => {
      if (!item || typeof item !== "object" || Array.isArray(item)) return [];
      const rule = item as Record<string, unknown>;
      if (typeof rule.id !== "string" || !rule.id.trim() || typeof rule.proto !== "string") return [];
      return [{ id: rule.id, proto: rule.proto, target_type: rule.target_type === "group" ? "group" : "single", ...(typeof rule.stream_name === "string" ? { title: rule.stream_name } : {}), ...(rule.proto.toUpperCase() === "RTP" && rule.fec === true ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }];
    });
    return { targets, sourceText };
  }

  private schemaFile() { return path.resolve(path.dirname(this.stmConfigFile), "alerts_config.schema.json"); }
}

function parseJson(text: string, label: string): unknown {
  try { return JSON.parse(text) as unknown; }
  catch (error) { throw new AlertsValidationError("invalid " + label + ": " + String(error)); }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  const value = parseJson(text, label);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("invalid " + label + ": must be an object");
  return value as Record<string, unknown>;
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new AlertsValidationError("alerts config path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new AlertsValidationError("alerts config path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertsDocument {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("alerts config must be a monitoring-policy object");
  const record = value as Record<string, unknown>;
  ensureAllowed(record, new Set(["_note", "policies", "bindings"]), "alerts config");
  if (record._note !== undefined && typeof record._note !== "string") throw new AlertsValidationError("_note must be a string");
  if (!Array.isArray(record.policies) || !Array.isArray(record.bindings)) throw new AlertsValidationError("monitoring policy format requires policies and bindings arrays");
  const policies = record.policies.map((policy, index) => validatePolicy(policy, index, metrics, protocols));
  ensureUniqueIds(policies, "policy");
  const policyById = new Map(policies.map((policy) => [policy.id, policy]));
  const bindings = record.bindings.map((binding, index) => validateBinding(binding, index, policyById, metrics, protocols));
  const scopes = new Set<string>();
  for (const binding of bindings) {
    const key = bindingScopeKey(binding.scope);
    if (scopes.has(key)) throw new AlertsValidationError("bindings must not share a scope: " + key);
    scopes.add(key);
  }
  return { ...(typeof record._note === "string" ? { _note: record._note } : {}), policies, bindings };
}

function ensureAllowed(value: Record<string, unknown>, allowed: Set<string>, label: string) {
  for (const key of Object.keys(value)) if (!allowed.has(key)) throw new AlertsValidationError(label + ": unsupported field " + key);
}

function ensureUniqueIds(items: Array<{ id: string }>, label: string) {
  const ids = new Set<string>();
  for (const item of items) {
    if (ids.has(item.id)) throw new AlertsValidationError(label + " ids must be unique: " + item.id);
    ids.add(item.id);
  }
}

