std::vector<std::string> protocol_map::matching_target_ids(std::string_view proto,
                                                           const ip_endpoint &src,
                                                           const ip_endpoint &dst,
                                                           const tsv::vlan_info &vlan,
                                                           std::string_view host,
                                                           std::string_view interface_name) const {
	std::vector<std::string> ids;
	for(const auto &r : m_rules) {
		if(r.id.empty() || !proto_matches(r.proto, proto) || !vlan_matches(r.vlan, vlan) || !interface_matches(r, interface_name)) continue;
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			if(std::find(ids.begin(), ids.end(), r.id) == ids.end()) ids.push_back(r.id);
		}
	}
	return ids;
}

std::vector<std::string> protocol_map::matching_group_ids(const std::vector<std::string> &target_ids) const {
	std::vector<std::string> ids;
	for(const auto &group : m_target_groups) {
		if(std::any_of(group.members.begin(), group.members.end(), [&target_ids](const std::string &member) {
			return std::find(target_ids.begin(), target_ids.end(), member) != target_ids.end();
		})) {
			ids.push_back(group.id);
		}
	}
	return ids;
}

