test('UI animations default On, migrate old persisted settings and retain explicit Off across restart and old-client saves',async t=>{
  const dir=await fs.mkdtemp(path.join(os.tmpdir(),'stm-maintenance-values-'));
  t.after(()=>fs.rm(dir,{recursive:true,force:true}));
  const options={definitionFile:path.resolve(__dirname,'../maintenance-settings.json'),runtimeFile:path.join(dir,'runtime-settings.json'),defaults};
  let settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().values.uiAnimationsEnabled,true);
  const legacy={...defaults};delete legacy.uiAnimationsEnabled;legacy.tooltipDelayMs=450;
  await fs.writeFile(options.runtimeFile,JSON.stringify({revision:7,values:legacy}));
  settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().revision,7);assert.equal(settings.get().values.tooltipDelayMs,450);
  assert.equal(settings.get().values.uiAnimationsEnabled,true,'missing old setting is filled without discarding the other values');
  await settings.update(7,{...settings.get().values,uiAnimationsEnabled:false});
  settings=await MaintenanceSettings.load(options);
  assert.equal(settings.get().values.uiAnimationsEnabled,false);
  await settings.update(8,legacy);
  assert.equal(settings.get().values.uiAnimationsEnabled,false,'an old client cannot reset the shared animation setting');
  for(const value of [null,0,'on'])await assert.rejects(settings.update(9,{...settings.get().values,uiAnimationsEnabled:value}),/must be boolean/);
  await assert.rejects(settings.update(8,settings.get().values),/settings changed/);
});

