  t.after(async()=>{for(const socket of sockets)socket.terminate();await stop();await fs.rm(dir,{recursive:true,force:true});});
  const start=async()=>{
    child=spawn(process.execPath,[path.resolve(__dirname,'../server/dist/index.js'),'--host=127.0.0.1','--port='+port,'--log-dir='+dir,'--state-dir='+dir+'/state','--process-control-socket='+dir+'/disabled.sock'],
      {cwd:path.resolve(__dirname,'..'),env:{...process.env,STM_ANALYSIS_STATE_FILE:'',STM_PLAYBACK_STATE_FILE:'',STM_CONFIG_FILE:''},stdio:['ignore','ignore','pipe']});
    let log='';child.stderr.on('data',x=>log+=x);
    for(let i=0;i<150;i++){
      assert.equal(child.exitCode,null,log);
      try{if((await fetch(base+'/api/config')).ok)return;}catch{}
      await sleep(30);
    }
    assert.fail('Server startup failed: '+log);
  };
  const get=async route=>(await fetch(base+route)).json();
  const save=body=>fetch(base+'/api/maintenance/frontend-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  await start();
  assert.equal((await get('/api/config')).uiAnimationsEnabled,true);
  const initial=await get('/api/maintenance/frontend-settings');
  const setting=initial.sections.flatMap(s=>s.settings).find(s=>s.key==='uiAnimationsEnabled');
