test('HTTP alerts API persists composed branches, marks activation pending and preserves 400/409 errors',{timeout:30000},async t=>{
 const net=require('node:net'),{spawn}=require('node:child_process'),{once}=require('node:events');
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'stm-composed-http-'));let child;
 t.after(async()=>{if(child&&child.exitCode===null){child.kill('SIGTERM');await once(child,'exit')}await fs.rm(dir,{recursive:true,force:true})});
 await fs.writeFile(path.join(dir,'stm.json'),JSON.stringify({configs:{alerts:'alerts.json',protocol_map:'protocols.json'},capture:{interfaces:['lo']}}));
 await fs.writeFile(path.join(dir,'protocols.json'),JSON.stringify({protocols:[{id:'camera',proto:'RTP',endpoints:['239.1.1.1:5000']}]}));
 await fs.writeFile(path.join(dir,'alerts.json'),JSON.stringify({policies:suite.policies,bindings:[]}));
 await fs.copyFile(path.resolve(__dirname,'../../conf/alerts_config.schema.json'),path.join(dir,'alerts_config.schema.json'));
 const probe=net.createServer();await new Promise(resolve=>probe.listen(0,'127.0.0.1',resolve));const port=probe.address().port;await new Promise(resolve=>probe.close(resolve));
 child=spawn(process.execPath,[path.resolve(__dirname,'../server/dist/index.js'),'--host=127.0.0.1','--port='+port,'--log-dir='+dir,'--state-dir='+dir+'/state','--process-control-socket='+dir+'/disabled.sock'],{cwd:path.resolve(__dirname,'..'),env:{...process.env,STM_CONFIG_FILE:path.join(dir,'stm.json'),STM_ANALYSIS_STATE_FILE:'',STM_PLAYBACK_STATE_FILE:''},stdio:['ignore','ignore','pipe']});
 let log='';child.stderr.on('data',data=>log+=data);
 const base='http://127.0.0.1:'+port;let current;
 for(let i=0;i<150;i++){assert.equal(child.exitCode,null,log);try{const response=await fetch(base+'/api/maintenance/alerts');if(response.ok){current=await response.json();break;}}catch{}await new Promise(resolve=>setTimeout(resolve,30))}
 assert.ok(current,'server startup: '+log);
 const document={policies:suite.policies,bindings:suite.cases.find(s=>s.name==='multiple').bindings};
 const put=body=>fetch(base+'/api/maintenance/alerts',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
 const saved=await put({revision:current.revision,document});assert.equal(saved.status,200);const next=await saved.json();assert.equal(next.apply,'restart_required');assert.equal(next.document.bindings[0].mode,'composed');assert.equal(next.document.bindings[0].policy_refs.length,2);
 const runtime=await (await fetch(base+'/api/runtime/processes')).json();assert.ok(runtime.processes.some(process=>process.name==='stm'&&process.activation.state==='restart_required'));
 assert.equal((await put({revision:current.revision,document})).status,409);
 const invalid=await put({revision:next.revision,document:{...document,bindings:[{...document.bindings[0],policy_refs:[{policy_id:'missing'}]}]}});assert.equal(invalid.status,400);assert.equal(typeof (await invalid.json()).error,'string');
 assert.deepEqual((await (await fetch(base+'/api/maintenance/alerts')).json()).document,next.document);
});
EOF
