export function resolveAlertPolicy(document: AlertsDocument | undefined, context: AlertPolicyContext): ResolvedAlertPolicy {
  if (!document) return { mode: "unconfigured", conditions: [] };
  const resolve = (below: number): ResolvedAlertPolicy => {
    const candidates = document.bindings.map(binding => ({ binding, priority: bindingPriority(binding, context) }))
      .filter(item => item.priority >= 0 && item.priority < below)
      .sort((left, right) => right.priority - left.priority || (bindingKey(left.binding) < bindingKey(right.binding) ? -1 : 1));
    const candidate = candidates[0]?.binding;
    if (!candidate) return { mode: "unconfigured", conditions: [] };
    if (candidate.mode === "disabled" || candidate.mode === "composed" && candidate.enabled === false) return { mode: "disabled", binding: candidate, conditions: [] };
    const scoped = (rule: AlertRule): AlertRule => candidate.scope.kind === "protocol" ? { ...rule,
      ...(candidate.scope.proto ? { proto: candidate.scope.proto } : {}), ...(candidate.scope.target ? { target: candidate.scope.target } : {}) } : rule;
    const refs = bindingPolicyReferences(candidate);
    const own: ResolvedAlertCondition[] = [];
    const masked = new Set<string>();
    for (const ref of refs) {
      const policy = document.policies.find(item => item.id === ref.policy_id);
      for (const rule of policy?.conditions ?? []) {
        const compiledId = ref.policy_id + "." + rule.id; masked.add(compiledId);
        const adjustment = ref.adjustments?.[rule.id];
        // BE applies overrides after deriving defaults from the base condition.
        const defaults = { recover_threshold: rule.error_threshold ?? 0, recover_after_sec: rule.type === "counter_delta" ? 3 : 0 };
        if (ref.enabled !== false) own.push({ rule: scoped({ ...defaults, ...rule, ...(adjustment ?? {}) }), compiledId, policyId: ref.policy_id, binding: candidate, source: adjustment ? "individual_adjustment" : "shared" });
      }
    }
    for (const key of ["conditions", "additional_conditions"] as const) {
      for (const rule of candidate[key] ?? []) {
        const compiledId = bindingKey(candidate) + (key === "conditions" ? "." : ".additional.") + rule.id; masked.add(compiledId);
        own.push({ rule: scoped(rule), compiledId, binding: candidate, source: key === "conditions" ? "individual" : "additional" });
      }
    }
