}

export function bindingPolicyReferences(binding: AlertBinding): AlertPolicyReference[] {
  if (binding.mode === "composed") return binding.policy_refs ?? [];
  return binding.policy_id ? [{ policy_id: binding.policy_id, ...(binding.mode === "shared_with_adjustments" ? { adjustments: binding.adjustments ?? {} } : {}) }] : [];
}

