export function composedBinding(scope: AlertBindingScope, previous?: AlertBinding): AlertBinding {
  if (previous?.mode === "composed") return previous;
  if (!previous) return { scope, mode: "composed", inherit: true, policy_refs: [], conditions: [] };
  return { scope, mode: "composed", enabled: previous.mode !== "disabled", inherit: false,
    policy_refs: bindingPolicyReferences(previous), ...(previous.conditions ? { conditions: previous.conditions } : {}),
    ...(previous.additional_conditions ? { additional_conditions: previous.additional_conditions } : {}) };
}

export function directTargetBinding(document: AlertsDocument, targetId: string) {
