/** Pull library changes without dropping unsaved target branches or overwriting a concurrent edit. */
export function mergeAlertDraft(base: AlertsDocument, draft: AlertsDocument, latest: AlertsDocument): AlertsDocument {
  const same = (left: unknown, right: unknown) => JSON.stringify(left, sortedObject) === JSON.stringify(right, sortedObject);
  if (!same(base.policies, draft.policies)) throw new Error("Common policies were also edited in this draft. Save or reload before refreshing the library.");
  const original = new Map(base.bindings.map(binding => [bindingKey(binding), binding]));
  const local = new Map(draft.bindings.map(binding => [bindingKey(binding), binding]));
  const remote = new Map(latest.bindings.map(binding => [bindingKey(binding), binding]));
  for (const key of new Set([...original.keys(), ...local.keys()])) {
    if (same(original.get(key), local.get(key))) continue;
    if (!same(original.get(key), remote.get(key))) throw new Error("Alert settings for this target changed on the server. Reload settings before saving.");
    const binding = local.get(key);
    if (binding) remote.set(key, binding); else remote.delete(key);
  }
  return { ...latest, bindings: [...remote.values()] };
}
function sortedObject(_key: string, value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value) ? Object.fromEntries(Object.entries(value).sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0)) : value;
}
