.alerts-condition-table .alerts-condition-col-indicator { width: 7%; }
.alerts-condition-table .alerts-condition-col-metric { width: 13%; }
.alerts-condition-table .alerts-condition-col-type { width: 12%; }
.alerts-condition-table .alerts-condition-col-value { width: 7%; }
.alerts-condition-table .alerts-condition-col-timing { width: 10%; }
.alerts-condition-table .alerts-condition-col-severity { width: 7%; }
.alerts-condition-table .alerts-condition-col-delete { width: 2%; }
.alerts-condition-type-controls { display: flex; min-width: 0; align-items: center; gap: 4px; }
.alerts-condition-type-controls > select:first-child { flex: 1 1 auto; width: auto; min-width: 0; }
.alerts-condition-type-controls .alerts-condition-operator { flex: 0 0 42px; width: 42px; }
.alerts-condition-table .alerts-timing-picker-menu { width: 210px; }
.alerts-condition-table .alerts-timing-picker-menu input { width: 100%; }

/* Target policy branches edit only the target's references and conditions. */
.policy-tree-panel { container-type: inline-size; container-name: alert-policy; }
.policy-tree-layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-3); align-items: start; min-width: 0; }
.policy-tree-branches { display: grid; gap: var(--space-3); min-width: 0; }
.policy-tree-category { min-width: 0; }
.policy-tree-category > summary { font-weight: 700; margin-bottom: var(--space-2); cursor: pointer; }
.policy-tree-branch { min-width: 0; margin: var(--space-2) 0 var(--space-2) var(--space-3); padding: var(--space-2); border-left: 2px solid var(--line); }
.policy-tree-branch > summary { cursor: pointer; overflow-wrap: anywhere; }
.policy-tree-branch > summary > :is(label, small, button) { margin-inline-end: var(--space-2); }
.policy-tree-switch { display: inline-flex; align-items: center; gap: var(--space-2); color: var(--text); font-size: var(--font-size-sm); }
.policy-tree-switch input { margin: 0; }
.policy-tree-add { max-width: 480px; margin-block: var(--space-2); }
.policy-tree-manage { display: inline-block; margin: var(--space-2) 0; }
.policy-tree-condition-list { display: grid; gap: var(--space-2); list-style: none; margin: var(--space-2) 0; padding: 0; min-width: 0; }
.policy-tree-condition-list li { display: grid; gap: var(--space-1); padding-block: var(--space-2); border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
.policy-tree-condition-list small, .policy-tree-effective > p { color: var(--muted); font-size: var(--font-size-xs); }
.policy-tree-branch.is-disabled > summary, .policy-tree-condition-list .is-disabled { color: var(--muted); }
.policy-tree-effective { position: sticky; top: 0; order: -1; z-index: 1; max-height: 180px; overflow: auto; padding: var(--space-2); background: var(--surface-muted); border: 1px solid var(--line); border-radius: var(--radius-sm); }
.policy-tree-effective :is(h4, p) { margin: 0 0 var(--space-2); }
.policy-tree-condition .maintenance-table-wrap { max-width: 100%; overflow: auto; }
.policy-tree-condition .alerts-condition-table { min-width: 1640px; }
@container alert-policy (min-width: 950px) {
  .policy-tree-layout { grid-template-columns: minmax(0, 1fr) minmax(280px, .55fr); }
  .policy-tree-effective { order: 0; max-height: 340px; }
}
import type { AlertMetricDefinition, AlertRule } from "../types/api";
import { Icon } from "./ui/Icon";

const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertConditionTable({ title, rules, metrics, protocols, flowRoles, busy, onChange, lockedIdentity = false, hideActions = false }: { title: string; rules: AlertRule[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onChange: (rules: AlertRule[]) => void; lockedIdentity?: boolean; hideActions?: boolean }) {
  const update = (index: number, patch: Partial<AlertRule>) => onChange(rules.map((rule, ruleIndex) => ruleIndex === index ? { ...rule, ...patch } : rule));
  const remove = (index: number) => onChange(rules.filter((_, ruleIndex) => ruleIndex !== index));
  const add = () => onChange([...rules, newAlertCondition(undefined, flowRoles, rules)]);
  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table alerts-condition-table"><colgroup><col className="alerts-condition-col-enabled" /><col className="alerts-condition-col-id" /><col className="alerts-condition-col-target" /><col className="alerts-condition-col-protocol" /><col className="alerts-condition-col-roles" /><col className="alerts-condition-col-indicator" /><col className="alerts-condition-col-metric" /><col className="alerts-condition-col-type" /><col className="alerts-condition-col-value" /><col className="alerts-condition-col-value" /><col className="alerts-condition-col-timing" /><col className="alerts-condition-col-severity" /><col className="alerts-condition-col-delete" /></colgroup><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={hideActions ? index : rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={hideActions ? undefined : () => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && !hideActions && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
}

function ConditionRow({ rule, metrics, protocols, flowRoles, busy, lockedIdentity, onUpdate, onRemove }: { rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; lockedIdentity: boolean; onUpdate: (patch: Partial<AlertRule>) => void; onRemove?: () => void }) {
  const type = rule.type ?? "threshold";
  const target = rule.target ?? "flow";
  const roles = (rule.flow_roles ?? []).join(", ");
  const selectableMetrics = metrics.filter((metric) => isSelectableMetric(metric.key, target, rule.proto));
  const setType = (next: AlertRule["type"]) => {
    if (next === "availability") onUpdate({ type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 });
    else if (next === "counter_delta") onUpdate({ type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined });
    else onUpdate({ type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined });
  };
  const setProtocol = (proto: string) => {
    const patch: Partial<AlertRule> = { proto: proto || undefined };
    if (proto === "UDP" || proto === "TCP") {
      patch.flow_roles = undefined;
      if (type === "availability") Object.assign(patch, {
        type: "threshold", metric: "packet_count.window", operator: "==",
        error_threshold: 0, recover_threshold: 0, inactive_after_sec: undefined
      });
    }
    onUpdate(patch);
  };
  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => setProtocol(event.target.value)}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} data-tooltip-key={rule.proto ? "tooltip.availableRoles" : undefined} data-tooltip-roles={rule.proto ? (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><select value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><select value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })}>{!selectableMetrics.some((metric) => metric.key === rule.metric) && <option value={rule.metric}>Current: {rule.metric} (not available for this target)</option>}{selectableMetrics.map((metric) => <option key={metric.key} value={metric.key}>{metric.key}</option>)}</select></td><td><span className="alerts-condition-type-controls"><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option>{rule.proto !== "UDP" && rule.proto !== "TCP" && <option value="availability">Availability</option>}</select>{type !== "availability" && <select className="alerts-condition-operator" value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && onRemove && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" data-tooltip-key="tooltip.deleteCondition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  const type = rule.type ?? "threshold";
  if (type === "availability") return <span data-tooltip-key="tooltip.lastPacketEvaluated">Last packet</span>;
  const summary = [type === "threshold" ? "On " + seconds(rule.trigger_after_sec) : "", type === "threshold" ? "Off " + seconds(rule.recover_after_sec) : "", "Missing " + seconds(rule.missing_after_sec)].filter(Boolean).join(" · ");
  return <details className={"alerts-timing-picker" + (disabled ? " is-disabled" : "")}><summary title={summary} onClick={(event) => { if (disabled) event.preventDefault(); }}><span>{summary}</span></summary><div className="alerts-timing-picker-menu">{type === "threshold" && <label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label>}{type === "threshold" && <label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></div></details>;
}
function seconds(value: number | undefined) { return value === undefined ? "—" : value + "s"; }

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

export function newAlertCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = [], defaultFlowRoles?: string[]): AlertRule {
  const roles = defaultFlowRoles ?? (proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined);
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function isSelectableMetric(key: string, target: string, proto: string | undefined) {
  const interfaceMetric = key.startsWith("link.") || key.startsWith("rx.") || key.startsWith("tx.");
  if (target === "interface") return interfaceMetric;
  if (interfaceMetric) return false;
  const universal = key.startsWith("bitrate.") || key.startsWith("packet_rate.") || key.startsWith("packet_count.");
  const mediaCommon = universal || key.startsWith("interval.");
  if (!proto) return universal || key.startsWith("duration.");
  if (proto === "HLS") return key.startsWith("hls.preview.");
  if (proto === "UDP" || proto === "TCP") return universal || key === "duration.seconds";
  const transportShared = key.startsWith("jitter.") || key.startsWith("seq_stats.");
  if (proto === "SRT") return mediaCommon || transportShared || key.startsWith("bandwidth.") || key.startsWith("control_type_count.") || key.startsWith("nak_seqno.") || key.startsWith("packet_breakdown.") || key.startsWith("rate.") || key.startsWith("rcvrate.") || key.startsWith("rtt.") || key.startsWith("rttvar.");
  if (proto === "RTP" || proto === "RTMP") return mediaCommon || transportShared || key.startsWith("clock_skew.");
  return universal;
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
.stream-target-content p, .stream-target-content :is(h3, h4) { margin: 0; }
