import type { ButtonHTMLAttributes } from "react";
import { Icon, type IconName } from "./Icon";

type IconActionButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "aria-label"> & {
  icon: IconName;
  label: string;
};

/** A compact row action with the same visible hint and accessible name. */
export function IconActionButton({ icon, label, type = "button", className = "", ...props }: IconActionButtonProps) {
  return <button {...props} type={type} className={`icon-action-button icon-only ${className}`.trim()} aria-label={label} data-tooltip={label}>
    <Icon name={icon} size={16} />
  </button>;
}
