import { useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { bindingKey, bindingPolicyReferences, composedBinding, directTargetBinding, policyTitle, resolveAlertPolicy } from "../alertsPolicy";
import { useI18n } from "../i18n";
import type { AlertBinding, AlertMetricDefinition, AlertPolicyReference, AlertRule, AlertsDocument, MonitoringTargetDefinition } from "../types/api";
import { replaceBinding } from "../alertsPolicy";
import { conditionBaseValues } from "./alertConditionEditing";
import { AlertConditionEditor } from "./AlertConditionEditor";
import { IconActionButton } from "./ui/IconActionButton";
import { Icon } from "./ui/Icon";
import { newAlertCondition } from "./AlertConditionTable";

export function TargetAlertPolicyPanel({ target, document, metrics, protocols, flowRoles, busy, onDocument, onReloadPolicies }: { target: MonitoringTargetDefinition; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onDocument: (document: AlertsDocument) => void; onReloadPolicies?: () => void }) {
  const { t } = useI18n();
  const [message, setMessage] = useState("");
  const [view, setView] = useState<"settings" | "effective">("settings");
  const [expanded, setExpanded] = useState<Record<string, boolean>>({ defaults: true, common: true, specific: true });
  const panel = useRef<HTMLElement>(null);
  const tabs = useRef<HTMLDivElement>(null);
  const commonSelect = useRef<HTMLSelectElement>(null);
  const tabButtons = useRef<Array<HTMLButtonElement | null>>([]);
  const scrollMemory = useRef<Partial<Record<typeof view, { host: HTMLElement; top: number; left: number; anchor: number }>>>({});
  const previousView = useRef(view);
  const invalidFocusPending = useRef(false);
  const id = useId();
  const selectView = (next: typeof view) => {
    if (next === view) return;
    const host = scrollHost(panel.current);
    if (host) scrollMemory.current[view] = { host, top: host.scrollTop, left: host.scrollLeft, anchor: panelPosition(panel.current, host) };
    setView(next);
  };
  useLayoutEffect(() => {
    if (previousView.current === view) return;
    previousView.current = view;
    const saved = scrollMemory.current[view];
    if (saved?.host.isConnected) { saved.host.scrollTop = saved.top + panelPosition(panel.current, saved.host) - saved.anchor; saved.host.scrollLeft = saved.left; }
    else {
      const host = scrollHost(panel.current);
      if (host && tabs.current) host.scrollTop += tabs.current.getBoundingClientRect().top - host.getBoundingClientRect().top;
    }
  }, [view]);
  const toggle = (key: string) => setExpanded(current => ({ ...current, [key]: !current[key] }));
  const direct = directTargetBinding(document, target.id);
  const scope = { kind: "managed_target" as const, target_id: target.id, target_type: target.target_type };
  const draft = composedBinding(scope, direct);
  const context = { target: "flow" as const, proto: target.proto, monitoringTargetIds: [target.id], monitoringGroupIds: target.groupIds };
  const effective = resolveAlertPolicy(document, context);
  const parentDocument = { ...document, bindings: document.bindings.filter(binding => bindingKey(binding) !== bindingKey({ scope, mode: "disabled" })) };
  const inherited = resolveAlertPolicy(parentDocument, context);
  const refs = draft.policy_refs ?? [];
  const own = [...(draft.conditions ?? []), ...(draft.additional_conditions ?? [])];
  const active = draft.enabled !== false;
  const update = (patch: Partial<AlertBinding>) => { setMessage(""); onDocument(replaceBinding(document, { ...draft, ...patch })); };
  const updateRef = (id: string, patch: Partial<AlertPolicyReference>) => update({ policy_refs: refs.map(ref => ref.policy_id === id ? { ...ref, ...patch } : ref) });
  const inheritedPolicyIds = new Set(draft.inherit ? inherited.conditions.map(item => item.policyId).filter(Boolean) : []);
  const available = document.policies.filter(policy => !refs.some(ref => ref.policy_id === policy.id) && !inheritedPolicyIds.has(policy.id) && (!policy.conditions.length || policy.conditions.some(rule => !rule.proto || rule.proto === target.proto)));
  const updateOwn = (key: "conditions" | "additional_conditions", index: number, rule?: AlertRule) => update({ [key]: (draft[key] ?? []).flatMap((current, currentIndex) => currentIndex !== index ? [current] : rule ? [rule] : []) });
  const sourceTitle = (item: (typeof effective.conditions)[number]) => {
    const origin = item.binding.scope.kind === "protocol" ? t("policyTree.protocolDefault", { name: item.binding.scope.proto ?? "*" })
      : item.binding.scope.target_id !== target.id ? t("policyTree.groupDefault", { name: item.binding.scope.target_id }) : t(item.policyId ? "policyTree.common" : "policyTree.specific");
    const title = item.policyId ? origin + " → " + policyTitle(document, item.policyId) : origin;
    return item.source === "individual_adjustment" ? title + " · " + t("policyTree.existingAdjustments") : title;
  };
  const applicable = effective.conditions.filter(({ rule }) => rule.enabled !== false && (!rule.proto || rule.proto === target.proto) && rule.target !== "interface" && (!rule.flow_roles?.length || !target.flowRoles?.length || rule.flow_roles.some(role => target.flowRoles!.includes(role))));
  const legacy = refs.filter(ref => ref.adjustments !== undefined);
  const node = (key: string, title: string, children: ReactNode, options: { className?: string; check?: ReactNode; count?: number; actions?: ReactNode } = {}) =>
    <PolicyTreeNode nodeKey={key} title={title} open={Boolean(expanded[key])} onToggle={() => toggle(key)} {...options}>{children}</PolicyTreeNode>;
  const addButton = (label: string, action: () => void, disabled = false) => <IconActionButton icon="add" label={label} className="maintenance-secondary-button policy-tree-action" disabled={busy || !active || disabled} onClick={action} />;
  const removeButton = (action: () => void) => <IconActionButton icon="delete" label={t("policyTree.remove")} className="maintenance-secondary-button policy-tree-action" disabled={busy || !active} onClick={action} />;
  const check = (label: string, checked: boolean, onChange: (checked: boolean) => void, disabled = false) => <label className="policy-tree-check"><input type="checkbox" aria-label={label} checked={checked} disabled={busy || disabled} onChange={event => onChange(event.target.checked)} /></label>;
  return <section ref={panel} className="protocol-map-alert-policy policy-tree-panel" onInvalidCapture={event => {
    if (view === "settings") return;
    event.preventDefault();
    if (invalidFocusPending.current) return;
    invalidFocusPending.current = true;
    const field = event.target as HTMLInputElement;
    selectView("settings");
    requestAnimationFrame(() => { invalidFocusPending.current = false; if (field.isConnected) { field.focus(); field.reportValidity(); } });
  }}>
    <header><div><h3>{target.title || target.id}</h3><p>{target.id} · {target.proto} · {target.target_type}</p></div>
      <label className="policy-tree-switch"><input type="checkbox" aria-label={t("policyTree.evaluation")} checked={active} disabled={busy} onChange={event => update({ enabled: event.target.checked })} />{t("policyTree.evaluation")}</label>
    </header>
    <div ref={tabs} className="policy-tree-tabs maintenance-tabs" role="tablist" aria-label={t("policyTree.views")} onKeyDown={event => {
      if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
      event.preventDefault(); event.stopPropagation();
      const next = event.key === "Home" ? 0 : event.key === "End" ? 1 : view === "settings" ? 1 : 0;
      selectView(next === 0 ? "settings" : "effective"); tabButtons.current[next]?.focus();
    }}>
      {(["settings", "effective"] as const).map((key, index) => <button key={key} ref={element => { tabButtons.current[index] = element; }} type="button" id={id + "-tab-" + key} className={"maintenance-tab" + (view === key ? " is-active" : "")} role="tab" aria-selected={view === key} aria-controls={id + "-panel-" + key} tabIndex={view === key ? 0 : -1} onClick={() => selectView(key)}>{t(key === "settings" ? "policyTree.settingsTab" : "policyTree.effectiveTab")}{key === "effective" && <span className="policy-tree-count">{applicable.length}</span>}</button>)}
    </div>
    {message && <p role="alert">{message}</p>}
    <div id={id + "-panel-settings"} role="tabpanel" aria-labelledby={id + "-tab-settings"} className="policy-tree-tab-panel" hidden={view !== "settings"}>
      <p className="policy-tree-hint">{t("policyTree.hint")}</p>
      <div className="policy-tree-branches">
        {node("defaults", t("policyTree.defaults"), <div className="policy-tree-children">
          {draft.inherit ? node("inherited", (inherited.binding ? (inherited.binding.scope.kind === "protocol" ? t("policyTree.protocolDefault", { name: inherited.binding.scope.proto ?? "*" }) : t("policyTree.groupDefault", { name: inherited.binding.scope.target_id })) : t("policyTree.noDefault")) + " " + (inherited.binding ? bindingPolicyReferences(inherited.binding).map(ref => policyTitle(document, ref.policy_id)).join(", ") : ""),
            <div className="policy-tree-detail"><AlertConditionSummary rules={inherited.conditions.map(item => item.rule)} sources={inherited.conditions.map(sourceTitle)} /></div>,
            { className: "policy-tree-inherited", count: inherited.conditions.filter(item => item.rule.enabled !== false).length }) : <p className="policy-tree-empty">{t("policyTree.inheritOff")}</p>}
        </div>, { className: "policy-tree-category", check: check(t("policyTree.inherit"), Boolean(draft.inherit), inherit => update({ inherit })) })}
        {node("common", t("policyTree.common"), <>
          <div className="policy-tree-tools"><label className="policy-condition-field policy-tree-add">{t("policyTree.addPolicy")}<select ref={commonSelect} aria-label={t("policyTree.addPolicy")} disabled={busy || !active || !available.length} value="" onChange={event => {
            const key = event.target.value; if (!key) return;
            setExpanded(current => ({ ...current, ["policy:" + key]: true }));
            update({ policy_refs: [...refs, { policy_id: key }] });
          }}><option value="">{t(available.length ? "policyTree.choosePolicy" : "policyTree.noPolicies")}</option>{available.map(policy => <option key={policy.id} value={policy.id}>{policy.title || policy.id} · {policy.conditions.length} {t("policyTree.conditions")}</option>)}</select></label></div>
          <div className="policy-tree-children">{refs.map(ref => {
            const policy = document.policies.find(policy => policy.id === ref.policy_id), title = policy?.title || ref.policy_id;
            return <div key={ref.policy_id}>{node("policy:" + ref.policy_id, title,
              <div className="policy-tree-detail"><p className="policy-tree-hint">{t("policyTree.readOnly")}</p>{policy ? <AlertConditionSummary rules={policy.conditions} source={title} /> : <p role="alert">{t("policyTree.missingPolicy")}</p>}</div>,
              { className: "policy-tree-branch" + (ref.enabled === false ? " is-disabled" : ""), count: policy?.conditions.length ?? 0,
                check: check(t("policyTree.enablePolicy", { name: title }), ref.enabled !== false, enabled => updateRef(ref.policy_id, { enabled }), !active),
                actions: removeButton(() => update({ policy_refs: refs.filter(item => item.policy_id !== ref.policy_id) })) })}</div>;
          })}</div>
          <div className="policy-tree-tools policy-tree-library-actions">{onReloadPolicies && <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onReloadPolicies}>{t("policyTree.refreshLibrary")}</button>}<a className="policy-tree-manage" href="/?tab=alerts" target="_blank" rel="noopener noreferrer">{t("policyTree.manage")}</a></div>
        </>, { className: "policy-tree-category", count: refs.length, actions: addButton(t("policyTree.addPolicy"), () => { setExpanded(current => ({ ...current, common: true })); requestAnimationFrame(() => commonSelect.current?.focus()); }, !available.length) })}
        {node("specific", t("policyTree.specific"), <div className="policy-tree-children">
          {legacy.map(ref => {
            const policy = document.policies.find(policy => policy.id === ref.policy_id);
            return <div key={ref.policy_id}>{node("adjustment:" + ref.policy_id, (policy?.title || ref.policy_id) + " · " + t("policyTree.existingAdjustments"),
              <div className="policy-tree-detail policy-tree-legacy-adjustments">{(policy?.conditions ?? []).map(base => <div className="policy-tree-adjustment" key={base.id}><h4>{base.id}</h4><AlertConditionEditor rule={{ ...conditionBaseValues(base), ...(ref.adjustments?.[base.id] ?? {}) }} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy || !active || ref.enabled === false} lockedIdentity onChange={next => {
                const fields: Array<keyof AlertRule> = ["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"];
                const baseValues = conditionBaseValues(base), currentValues = { ...baseValues, ...ref.adjustments?.[base.id] };
                const patch = { ...ref.adjustments?.[base.id] };
                for (const key of fields) {
                  if (next[key] === currentValues[key]) continue;
                  if (next[key] === undefined || next[key] === baseValues[key]) delete patch[key];
                  else Object.assign(patch, { [key]: next[key] });
                }
                const adjustments = { ...ref.adjustments }; if (Object.keys(patch).length) adjustments[base.id] = patch; else delete adjustments[base.id];
                updateRef(ref.policy_id, { adjustments });
              }} /></div>)}</div>, { className: "policy-tree-legacy-node", count: policy?.conditions.length ?? 0 })}</div>;
          })}
          {(["conditions", "additional_conditions"] as const).flatMap(key => (draft[key] ?? []).map((rule, index) => <div key={key + ":" + index}>{node("condition:" + key + ":" + index, rule.id + " · " + rule.metric,
            <div className="policy-tree-detail"><AlertConditionEditor rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy || !active || rule.enabled === false} onChange={next => {
              if (own.some(item => item !== rule && item.id === next.id)) { setMessage(t("policyTree.duplicateCondition")); return; }
              updateOwn(key, index, next);
            }} /></div>, { className: "policy-tree-branch policy-tree-condition" + (rule.enabled === false ? " is-disabled" : ""),
              check: check(t("policyTree.enableCondition", { name: rule.id }), rule.enabled !== false, enabled => updateOwn(key, index, { ...rule, enabled }), !active),
              actions: removeButton(() => updateOwn(key, index)) })}</div>))}
          {!own.length && !legacy.length && <p className="policy-tree-empty">{t("policyTree.noOwn")}</p>}
        </div>, { className: "policy-tree-category", count: own.length + legacy.length, actions: addButton(t("policyTree.addCondition"), () => {
          const index = (draft.conditions ?? []).length;
          setExpanded(current => ({ ...current, specific: true, ["condition:conditions:" + index]: true }));
          update({ conditions: [...(draft.conditions ?? []), newAlertCondition(target.proto, flowRoles, own, target.flowRoles)] });
        }) })}
      </div>
    </div>
    <div id={id + "-panel-effective"} role="tabpanel" aria-labelledby={id + "-tab-effective"} className="policy-tree-tab-panel" hidden={view !== "effective"}>
      <section className="policy-tree-effective" aria-label={t("policyTree.effective")} aria-live="polite"><h4>{t("policyTree.effective")} · {applicable.length}</h4><p className="policy-tree-hint">{t("policyTree.draft")}</p>
        {!applicable.length ? <p>{t(active ? "policyTree.none" : "policyTree.disabled")}</p> : <AlertConditionSummary rules={applicable.map(item => item.rule)} sources={applicable.map(sourceTitle)} />}
      </section>
    </div>
  </section>;
}

function PolicyTreeNode({ nodeKey, title, open, onToggle, className = "", check, count, actions, children }: {
  nodeKey: string; title: string; open: boolean; onToggle: () => void; className?: string;
  check?: ReactNode; count?: number; actions?: ReactNode; children: ReactNode;
}) {
  const id = useId(), { t } = useI18n();
  return <div className={"policy-tree-node " + className} data-policy-node={nodeKey}>
    <div className="policy-tree-row">
      <button type="button" className={"policy-tree-toggle" + (open ? " is-open" : "")} aria-label={t(open ? "policyTree.collapse" : "policyTree.expand", { name: title })} aria-expanded={open} aria-controls={id} onClick={onToggle}><Icon name="expand" size={15} /></button>
      {check ?? <span className="policy-tree-check-spacer" aria-hidden="true" />}
      <button type="button" className="policy-tree-title" title={title} aria-expanded={open} aria-controls={id} onClick={onToggle}>{title}</button>
      {count !== undefined ? <span className="policy-tree-count">{count}</span> : <span />}
      <span className="policy-tree-row-actions">{actions}</span>
    </div>
    <div id={id} className="policy-tree-node-body" hidden={!open}>{children}</div>
  </div>;
}

function panelPosition(panel: HTMLElement | null, host: HTMLElement): number {
  return (panel?.getBoundingClientRect().top ?? 0) - (host === document.scrollingElement ? 0 : host.getBoundingClientRect().top) + host.scrollTop;
}

function scrollHost(element: HTMLElement | null): HTMLElement | null {
  for (let current = element?.parentElement; current; current = current.parentElement) {
    if (/(auto|scroll)/.test(getComputedStyle(current).overflowY) && current.scrollHeight > current.clientHeight + 1) return current;
  }
  return document.scrollingElement as HTMLElement | null;
}

export function AlertConditionSummary({ rules, source, sources }: { rules: AlertRule[]; source?: string; sources?: string[] }) {
  const { t } = useI18n();
  return <ul className="policy-tree-condition-list">{rules.map((rule, index) => <li key={index} className={rule.enabled === false ? "is-disabled" : ""}>
    <strong>{rule.id}</strong><small>{sources?.[index] ?? source} · {rule.proto || "*"} · {rule.target ?? "any"} {rule.flow_roles?.join(", ")} · {rule.enabled === false ? t("policyTree.conditionOff") : rule.severity ?? "warning"}</small>
    <span>{rule.metric} · {rule.type === "availability" ? `${t("policyTree.inactive")} ${rule.inactive_after_sec}s` : `${rule.operator ?? ">"} ${rule.type === "counter_delta" ? rule.delta_threshold ?? 0 : rule.error_threshold ?? 0}`}</span>
    <small>{t("policyTree.recovery")}: {rule.type === "counter_delta" ? `${rule.recover_after_sec ?? 3}s` : rule.type === "availability" ? t("policyTree.packetReceived") : rule.recover_threshold ?? rule.error_threshold ?? 0} · {t("policyTree.timing")}: {rule.trigger_after_sec ?? 0}s / {rule.recover_after_sec ?? (rule.type === "counter_delta" ? 3 : 0)}s · {t("policyTree.missing")}: {rule.missing_after_sec ?? 0}s</small>
  </li>)}</ul>;
}

export function targetPolicyModeLabel(mode: "inherit" | AlertBinding["mode"]) { return mode === "inherit" ? "Inherited default" : mode === "disabled" ? "Alert evaluation disabled" : mode === "composed" ? "Target conditions" : mode === "shared" ? "Common policy" : mode === "individual" ? "Target-specific policy" : "Common policy + adjustments"; }

