function PolicyTreeNode({ nodeKey, title, open, onToggle, className = "", check, count, actions, children }: {
  nodeKey: string; title: string; open: boolean; onToggle: () => void; className?: string;
  check?: ReactNode; count?: number; actions?: ReactNode; children: ReactNode;
}) {
  const id = useId(), { t } = useI18n();
  return <div className={"policy-tree-node " + className} data-policy-node={nodeKey}>
    <div className="policy-tree-row">
      <button type="button" className={"policy-tree-toggle" + (open ? " is-open" : "")} aria-label={t(open ? "policyTree.collapse" : "policyTree.expand", { name: title })} aria-expanded={open} aria-controls={id} onClick={onToggle}><Icon name="expand" size={15} /></button>
      {check ?? <span className="policy-tree-check-spacer" aria-hidden="true" />}
      <button type="button" className="policy-tree-title" title={title} aria-expanded={open} aria-controls={id} onClick={onToggle}>{title}</button>
      {count !== undefined ? <span className="policy-tree-count">{count}</span> : <span />}
      <span className="policy-tree-row-actions">{actions}</span>
    </div>
    <div id={id} className="policy-tree-node-body" hidden={!open}>{children}</div>
  </div>;
}

function panelPosition(panel: HTMLElement | null, host: HTMLElement): number {
  return (panel?.getBoundingClientRect().top ?? 0) - (host === document.scrollingElement ? 0 : host.getBoundingClientRect().top) + host.scrollTop;
}

function scrollHost(element: HTMLElement | null): HTMLElement | null {
  for (let current = element?.parentElement; current; current = current.parentElement) {
    if (/(auto|scroll)/.test(getComputedStyle(current).overflowY) && current.scrollHeight > current.clientHeight + 1) return current;
  }
  return document.scrollingElement as HTMLElement | null;
}

import type { ReactNode } from "react";
import { useI18n } from "../i18n";
import type { AlertMetricDefinition, AlertRule } from "../types/api";
import { conditionProtocolPatch, conditionTypePatch, isSelectableMetric } from "./alertConditionEditing";

/** One target condition, using the same field semantics as the shared-policy table. */
export function AlertConditionEditor({ rule, metrics, protocols, flowRoles, busy, lockedIdentity = false, onChange }: {
  rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>;
  busy: boolean; lockedIdentity?: boolean; onChange: (rule: AlertRule) => void;
}) {
  const { t } = useI18n();
  const type = rule.type ?? "threshold", target = rule.target ?? "any";
  const change = (patch: Partial<AlertRule>) => onChange({ ...rule, ...patch });
  const candidates = metrics.filter(metric => isSelectableMetric(metric.key, target, rule.proto));
  const field = (key: string, content: ReactNode) => <label className="policy-condition-field">{t("conditionEditor." + key)}{content}</label>;
  const number = (key: keyof AlertRule, label: string, fallback?: number, min?: number) => field(label,
    <input type="number" step="any" min={min} data-condition-field={key} value={rule[key] as number | undefined ?? fallback ?? ""} disabled={busy}
      onChange={event => change({ [key]: event.target.value === "" ? undefined : Number(event.target.value) })} />);
  return <div className="policy-condition-editor" role="group" aria-label={t("policyTree.editCondition")}>
    <div className="policy-condition-fields">
      {lockedIdentity && field("enabled", <input type="checkbox" checked={rule.enabled !== false} disabled={busy} onChange={event => change({ enabled: event.target.checked })} />)}
      {field("metric", <select data-condition-field="metric" value={rule.metric} disabled={busy || lockedIdentity} onChange={event => change({ metric: event.target.value })}>
        {!candidates.some(metric => metric.key === rule.metric) && <option value={rule.metric}>{rule.metric} · {t("conditionEditor.unavailable")}</option>}
        {candidates.map(metric => <option key={metric.key} value={metric.key}>{metric.key}{metric.unit ? " (" + metric.unit + ")" : ""}</option>)}
      </select>)}
      {field("type", <select data-condition-field="type" value={type} disabled={busy || lockedIdentity} onChange={event => change(conditionTypePatch(rule, event.target.value as AlertRule["type"]))}>
        <option value="threshold">{t("conditionEditor.threshold")}</option><option value="counter_delta">{t("conditionEditor.counterDelta")}</option>
        {(type === "availability" || rule.proto !== "UDP" && rule.proto !== "TCP") && <option value="availability">{t("conditionEditor.availability")}</option>}
      </select>)}
      {type !== "availability" && field("operator", <select data-condition-field="operator" value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={event => change({ operator: event.target.value as AlertRule["operator"] })}>{[">", ">=", "<", "<=", "==", "!="].map(operator => <option key={operator}>{operator}</option>)}</select>)}
      {type === "availability" ? number("inactive_after_sec", "inactive", undefined, 0)
        : number(type === "counter_delta" ? "delta_threshold" : "error_threshold", "trigger")}
      {type === "threshold" && <>
        {number("recover_threshold", "recovery", rule.error_threshold)}
        {number("trigger_after_sec", "triggerDelay", 0, 0)}
      </>}
      {type !== "availability" && <>
        {number("recover_after_sec", "recoveryDelay", type === "counter_delta" ? 3 : 0, 0)}
        {number("missing_after_sec", "missing", 0, 0)}
      </>}
      {field("severity", <select data-condition-field="severity" value={rule.severity ?? "warning"} disabled={busy} onChange={event => change({ severity: event.target.value })}>{["info", "warning", "error", "critical"].map(severity => <option key={severity}>{severity}</option>)}</select>)}
    </div>
    <details className="policy-condition-advanced">
      <summary>{t("conditionEditor.advanced")}</summary>
      <div className="policy-condition-fields">
        {field("id", <input data-condition-field="id" value={rule.id} disabled={busy || lockedIdentity} onChange={event => change({ id: event.target.value })} />)}
        {field("target", <select data-condition-field="target" value={target} disabled={busy || lockedIdentity} onChange={event => change({ target: event.target.value as AlertRule["target"], ...(event.target.value !== "flow" ? { flow_roles: undefined } : {}) })}>{["flow", "stream", "interface", "any"].map(value => <option key={value}>{value}</option>)}</select>)}
        {field("protocol", <select data-condition-field="proto" value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={event => change(conditionProtocolPatch(rule, event.target.value))}><option value="">{t("streamTarget.any")}</option>{protocols.map(proto => <option key={proto}>{proto}</option>)}</select>)}
        {field("roles", <input data-condition-field="flow_roles" value={(rule.flow_roles ?? []).join(", ")} disabled={busy || lockedIdentity || target !== "flow"} placeholder={(flowRoles[rule.proto ?? ""] ?? []).join(", ")} onChange={event => change({ flow_roles: event.target.value.split(",").map(value => value.trim()).filter(Boolean) })} />)}
        {field("indicator", <select data-condition-field="indicator_category" value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={event => change({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">{t("conditionEditor.other")}</option><option value="quality">{t("conditionEditor.quality")}</option></select>)}
      </div>
    </details>
  </div>;
}
"}}}

