  const applicable = effective.conditions.filter(({ rule }) => rule.enabled !== false && (!rule.proto || rule.proto === target.proto) && rule.target !== "interface" && (!rule.flow_roles?.length || !target.flowRoles?.length || rule.flow_roles.some(role => target.flowRoles!.includes(role))));
