type SearchInputProps = {
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  label: string;
  className?: string;
  maxLength?: number;
};

export function SearchInput({ value, onChange, placeholder, label, className = "", maxLength }: SearchInputProps) {
  return (
    <label className={`search-input ${className}`.trim()}>
      <Icon name="search" size={16} />
      <input value={value} maxLength={maxLength} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} aria-label={label} data-tooltip={placeholder} />
      {value && (
        <button type="button" className="search-clear" onClick={() => onChange("")} aria-label={`Clear ${label}`} data-tooltip-key="tooltip.clear" data-tooltip-label={label}>
          <Icon name="close" size={14} />
        </button>
      )}
    </label>
  );
}
