item.aggregated_output:
.alerts-condition-table .alerts-condition-col-delete { width: 2%; }
.alerts-condition-type-controls { display: flex; min-width: 0; align-items: center; gap: 4px; }
.alerts-condition-type-controls > select:first-child { flex: 1 1 auto; width: auto; min-width: 0; }
.alerts-condition-type-controls .alerts-condition-operator { flex: 0 0 42px; width: 42px; }
.alerts-condition-table .alerts-timing-picker-menu { width: 210px; }
.alerts-condition-table .alerts-timing-picker-menu input { width: 100%; }

/* Target policy views share the full width and keep tree controls separate. */
.policy-tree-panel { --policy-tree-indent: 24px; --policy-tree-joint: 14px; container-type: inline-size; container-name: alert-policy; }
.policy-tree-tabs.maintenance-tabs { position: sticky; top: 0; z-index: 2; align-self: start; display: flex; flex-wrap: nowrap; gap: var(--space-1); min-width: 0; margin: 0; padding: var(--space-1) 0; border-bottom: 1px solid var(--line); background: var(--surface); }
.policy-tree-tabs .maintenance-tab { min-width: 0; white-space: normal; }
.policy-tree-tab-panel { min-width: 0; }
.policy-tree-tab-panel[hidden], .policy-tree-node-body[hidden] { display: none; }
.policy-tree-hint { color: var(--muted); font-size: var(--font-size-xs); line-height: 1.5; }
.policy-tree-tab-panel > .policy-tree-hint { margin-bottom: var(--space-2); }
.policy-tree-branches { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius-sm); overflow: clip; }
.policy-tree-node { position: relative; min-width: 0; }
.policy-tree-category + .policy-tree-category { border-top: 1px solid var(--line-strong); }
.policy-tree-row { display: grid; grid-template-columns: 20px 20px minmax(0, 1fr) auto auto; align-items: center; gap: var(--space-1); min-height: 34px; padding: 2px var(--space-1); border-bottom: 1px solid var(--line); }
.policy-tree-category > .policy-tree-row { background: var(--surface-muted); }
.policy-tree-category > .policy-tree-row > .policy-tree-title { font-weight: 700; }
.policy-tree-row:hover { background: var(--accent-soft); }
.policy-tree-panel .policy-tree-toggle, .policy-tree-panel .policy-tree-title { min-width: 0; margin: 0; padding: 0; border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--text); font: inherit; box-shadow: none; cursor: pointer; }
.policy-tree-panel .policy-tree-toggle { display: grid; place-items: center; width: 20px; height: 24px; min-height: 0; color: var(--muted); }
.policy-tree-toggle > svg { transition: transform 120ms; }
.policy-tree-toggle.is-open > svg { transform: rotate(90deg); }
.policy-tree-panel .policy-tree-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: start; }
.policy-tree-row-actions { display: flex; align-items: center; gap: var(--space-1); }
.policy-tree-panel .policy-tree-action { display: grid; place-items: center; width: 26px; min-width: 26px; min-height: 26px; margin: 0; padding: 0; }
.policy-tree-count, .policy-tree-tabs .policy-tree-count { display: inline-flex; align-items: center; justify-content: center; min-height: 18px; padding: 0 5px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-muted); color: var(--muted); font-size: var(--font-size-xs); font-weight: 600; font-variant-numeric: tabular-nums; }
.policy-tree-switch, .policy-tree-check { display: inline-flex; align-items: center; min-height: 28px; gap: var(--space-2); margin: 0; color: var(--text); font-size: var(--font-size-sm); cursor: pointer; }
.policy-tree-check { justify-content: center; width: 20px; }
.protocol-map-alert-policy.policy-tree-panel input[type="checkbox"] { box-sizing: border-box; appearance: auto; accent-color: var(--accent); flex: 0 0 14px; width: 14px; height: 14px; min-width: 14px; min-height: 14px; max-width: 14px; max-height: 14px; margin: 0; padding: 0; border: initial; border-radius: initial; background: initial; }
.policy-tree-check-spacer { width: 20px; }
.policy-tree-children { min-width: 0; margin-inline-start: var(--policy-tree-joint); padding-inline-start: calc(var(--policy-tree-indent) - var(--policy-tree-joint) - 1px); border-inline-start: 1px solid var(--line-strong); }
.policy-tree-children .policy-tree-node::before { content: ""; position: absolute; inset-inline-start: calc(var(--policy-tree-joint) - var(--policy-tree-indent)); top: 17px; width: calc(var(--policy-tree-indent) - var(--policy-tree-joint) + 4px); border-top: 1px solid var(--line-strong); pointer-events: none; }
.policy-tree-tools { display: grid; gap: var(--space-2); margin: var(--space-2) var(--space-2) var(--space-2) var(--policy-tree-indent); min-width: 0; }
.policy-tree-library-actions { display: flex; flex-wrap: wrap; align-items: center; }
.policy-tree-add { width: 100%; max-width: 480px; }
.policy-tree-detail { min-width: 0; margin: var(--space-2) var(--space-2) var(--space-2) var(--policy-tree-indent); padding: var(--space-3); border: 1px solid var(--line); border-inline-start: 2px solid var(--line-strong); border-radius: var(--radius-sm); background: var(--surface); }
.policy-tree-empty { padding: var(--space-2); color: var(--muted); font-size: var(--font-size-xs); }
.policy-tree-branch.is-disabled > .policy-tree-row > .policy-tree-title, .policy-tree-condition-list .is-disabled { color: var(--muted); }
.policy-tree-condition-list { display: grid; gap: var(--space-2); list-style: none; margin: var(--space-2) 0; padding: 0; min-width: 0; }
.policy-tree-panel .policy-tree-condition-list { padding: 0; }
.policy-tree-condition-list li { display: grid; gap: var(--space-1); padding-block: var(--space-2); border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
.policy-tree-condition-list small { color: var(--muted); font-size: var(--font-size-xs); }
.policy-tree-effective { min-width: 0; padding: var(--space-3); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); }
.policy-tree-effective :is(h4, p) { margin: 0 0 var(--space-2); }
.policy-condition-editor { display: grid; gap: var(--space-3); min-width: 0; }
.policy-condition-fields { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-3); min-width: 0; }
.policy-condition-field { display: grid; align-content: start; gap: var(--space-1); min-width: 0; margin: 0; color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.policy-condition-field > :is(input:not([type="checkbox"]), select) { box-sizing: border-box; width: 100%; min-width: 0; max-width: 100%; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
.policy-condition-advanced { min-width: 0; border-top: 1px solid var(--line); padding-top: var(--space-2); }
.policy-condition-advanced > summary { cursor: pointer; color: var(--muted); font-size: var(--font-size-xs); }
.policy-condition-advanced > .policy-condition-fields { margin-top: var(--space-2); }
.policy-tree-adjustment + .policy-tree-adjustment { margin-top: var(--space-3); padding-top: var(--space-3); border-top: 1px solid var(--line-strong); }
.policy-tree-adjustment > h4 { margin-bottom: var(--space-2); overflow-wrap: anywhere; }
.policy-tree-panel :is(button, input, select, summary):focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
@container alert-policy (min-width: 600px) { .policy-condition-fields { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@container alert-policy (min-width: 1000px) { .policy-condition-fields { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@container alert-policy (max-width: 500px) { .policy-tree-node-body { --policy-tree-indent: 16px; } .policy-tree-detail { padding: var(--space-2); } }
@media (prefers-reduced-motion: reduce) { .policy-tree-toggle > svg { transition: none; } }

/* Streams-style guides run through the disclosure column, without horizontal elbows. */
.policy-tree-branches { overflow: visible; }
.policy-tree-row { display: flex; gap: 4px; padding: 3px 4px; }
.policy-tree-row > .policy-tree-toggle { flex: 0 0 20px; align-self: start; margin-top: 2px; position: relative; z-index: 2; }
.policy-tree-row > .policy-tree-check { flex: 0 0 20px; }
.policy-tree-row > .policy-tree-title { flex: 1 1 auto; }
.policy-tree-row > :is(.policy-tree-count, .policy-tree-readonly, .policy-tree-row-actions) { flex: 0 0 auto; }
.policy-tree-node::before, .policy-tree-node::after { content: ""; position: absolute; left: 14px; width: 1px; background: color-mix(in srgb, var(--muted) 38%, transparent); pointer-events: none; z-index: 1; }
