import { useLayoutEffect, useRef, useState, type ReactNode, type RefObject } from "react";
import { createPortal } from "react-dom";

/** A row-anchored popup outside the dock's scroll and clipping containers. */
export function PolicyTreePopup({ anchor, label, onClose, children }: {
  anchor: RefObject<HTMLElement>; label: string; onClose: () => void; children: ReactNode;
}) {
  const popup = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ top: 0, left: 8, maxHeight: 320 });
  const close = useRef(onClose);
  close.current = onClose;
  useLayoutEffect(() => {
    const trigger = anchor.current?.querySelector("button");
    const content = popup.current;
    const rect = anchor.current?.getBoundingClientRect();
    if (!rect) return;
    const width = Math.min(340, window.innerWidth - 16);
    const below = window.innerHeight - rect.bottom - 12;
    const above = rect.top - 12;
    const upward = below < 200 && above > below;
    const maxHeight = Math.max(100, Math.min(360, upward ? above : below));
    const height = Math.min(popup.current?.scrollHeight ?? 320, maxHeight);
    setPosition({ left: Math.max(8, Math.min(rect.right - width, window.innerWidth - width - 8)), top: upward ? rect.top - height - 4 : rect.bottom + 4, maxHeight });
    popup.current?.querySelector<HTMLElement>("input,button,a")?.focus();
    const pointer = (event: PointerEvent) => {
      if (!popup.current?.contains(event.target as Node) && !anchor.current?.contains(event.target as Node)) close.current();
    };
    const viewport = (event: Event) => { if (!popup.current?.contains(event.target as Node)) close.current(); };
    document.addEventListener("pointerdown", pointer);
    window.addEventListener("resize", viewport);
    window.addEventListener("scroll", viewport, true);
    return () => {
      document.removeEventListener("pointerdown", pointer);
      window.removeEventListener("resize", viewport);
      window.removeEventListener("scroll", viewport, true);
      if (document.activeElement === document.body || content?.contains(document.activeElement)) trigger?.focus({ preventScroll: true });
    };
  }, [anchor]);
  return createPortal(<div ref={popup} role="dialog" aria-label={label} className="policy-tree-popup" style={position} onKeyDown={event => {
    if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); close.current(); anchor.current?.querySelector("button")?.focus({ preventScroll: true }); }
  }}>{children}</div>, document.body);
}
    catch (error) { setMessage(error instanceof Error ? error.message : t("streamTarget.restartFailed")); }
    finally { request.current = false; setBusy(false); }
  }

  const status = !live ? "returnLive" : !connected || runtimeError || !runtime?.control.available || !stm ? "statusUnavailable"
    : restarting ? "restarting" : stm.activation.state === "restart_failed" ? "restartFailed"
    : stm.activation.state === "restart_required" ? "pending" : stm.state !== "RUNNING" || stm.ready === false ? "serviceNotRunning"
    : saved?.rule.enabled === false || saved?.rule.observe === false ? "disabled"
    : confirmed ? "confirmed" : "waiting";
  return <aside ref={panel} tabIndex={-1} className={`stream-target-panel${docked ? " is-docked-settings" : ""}`} aria-busy={busy} aria-label={t("streamTarget.title")} onKeyDown={event => {
    if (!docked && event.key === "Escape") { event.stopPropagation(); leave(onClose); }
  }}>
    {!docked && <PaneHeader className="stream-target-header" title={t("streamTarget.title")} icon="monitoringSettings" actions={<IconActionButton icon="close" label={t("streamTarget.close")} disabled={busy} onClick={() => leave(onClose)} />} />}
    <div className="stream-target-content">
