import type { AlertMetricDefinition, AlertRule } from "../types/api";
import { conditionProtocolPatch, conditionTypePatch, isSelectableMetric } from "./alertConditionEditing";

/** One target condition, using the same field semantics as the shared-policy table. */
export function AlertConditionEditor({ rule, metrics, protocols, flowRoles, busy, lockedIdentity = false, onChange }: {
  rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>;
  busy: boolean; lockedIdentity?: boolean; onChange: (rule: AlertRule) => void;
}) {
  const { t } = useI18n();
  const type = rule.type ?? "threshold", target = rule.target ?? "any";
  const change = (patch: Partial<AlertRule>) => onChange({ ...rule, ...patch });
  const candidates = metrics.filter(metric => isSelectableMetric(metric.key, target, rule.proto));
  const shortLabels: Record<string, string> = { trigger: "policyTree.occur", recovery: "policyTree.recovery", triggerDelay: "policyTree.triggerShort", recoveryDelay: "policyTree.recoverShort", missing: "conditionEditor.missingShort", inactive: "conditionEditor.inactiveShort" };
  const field = (key: string, content: ReactNode) => <label className={"policy-condition-field policy-condition-field-" + key} title={t("conditionEditor." + key)}>
    <span className="policy-condition-label">{t(shortLabels[key] ?? "conditionEditor." + key)}</span>{content}</label>;
  const number = (key: keyof AlertRule, label: string, fallback?: number, min?: number) => field(label,
    <><input type="number" step="any" min={min} aria-label={t("conditionEditor." + label)} data-condition-field={key} value={rule[key] as number | undefined ?? fallback ?? ""} disabled={busy}
      onChange={event => change({ [key]: event.target.value === "" ? undefined : Number(event.target.value) })} />{String(key).endsWith("_sec") && <span className="policy-condition-unit">s</span>}</>);
  return <div className="policy-condition-editor" role="group" aria-label={t("policyTree.editCondition")}>
    <div className="policy-condition-scroll" tabIndex={0} aria-label={t("policyTree.editCondition")}><div className="policy-condition-fields">
      {lockedIdentity && field("enabled", <input type="checkbox" checked={rule.enabled !== false} disabled={busy} onChange={event => change({ enabled: event.target.checked })} />)}
      {field("metric", <select aria-label={t("conditionEditor.metric")} data-condition-field="metric" value={rule.metric} disabled={busy || lockedIdentity} onChange={event => change({ metric: event.target.value })}>
        {!candidates.some(metric => metric.key === rule.metric) && <option value={rule.metric}>{rule.metric} · {t("conditionEditor.unavailable")}</option>}
        {candidates.map(metric => <option key={metric.key} value={metric.key}>{metric.key}{metric.unit ? " (" + metric.unit + ")" : ""}</option>)}
      </select>)}
      {field("type", <><Icon name="alertRules" size={13} /><select aria-label={t("conditionEditor.type")} data-condition-field="type" value={type} disabled={busy || lockedIdentity} onChange={event => change(conditionTypePatch(rule, event.target.value as AlertRule["type"]))}>
        <option value="threshold">{t("conditionEditor.threshold")}</option><option value="counter_delta">{t("conditionEditor.counterDelta")}</option>
        {(type === "availability" || rule.proto !== "UDP" && rule.proto !== "TCP") && <option value="availability">{t("conditionEditor.availability")}</option>}
      </select></>)}
      {type !== "availability" && field("operator", <select aria-label={t("conditionEditor.operator")} data-condition-field="operator" value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={event => change({ operator: event.target.value as AlertRule["operator"] })}>{[">", ">=", "<", "<=", "==", "!="].map(operator => <option key={operator}>{operator}</option>)}</select>)}
      {type === "availability" ? number("inactive_after_sec", "inactive", undefined, 0)
        : number(type === "counter_delta" ? "delta_threshold" : "error_threshold", "trigger")}
      {type === "threshold" && <>
        {number("recover_threshold", "recovery", rule.error_threshold)}
        {number("trigger_after_sec", "triggerDelay", 0, 0)}
      </>}
      {type !== "availability" && <>
        {number("recover_after_sec", "recoveryDelay", type === "counter_delta" ? 3 : 0, 0)}
        {number("missing_after_sec", "missing", 0, 0)}
      </>}
      {field("severity", <select className="policy-severity-badge" data-severity={rule.severity ?? "warning"} aria-label={t("conditionEditor.severity")} data-condition-field="severity" value={rule.severity ?? "warning"} disabled={busy} onChange={event => change({ severity: event.target.value })}>{["info", "warning", "error", "critical"].map(severity => <option key={severity}>{severity}</option>)}</select>)}
    </div></div>
    <details className="policy-condition-advanced">
      <summary aria-label={t("conditionEditor.advanced")} title={t("conditionEditor.advanced") + " · " + target + " · " + (rule.proto ?? "*")}><Icon name="more" size={16} /><span className="policy-condition-advanced-label">{t("conditionEditor.advanced")}</span></summary>
      <div className="policy-condition-fields">
        {field("id", <input data-condition-field="id" value={rule.id} disabled={busy || lockedIdentity} onChange={event => change({ id: event.target.value })} />)}
        {field("target", <select aria-label={t("conditionEditor.target")} data-condition-field="target" value={target} disabled={busy || lockedIdentity} onChange={event => change({ target: event.target.value as AlertRule["target"], ...(event.target.value !== "flow" ? { flow_roles: undefined } : {}) })}>{["flow", "stream", "interface", "any"].map(value => <option key={value}>{value}</option>)}</select>)}
        {field("protocol", <select aria-label={t("conditionEditor.protocol")} data-condition-field="proto" value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={event => change(conditionProtocolPatch(rule, event.target.value))}><option value="">{t("streamTarget.any")}</option>{protocols.map(proto => <option key={proto}>{proto}</option>)}</select>)}
        {field("roles", <input data-condition-field="flow_roles" value={(rule.flow_roles ?? []).join(", ")} disabled={busy || lockedIdentity || target !== "flow"} placeholder={(flowRoles[rule.proto ?? ""] ?? []).join(", ")} onChange={event => change({ flow_roles: event.target.value.split(",").map(value => value.trim()).filter(Boolean) })} />)}
        {field("indicator", <select aria-label={t("conditionEditor.indicator")} data-condition-field="indicator_category" value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={event => change({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">{t("conditionEditor.other")}</option><option value="quality">{t("conditionEditor.quality")}</option></select>)}
      </div>
    </details>
  </div>;
}
