          <span ref={menuAnchor}><IconActionButton icon="more" label={t("policyTree.commonActions")} className="maintenance-secondary-button policy-tree-action" aria-haspopup="dialog" aria-expanded={popup === "menu"} onClick={() => setPopup(popup === "menu" ? null : "menu")} /></span>
        </> })}
        {node("specific", t("policyTree.specific"), <div className="policy-tree-children">
          {legacy.map(ref => {
            const policy = document.policies.find(policy => policy.id === ref.policy_id);
            return <div key={ref.policy_id}>{node("adjustment:" + ref.policy_id, (policy?.title || ref.policy_id) + " · " + t("policyTree.existingAdjustments"),
              <div className="policy-tree-detail policy-tree-legacy-adjustments">{(policy?.conditions ?? []).map(base => <div className="policy-tree-adjustment" key={base.id}><h4>{base.id}</h4><AlertConditionEditor rule={{ ...conditionBaseValues(base), ...(ref.adjustments?.[base.id] ?? {}) }} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy || !active || ref.enabled === false} lockedIdentity onChange={next => {
                const fields: Array<keyof AlertRule> = ["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"];
                const baseValues = conditionBaseValues(base), currentValues = { ...baseValues, ...ref.adjustments?.[base.id] };
                const patch = { ...ref.adjustments?.[base.id] };
                for (const key of fields) {
                  if (next[key] === currentValues[key]) continue;
                  if (next[key] === undefined || next[key] === baseValues[key]) delete patch[key];
                  else Object.assign(patch, { [key]: next[key] });
                }
                const adjustments = { ...ref.adjustments }; if (Object.keys(patch).length) adjustments[base.id] = patch; else delete adjustments[base.id];
                updateRef(ref.policy_id, { adjustments });
              }} /></div>)}</div>, { className: "policy-tree-legacy-node", count: policy?.conditions.length ?? 0 })}</div>;
          })}
          {(["conditions", "additional_conditions"] as const).flatMap(key => (draft[key] ?? []).map((rule, index) => <div key={key + ":" + index}>{node("condition:" + key + ":" + index, rule.id,
            <div className="policy-tree-detail"><AlertConditionEditor rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy || !active || rule.enabled === false} onChange={next => {
              if (own.some(item => item !== rule && item.id === next.id)) { setMessage(t("policyTree.duplicateCondition")); return; }
              updateOwn(key, index, next);
            }} /></div>, { className: "policy-tree-branch policy-tree-condition" + (rule.enabled === false ? " is-disabled" : ""),
              check: check(t("policyTree.enableCondition", { name: rule.id }), rule.enabled !== false, enabled => updateOwn(key, index, { ...rule, enabled }), !active),
              actions: removeButton(() => updateOwn(key, index)) })}</div>))}
          {!own.length && !legacy.length && <p className="policy-tree-empty">{t("policyTree.noOwn")}</p>}
        </div>, { className: "policy-tree-category", count: own.length + legacy.length, actions: addButton(t("policyTree.addCondition"), () => {
          const index = (draft.conditions ?? []).length;
          setExpanded(current => ({ ...current, specific: true, ["condition:conditions:" + index]: true }));
          update({ conditions: [...(draft.conditions ?? []), newAlertCondition(target.proto, flowRoles, own, target.flowRoles)] });
        }) })}
      </div>
    </div>
    <div id={id + "-panel-effective"} role="tabpanel" aria-labelledby={id + "-tab-effective"} className="policy-tree-tab-panel" hidden={view !== "effective"}>
      <section className="policy-tree-effective" aria-label={t("policyTree.effective")} aria-live="polite"><h4>{t("policyTree.effective")} · {applicable.length}</h4><p className="policy-tree-hint">{t("policyTree.draft")}</p>
        {!applicable.length ? <p>{t(active ? "policyTree.none" : "policyTree.disabled")}</p> : <AlertConditionSummary rules={applicable.map(item => item.rule)} sources={applicable.map(sourceTitle)} />}
      </section>
    </div>
  </section>;
}

function PolicyTreeNode({ nodeKey, title, open, onToggle, className = "", check, count, badge, actions, children }: {
  nodeKey: string; title: string; open: boolean; onToggle: () => void; className?: string;
  check?: ReactNode; count?: number; badge?: ReactNode; actions?: ReactNode; children: ReactNode;
}) {
  const id = useId(), { t } = useI18n();
  return <div className={"policy-tree-node " + className + (open ? " is-open" : "")} data-policy-node={nodeKey}>
    <div className="policy-tree-row">
      <button type="button" className={"policy-tree-toggle" + (open ? " is-open" : "")} aria-label={t(open ? "policyTree.collapse" : "policyTree.expand", { name: title })} aria-expanded={open} aria-controls={id} onClick={onToggle}><Icon name="expand" size={15} /></button>
      {check}
      <button type="button" className="policy-tree-title" title={title} aria-expanded={open} aria-controls={id} onClick={onToggle}>{title}</button>
      {badge}
      {count !== undefined && <span className="policy-tree-count">{count}</span>}
      <span className="policy-tree-row-actions">{actions}</span>
    </div>
    <div id={id} className="policy-tree-node-body" hidden={!open}>{children}</div>
  </div>;
}

function panelPosition(panel: HTMLElement | null, host: HTMLElement): number {
  return (panel?.getBoundingClientRect().top ?? 0) - (host === document.scrollingElement ? 0 : host.getBoundingClientRect().top) + host.scrollTop;
}

function scrollHost(element: HTMLElement | null): HTMLElement | null {
  for (let current = element?.parentElement; current; current = current.parentElement) {
    if (/(auto|scroll)/.test(getComputedStyle(current).overflowY) && current.scrollHeight > current.clientHeight + 1) return current;
  }
  return document.scrollingElement as HTMLElement | null;
}

export function AlertConditionSummary({ rules, source, sources }: { rules: AlertRule[]; source?: string; sources?: string[] }) {
  const { t } = useI18n();
  return <ul className="policy-tree-condition-list">{rules.map((rule, index) => <li key={index} className={rule.enabled === false ? "is-disabled" : ""}>
    <div className="policy-condition-heading"><strong title={rule.id}>{rule.id}</strong>
      <small>{rule.proto || "*"} · {rule.target ?? "any"}{rule.flow_roles?.length ? " · " + rule.flow_roles.join(", ") : ""} · {t("conditionEditor." + (rule.type === "counter_delta" ? "counterDelta" : rule.type === "availability" ? "availability" : "threshold"))}</small>
      {(sources?.[index] || source) && <small className="policy-condition-source" title={sources?.[index] ?? source}>{sources?.[index] ?? source}</small>}
      <span className="policy-severity-badge" data-severity={rule.severity ?? "warning"}>{rule.severity ?? "warning"}</span>
      {rule.enabled === false && <small>{t("policyTree.conditionOff")}</small>}
    </div>
    <div className="policy-condition-expression"><span>{rule.metric} · {t("policyTree.occur")}: {rule.type === "availability" ? `${t("policyTree.inactive")} ${rule.inactive_after_sec}s` : `${rule.operator ?? ">"} ${rule.type === "counter_delta" ? rule.delta_threshold ?? 0 : rule.error_threshold ?? 0}`}</span>
      <span>{t("policyTree.recovery")}: {rule.type === "counter_delta" ? `${rule.recover_after_sec ?? 3}s` : rule.type === "availability" ? t("policyTree.packetReceived") : rule.recover_threshold ?? rule.error_threshold ?? 0}</span>
      {rule.type === "threshold" || !rule.type ? <span>{t("policyTree.triggerShort")}: {rule.trigger_after_sec ?? 0}s</span> : null}
      {rule.type !== "availability" && <><span>{t("policyTree.recoverShort")}: {rule.recover_after_sec ?? (rule.type === "counter_delta" ? 3 : 0)}s</span><span>{t("policyTree.missing")}: {rule.missing_after_sec ?? 0}s</span></>}
    </div>
  </li>)}</ul>;
}

export function targetPolicyModeLabel(mode: "inherit" | AlertBinding["mode"]) { return mode === "inherit" ? "Inherited default" : mode === "disabled" ? "Alert evaluation disabled" : mode === "composed" ? "Target conditions" : mode === "shared" ? "Common policy" : mode === "individual" ? "Target-specific policy" : "Common policy + adjustments"; }

