import type { AlertRule } from "../types/api";

export function conditionTypePatch(rule: AlertRule, next: AlertRule["type"]): Partial<AlertRule> {
  if (next === "availability") return { type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 };
  if (next === "counter_delta") return { type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined };
  return { type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined };
}

export function conditionProtocolPatch(rule: AlertRule, proto: string): Partial<AlertRule> {
  const patch: Partial<AlertRule> = { proto: proto || undefined };
  if (proto === "UDP" || proto === "TCP") {
    patch.flow_roles = undefined;
    if (rule.type === "availability") Object.assign(patch, { type: "threshold", metric: "packet_count.window", operator: "==", error_threshold: 0, recover_threshold: 0, inactive_after_sec: undefined });
  }
  return patch;
}

export function isSelectableMetric(key: string, target: string, proto: string | undefined) {
  const interfaceMetric = key.startsWith("link.") || key.startsWith("rx.") || key.startsWith("tx.");
  if (target === "interface") return interfaceMetric;
  if (interfaceMetric) return false;
  const universal = key.startsWith("bitrate.") || key.startsWith("packet_rate.") || key.startsWith("packet_count.");
  const mediaCommon = universal || key.startsWith("interval.");
  if (!proto) return universal || key.startsWith("duration.");
  if (proto === "HLS") return key.startsWith("hls.preview.");
