import { useRef, useState } from "react";
import { useI18n } from "../i18n";
import { Icon } from "./ui/Icon";
import { IconActionButton } from "./ui/IconActionButton";

/** Keep roles as an array; punctuation in a custom draft is normalized only on commit. */
export function FlowRolePicker({ roles = [], options, allowCustom, disabled, onChange }: {
  roles?: string[]; options: string[]; allowCustom: boolean; disabled: boolean; onChange: (roles: string[] | undefined) => void;
}) {
  const { t } = useI18n();
  const [draft, setDraft] = useState("");
  const picker = useRef<HTMLDivElement>(null);
  const available = [...new Set(options)].filter(role => !roles.includes(role));
  const update = (next: string[]) => {
    if (next.length !== roles.length || next.some((role, index) => role !== roles[index])) onChange(next.length ? next : undefined);
  };
  const addCustom = () => {
    if (disabled) return;
    const additions = draft.split(",").map(role => role.trim()).filter(Boolean);
    if (additions.length) update([...new Set([...roles, ...additions])]);
    setDraft("");
  };
  return <div ref={picker} className="policy-role-picker" role="group" aria-label={t("conditionEditor.roles")}>
    <div className="policy-role-selected">
      {roles.map(role => <span key={role} className={"alerts-id-chip" + (!allowCustom && !options.includes(role) ? " is-orphan" : "")} data-flow-role={role}
        title={!allowCustom && !options.includes(role) ? t("conditionEditor.roleUnsupported", { name: role }) : role}>
        <span>{role}</span><button type="button" disabled={disabled} aria-label={t("conditionEditor.removeRole", { name: role })} data-tooltip={t("conditionEditor.removeRole", { name: role })} onClick={() => {
          update(roles.filter(current => current !== role));
          requestAnimationFrame(() => picker.current?.querySelector<HTMLElement>("select:not(:disabled), input:not(:disabled), button:not(:disabled)")?.focus({ preventScroll: true }));
        }}><Icon name="close" size={12} /></button>
      </span>)}
      {!roles.length && <span className="policy-role-empty">{t("conditionEditor.allRoles")}</span>}
    </div>
    <select data-condition-field="flow_roles" aria-label={t("conditionEditor.addRole")} value="" disabled={disabled || !available.length}
      onChange={event => { if (available.includes(event.target.value)) update([...roles, event.target.value]); }}>
      <option value="">{t(available.length ? "conditionEditor.chooseRole" : "conditionEditor.noMoreRoles")}</option>
      {available.map(role => <option key={role} value={role}>{role}</option>)}
    </select>
    {allowCustom && <div className="policy-role-custom">
      <input aria-label={t("conditionEditor.customRoles")} data-role-custom value={draft} disabled={disabled} placeholder={t("conditionEditor.customRolesHint")}
        onChange={event => setDraft(event.target.value)} onBlur={addCustom} onKeyDown={event => { if (event.key === "Enter" && !event.nativeEvent.isComposing) { event.preventDefault(); addCustom(); } }} />
      <IconActionButton icon="add" label={t("conditionEditor.addCustomRoles")} disabled={disabled || !draft.trim()} onClick={addCustom} />
    </div>}
  </div>;
}
EOF
